#!/usr/bin/env bash
# Sans Password Manager (SPM)
# Portable Bash + GPG password manager with encrypted vault.
# Dependencies: bash, gpg, openssl, base64, curl (for update)
# Copyright 2025-2026 Sansyourways and contributors
# SPDX-License-Identifier: Apache-2.0

set -o errexit
set -o nounset
set -o pipefail

VERSION="4.8.0"

# ----- Repo info for update check --------------------------------------------

# Adjust these to match your GitHub repo
REPO_OWNER="sansyourways"
REPO_NAME="Sans_Password_Manager"
REPO_API_URL="https://api.github.com/repos/${REPO_OWNER}/${REPO_NAME}/releases/latest"

# Global master password (in-memory only, per process)
MASTER_PW=""
VAULT_KEY=""
# Registry of temp files holding decrypted vault material.
# A file (not an array) because make_tmp is called via $(...) subshells,
# whose variable writes would be discarded. Wiped by cleanup() on any exit.
# Deliberately not "${TMPDIR:-/tmp}/.spm_tmpreg.$$": that path is guessable, and
# cleanup() feeds every line of this file to shred. A local user who pre-created
# it chose which files SPM destroyed. mktemp gives an unpredictable name and
# fails if it somehow exists. Created here rather than on first use because
# make_tmp runs inside command substitution, where an assignment would be lost.
SPM_TMP_REGISTRY="$(mktemp "${TMPDIR:-/tmp}/.spm_tmpreg.XXXXXX" 2>/dev/null)" || SPM_TMP_REGISTRY=""
if [ -n "$SPM_TMP_REGISTRY" ]; then
	chmod 600 "$SPM_TMP_REGISTRY" 2>/dev/null || true
fi
# Language: en / id (can be pre-set via env SPM_LANG)
SPM_LANG="${SPM_LANG:-}"

# Environment detection / package manager
ENV_FLAVOR=""   # termux / linux / macos / other
PKG_TYPE=""     # pkg / apt / pacman / dnf / apk / brew / none

# ----- Script + vault path detection -----------------------------------------

# Try to resolve the script path for copying into portable/save bundles.
SCRIPT_SRC="$0"
if [ ! -f "$SCRIPT_SRC" ]; then
	if command -v "$0" >/dev/null 2>&1; then
		SCRIPT_SRC="$(command -v "$0")"
	fi
fi

DEFAULT_VAULT_PATH="$HOME/.spm_vault.gpg"
SPM_CONFIG_DIR="${XDG_CONFIG_HOME:-$HOME/.config}/spm"
SPM_DATA_DIR="${XDG_DATA_HOME:-$HOME/.local/share}/spm"
SPM_PROFILE_FILE="$SPM_CONFIG_DIR/vaults.tsv"
SPM_DEFAULT_PROFILE_FILE="$SPM_CONFIG_DIR/default-profile"
SPM_AUTOUPDATE_FILE="$SPM_CONFIG_DIR/auto-update.conf"

if [ -z "${SPM_VAULT_PROFILE:-}" ] && [ -f "$SPM_DEFAULT_PROFILE_FILE" ]; then
	IFS= read -r SPM_VAULT_PROFILE < "$SPM_DEFAULT_PROFILE_FILE" || SPM_VAULT_PROFILE=""
fi

profile_vault_path() {
	local profile="$1"
	[ -f "$SPM_PROFILE_FILE" ] || return 1
	awk -F '\t' -v name="$profile" '$1 == name { print $2; found=1; exit } END { if (!found) exit 1 }' "$SPM_PROFILE_FILE"
}

# Vault resolution logic:
# 1) If PASSWORD_VAULT is set → use it
# 2) Else if ./spm_vault.gpg exists → use it (portable bundle case)
# 3) Else → use ~/.spm_vault.gpg
if [ -n "${PASSWORD_VAULT:-}" ]; then
	VAULT_FILE="$PASSWORD_VAULT"
elif [ -n "${SPM_VAULT_PROFILE:-}" ]; then
	VAULT_FILE="$(profile_vault_path "$SPM_VAULT_PROFILE")" || {
		printf "Unknown vault profile: %s\n" "$SPM_VAULT_PROFILE" >&2
		exit 1
	}
elif [ -f "./spm_vault.gpg" ]; then
	VAULT_FILE="./spm_vault.gpg"
else
	VAULT_FILE="$DEFAULT_VAULT_PATH"
fi

# Recovery-related paths (per vault)
RECOVERY_FILE="${VAULT_FILE}.recovery"
# Private key now always generated in the current working directory
RECOVERY_PRIV_DEFAULT="./spm_recovery_private.pem"

# Use $EDITOR or fallback
EDITOR_CMD="${EDITOR:-nano}"

# ----- Utility helpers --------------------------------------------------------

die() {
	printf 'Error: %s\n' "$*" >&2
	exit 1
}

require_cmd() {
	command -v "$1" >/dev/null 2>&1 || die "Required command '$1' not found. Install it first."
}

now_iso() {
	if date -u +"%Y-%m-%dT%H:%M:%SZ" >/dev/null 2>&1; then
		date -u +"%Y-%m-%dT%H:%M:%SZ"
	else
		date
	fi
}

# Vault records are TAB-delimited, one line each. A field carrying a raw TAB or
# newline silently splits the record: a password pasted with a TAB used to be
# stored whole but read back truncated at the TAB, with the remainder bleeding
# into the next column. Collapse both to a space before any field is written.
sanitize_field() {
	# Collapse every character Python's splitlines() honours, not just the three
	# ASCII ones: the web server reads this vault back with splitlines(), so a
	# field holding U+2028 was written here and silently split there.
	printf '%s' "$1" \
		| tr '\t\r\n\v\f\034\035\036' '        ' \
		| sed 's/\xc2\x85/ /g; s/\xe2\x80\xa8/ /g; s/\xe2\x80\xa9/ /g'
}

sanitize_url() {
	# The URL field is the one vault field that becomes a clickable link in Web
	# Mode and, later, an auto-fill target for the browser extension. Both make
	# a non-http(s) scheme dangerous -- "javascript:" in a rendered href, or a
	# "data:" document the extension would treat as a login origin -- so the
	# scheme is an allowlist rather than a denylist. An empty value is valid:
	# the field is optional and always has been.
	local raw
	raw="$(sanitize_field "$1" | sed 's/^[[:space:]]*//; s/[[:space:]]*$//')"
	[ -n "$raw" ] || { printf ''; return 0; }
	if ! printf '%s' "$raw" | grep -Eqi '^https?://[^[:space:]/]+'; then
		return 1
	fi
	printf '%s' "$raw"
}

validate_bundle_name() {
	local name="$1"
	case "$name" in
		""|.|..|-*|*/*|*\\*) die "Invalid bundle name. Use a simple file name without slashes or leading dashes." ;;
	esac
	# Reject control characters; they make archive names and cleanup targets
	# ambiguous even when shell quoting is otherwise correct.
	if printf '%s' "$name" | LC_ALL=C grep -q '[[:cntrl:]]'; then
		die "Invalid bundle name. Control characters are not allowed."
	fi
}

# Octal permission bits for a file, or empty if they cannot be read.
# GNU coreutils and BSD/macOS stat disagree on the flag, so try both.
file_mode() {
	local f="$1"
	stat -c '%a' "$f" 2>/dev/null && return 0
	stat -f '%Lp' "$f" 2>/dev/null && return 0
	printf ''
}

# True when a mode grants any group or other bit, i.e. anything but 0x00.
# Handles both 3-digit (600) and 4-digit (0600) stat output.
mode_is_exposed() {
	local mode="$1"
	[ -n "$mode" ] || return 1
	[ "${mode: -2}" != "00" ]
}

# Resolve a path to its canonical absolute form so the same file reached by two
# different paths is not audited (or reported) twice.
canon_path() {
	local p="$1"
	realpath "$p" 2>/dev/null && return 0
	readlink -f "$p" 2>/dev/null && return 0
	# Older macOS has neither; fall back to a subshell cd so the caller still
	# gets an absolute path and this function never changes our own cwd.
	local d b
	d="$(dirname "$p")"
	b="$(basename "$p")"
	( cd "$d" 2>/dev/null && printf '%s/%s\n' "$(pwd -P)" "$b" ) 2>/dev/null && return 0
	printf '%s\n' "$p"
}

# Every sensitive file 'doctor' should audit, one per line, de-duplicated.
#
# RECOVERY_PRIV_DEFAULT is cwd-relative by design (the key is generated in
# whatever directory you ran 'init' from), so checking only that path lets an
# exposed key in another directory pass unnoticed: run from $HOME and doctor
# reports OK while a world-readable copy sits in the project folder. Look in
# the cwd, alongside the vault, next to the script, and anywhere shallow
# under $HOME, matching the same glob .gitignore uses so renamed or spare
# keys are caught too.
sensitive_files() {
	local vault_dir script_dir d g p
	vault_dir="$(dirname "$VAULT_FILE")"
	script_dir="$(dirname "$0")"
	{
		printf '%s\n' "$VAULT_FILE" "${VAULT_FILE}.bak" "$RECOVERY_FILE"
		# The cwd and the vault's directory may sit outside $HOME entirely
		# (portable bundle on removable media), so check them explicitly.
		for d in "." "$vault_dir" "$script_dir"; do
			for g in "$d"/spm_recovery_private*.pem; do
				if [ -f "$g" ]; then
					printf '%s\n' "$g"
				fi
			done
		done
		# Copies of the key get left behind in project folders and backup
		# directories, where a directory-list check would never look. Bounded
		# depth keeps this well under a second on a normal home directory.
		find "$HOME" -maxdepth 4 -type f -name 'spm_recovery_private*.pem' 2>/dev/null || true
	} | while IFS= read -r p; do
		[ -f "$p" ] || continue
		printf '%s\t%s\n' "$(canon_path "$p")" "$p"
	done | awk -F '\t' '!seen[$1]++ { print $2 }'
}

make_tmp() {
	require_cmd mktemp
	local tmp
	[ -n "${SPM_TMP_REGISTRY:-}" ] || die "Temporary-file registry is unavailable; refusing to write decrypted data."
	tmp="$(mktemp "${TMPDIR:-/tmp}/spm.XXXXXX")"
	chmod 600 "$tmp" 2>/dev/null || true
	printf '%s\n' "$tmp" >>"$SPM_TMP_REGISTRY" 2>/dev/null || true
	printf '%s\n' "$tmp"
}

secure_wipe() {
	local f="$1"
	[ -f "$f" ] || return 0

	if command -v shred >/dev/null 2>&1; then
		shred -u "$f" || rm -f "$f" || true
	else
		rm -f "$f" || true
	fi
}

print_banner() {
	cat <<'EOF'

      *******            ***** **         *****   **    **
    *       ***       ******  ****     ******  ***** *****
   *         **      **   *  *  ***   **   *  *  ***** *****
   **        *      *    *  *    *** *    *  *   * **  * **
    ***                 *  *      **     *  *    *     *
   ** ***              ** **      **    ** **    *     *
    *** ***            ** **      **    ** **    *     *
      *** ***        **** **      *     ** **    *     *
        *** ***     * *** **     *      ** **    *     *
          ** ***       ** *******       ** **    *     **
           ** **       ** ******        *  **    *     **
            * *        ** **               *     *      **
  ***        *         ** **           ****      *      **
 *  *********          ** **          *  *****           **
*     *****       **   ** **         *     **
*                ***   *  *          *
 **               ***    *            **
                   ******
                     ***

EOF
	local year
	year="$(date +%Y 2>/dev/null || echo "2025")"
	printf "Sans Password Manager (SPM)  v%s  \u00a9 %s Sansyourways and contributors · Apache-2.0\n\n" "$VERSION" "$year"
}

pause_menu() {
	if [ "${SPM_LANG}" = "id" ]; then
		printf '\nTekan Enter untuk kembali ke menu...'
	else
		printf '\nPress Enter to return to menu...'
	fi
	read -r _ || true
}

cleanup() {
	if [ -n "${MASTER_PW:-}" ]; then
		MASTER_PW="$(printf '%*s' "${#MASTER_PW}" '' | tr ' ' 'X')"
	fi
	unset MASTER_PW 2>/dev/null || true
	if [ -n "${VAULT_KEY:-}" ]; then
		VAULT_KEY="$(printf '%*s' "${#VAULT_KEY}" '' | tr ' ' 'X')"
	fi
	unset VAULT_KEY 2>/dev/null || true

	# Never leave decrypted vault material behind, even on error or interrupt.
	if [ -n "${SPM_TMP_REGISTRY:-}" ] && [ -f "$SPM_TMP_REGISTRY" ]; then
		local f
		while IFS= read -r f; do
			[ -n "$f" ] && secure_wipe "$f"
		done <"$SPM_TMP_REGISTRY"
		rm -f "$SPM_TMP_REGISTRY" 2>/dev/null || true
	fi

	# Restore terminal echo in case we died inside a hidden prompt.
	if [ -t 0 ]; then
		stty echo 2>/dev/null || true
	fi
}

# Ctrl-C must abort the operation, not fall through with a wiped master password.
on_interrupt() {
	trap - INT
	cleanup
	printf '\n' >&2
	exit 130
}

# SIGTERM/SIGHUP do not run the EXIT trap on their own, so handle them
# explicitly or a killed process would strand a decrypted vault on disk.
on_terminate() {
	trap - TERM HUP
	cleanup
	exit 143
}

trap cleanup EXIT
trap on_interrupt INT
trap on_terminate TERM HUP

# ----- Environment & auto-install -------------------------------------------

detect_env() {
	if [ -n "${TERMUX_VERSION:-}" ] || [ -d "/data/data/com.termux/files/usr" ]; then
		ENV_FLAVOR="termux"
		PKG_TYPE="pkg"
		return
	fi

	local uname_s
	uname_s="$(uname -s 2>/dev/null || echo "Unknown")"

	case "$uname_s" in
		Darwin)
			ENV_FLAVOR="macos"
			if command -v brew >/dev/null 2>&1; then
				PKG_TYPE="brew"
			else
				PKG_TYPE="none"
			fi
			;;
		Linux)
			ENV_FLAVOR="linux"
			if command -v apt-get >/dev/null 2>&1; then
				PKG_TYPE="apt"
			elif command -v pacman >/dev/null 2>&1; then
				PKG_TYPE="pacman"
			elif command -v dnf >/dev/null 2>&1; then
				PKG_TYPE="dnf"
			elif command -v apk >/dev/null 2>&1; then
				PKG_TYPE="apk"
			else
				PKG_TYPE="none"
			fi
			;;
		*)
			ENV_FLAVOR="other"
			PKG_TYPE="none"
			;;
	esac
}

install_tool() {
	local tool="$1"
	local candidates="$tool"
	local rc=1

	case "$tool" in
		gpg) candidates="gpg gnupg gnupg2" ;;
		openssl) candidates="openssl" ;;
		curl) candidates="curl" ;;
		zip) candidates="zip" ;;
		xclip) candidates="xclip" ;;
		wl-copy) candidates="wl-clipboard" ;;
		termux-clipboard-set) candidates="termux-api" ;;
		python3) candidates="python3 python" ;;
	esac

	set +e
	for pkg in $candidates; do
		case "$PKG_TYPE" in
			pkg)
				pkg install -y "$pkg" >/dev/null 2>&1
				rc=$?
				;;
			apt)
				if command -v sudo >/dev/null 2>&1; then
					sudo apt-get install -y "$pkg" >/dev/null 2>&1
				else
					apt-get install -y "$pkg" >/dev/null 2>&1
				fi
				rc=$?
				;;
			pacman)
				if command -v sudo >/dev/null 2>&1; then
					sudo pacman -Sy --noconfirm "$pkg" >/dev/null 2>&1
				else
					pacman -Sy --noconfirm "$pkg" >/dev/null 2>&1
				fi
				rc=$?
				;;
			dnf)
				if command -v sudo >/dev/null 2>&1; then
					sudo dnf install -y "$pkg" >/dev/null 2>&1
				else
					dnf install -y "$pkg" >/dev/null 2>&1
				fi
				rc=$?
				;;
			apk)
				if command -v sudo >/dev/null 2>&1; then
					sudo apk add "$pkg" >/dev/null 2>&1
				else
					apk add "$pkg" >/dev/null 2>&1
				fi
				rc=$?
				;;
			brew)
				brew install "$pkg" >/dev/null 2>&1
				rc=$?
				;;
			*)
				rc=1
				;;
		esac
		if [ "$rc" -eq 0 ]; then
			break
		fi
	done
	set -e
	return "$rc"
}

loading_line() {
	local msg="$1"
	printf "%s" "$msg"
	for _ in 1 2 3; do
		printf "."
		sleep 0.15
	done
	printf "\n"
}

install_clipboard_helpers() {
	printf "\n"
	if [ "$SPM_LANG" = "id" ]; then
		printf "Pemeriksaan helper clipboard (opsional, untuk auto-copy & auto-clean):\n"
	else
		printf "Checking clipboard helpers (optional, for auto-copy & auto-clean):\n"
	fi

	if command -v pbcopy >/dev/null 2>&1; then
		printf "  [\033[0;32m✔\033[0m] pbcopy (macOS clipboard)\n"
	fi

	if [ "$ENV_FLAVOR" = "termux" ]; then
		printf "  [ ] termux-clipboard-set - checking/installing...\n"
		if command -v termux-clipboard-set >/dev/null 2>&1; then
			printf "\r  [\033[0;32m✔\033[0m] termux-clipboard-set available\n"
		else
			if install_tool "termux-clipboard-set"; then
				if command -v termux-clipboard-set >/dev/null 2>&1; then
					printf "\r  [\033[0;32m✔\033[0m] termux-clipboard-set installed\n"
				else
					printf "\r  [\033[0;31m✖\033[0m] termux-clipboard-set install ok but command not found\n"
				fi
			else
				printf "\r  [\033[0;31m✖\033[0m] termux-clipboard-set install failed\n"
			fi
		fi
	fi

	local opt_tools=("xclip" "wl-copy")
	local t
	for t in "${opt_tools[@]}"; do
		printf "  [ ] %-16s - checking/installing..." "$t"
		if command -v "$t" >/dev/null 2>&1; then
			printf "\r  [\033[0;32m✔\033[0m] %-16s - available          \n" "$t"
		else
			if [ "$PKG_TYPE" != "none" ]; then
				if install_tool "$t"; then
					if command -v "$t" >/dev/null 2>&1; then
						printf "\r  [\033[0;32m✔\033[0m] %-16s - installed           \n" "$t"
					else
						printf "\r  [\033[0;31m✖\033[0m] %-16s - install ok but not found\n" "$t"
					fi
				else
					printf "\r  [\033[0;31m✖\033[0m] %-16s - install failed       \n" "$t"
				fi
			else
				printf "\r  [\033[0;31m✖\033[0m] %-16s - no package manager   \n" "$t"
			fi
		fi
	done
	printf "\n"
}

ensure_requirements() {
	detect_env

	clear
	print_banner

	printf "Environment check\n"
	printf "  Detected environment : %s\n" "${ENV_FLAVOR:-unknown}"
	printf "  Package manager type : %s\n\n" "${PKG_TYPE:-none}"

	loading_line "Checking and installing required tools"

	local tools=("gpg" "openssl" "curl" "zip")
	local t

	for t in "${tools[@]}"; do
		printf "  [ ] %-8s - checking..." "$t"
		sleep 0.1

		if command -v "$t" >/dev/null 2>&1; then
			printf "\r  [\033[0;32m✔\033[0m] %-8s - available     \n" "$t"
			continue
		fi

		if [ "$PKG_TYPE" = "none" ]; then
			printf "\r  [\033[0;31m✖\033[0m] %-8s - missing (no package manager detected)\n" "$t"
		else
			printf "\r  [ ] %-8s - installing..." "$t"
			if install_tool "$t"; then
				if command -v "$t" >/dev/null 2>&1; then
					printf "\r  [\033[0;32m✔\033[0m] %-8s - installed      \n" "$t"
				else
					printf "\r  [\033[0;31m✖\033[0m] %-8s - install ok but command not found\n" "$t"
				fi
			else
				printf "\r  [\033[0;31m✖\033[0m] %-8s - install failed, please install manually\n" "$t"
			fi
		fi
		sleep 0.1
	done

	for t in "${tools[@]}"; do
		if ! command -v "$t" >/dev/null 2>&1; then
			printf "\nRequired tool '%s' is still missing. Please install it manually and rerun SPM.\n" "$t"
			exit 1
		fi
	done

	install_clipboard_helpers

	printf "\n"
	loading_line "Preparing language selection"
	sleep 0.2
	clear
}

choose_language() {
	if [ -n "${SPM_LANG}" ]; then
		case "$SPM_LANG" in
			id|ID) SPM_LANG="id" ;;
			*) SPM_LANG="en" ;;
		esac
		return
	fi

	print_banner
	printf "Language? (en/id) [default: en]: "
	read -r lang_in || true

	case "$lang_in" in
		id|ID|2)
			SPM_LANG="id"
			;;
		*)
			SPM_LANG="en"
			;;
	esac
}

# ----- Terms & Privacy Consent ----------------------------------------------

ensure_policy_consent() {
	# You can change this to be per-project if you want, but HOME-based is simple & portable
	SPM_CONSENT_FILE="${HOME}/.spm_spm_consent"

	# If already accepted, just return
	if [ -f "$SPM_CONSENT_FILE" ]; then
		if grep -q '^ACCEPTED=1' "$SPM_CONSENT_FILE" 2>/dev/null; then
			return
		fi
	fi

	clear
	print_banner

	if [ "$SPM_LANG" = "id" ]; then
		cat <<'EOF'
[PERJANJIAN PENGGUNA]

Sebelum menggunakan Sans Password Manager (SPM), kamu harus
menyetujui:

  • Syarat & Ketentuan Layanan (Terms & Conditions)
  • Kebijakan Privasi (Privacy Policy)

Dokumen resmi:
  • TERMS & CONDITIONS:
    https://github.com/sansyourways/Sans_Password_Manager/blob/main/docs/TERMS_AND_CONDITIONS.md

  • PRIVACY POLICY:
    https://github.com/sansyourways/Sans_Password_Manager/blob/main/docs/PRIVACY_POLICY.md

Silakan baca dokumen tersebut di browser kamu.

Tanpa persetujuan, kamu tidak dapat menggunakan aplikasi ini.

Apakah kamu sudah membaca dan SETUJU dengan
Syarat & Ketentuan + Kebijakan Privasi di atas?
Ketik: yes / y / ya untuk menyetujui.
EOF
		printf "\nJawaban (yes/ya/y atau lainnya untuk TIDAK): "
	else
		cat <<'EOF'
[USER AGREEMENT]

Before using Sans Password Manager (SPM), you must agree to:

  • Terms & Conditions of Service
  • Privacy Policy

Official documents:
  • TERMS & CONDITIONS:
    https://github.com/sansyourways/Sans_Password_Manager/blob/main/docs/TERMS_AND_CONDITIONS.md

  • PRIVACY POLICY:
    https://github.com/sansyourways/Sans_Password_Manager/blob/main/docs/PRIVACY_POLICY.md

Please open and read these documents in your browser.

Without your consent, you cannot use this application.

Have you read and do you AGREE to the Terms & Conditions
and Privacy Policy above?
Type: yes / y to accept.
EOF
		printf "\nAnswer (yes/y to accept, anything else to decline): "
	fi

	read -r ans || ans=""

	# Normalize to lowercase
	ans_lc=$(printf '%s' "$ans" | tr '[:upper:]' '[:lower:]')

	if [ "$ans_lc" = "yes" ] || [ "$ans_lc" = "y" ] || [ "$ans_lc" = "ya" ]; then
		# Record consent
		{
			printf 'ACCEPTED=1\n'
			printf 'DATE_UTC=%s\n' "$(date -u +"%Y-%m-%dT%H:%M:%SZ" 2>/dev/null || date)"
			printf 'VERSION=%s\n' "$VERSION"
			printf 'LANG=%s\n' "$SPM_LANG"
		} > "$SPM_CONSENT_FILE" 2>/dev/null || true

		if [ "$SPM_LANG" = "id" ]; then
			printf "\nTerima kasih. Persetujuan tersimpan. Melanjutkan...\n"
		else
			printf "\nThank you. Consent recorded. Continuing...\n"
		fi
		sleep 1
	else
		if [ "$SPM_LANG" = "id" ]; then
			printf "\nKamu tidak menyetujui Terms & Privacy.\n"
			printf "Aplikasi tidak dapat digunakan tanpa persetujuan.\n"
		else
			printf "\nYou did not accept the Terms & Privacy.\n"
			printf "The application cannot be used without consent.\n"
		fi
		exit 1
	fi
}

# ----- Master password handling ----------------------------------------------

prompt_master_password() {
	local pw1 pw2
	if [ "$SPM_LANG" = "id" ]; then
		printf 'Kata sandi utama: '
	else
		printf 'Master password: '
	fi
	stty -echo
	IFS= read -r pw1
	stty echo
	printf '\n'

	if [ "$SPM_LANG" = "id" ]; then
		printf 'Konfirmasi kata sandi utama: '
	else
		printf 'Confirm master password: '
	fi
	stty -echo
	IFS= read -r pw2
	stty echo
	printf '\n'

	[ "$pw1" = "$pw2" ] || die "Master passwords do not match / Kata sandi utama tidak sama."

	MASTER_PW="$pw1"
}

read_master_password_once() {
	# The prompt goes to stderr, not stdout. A command whose stdout is a
	# document -- `doctor --json`, and anything machine-readable added after it
	# -- would otherwise hand its caller a prompt in the middle of the payload,
	# which is the bug 3.4.1 shipped. An interactive user sees no difference:
	# stderr is the same terminal.
	if [ "$SPM_LANG" = "id" ]; then
		printf 'Kata sandi utama: ' >&2
	else
		printf 'Master password: ' >&2
	fi
	# stty fails when stdin is not a terminal, which is the normal case for a
	# piped password. The read still works, so that failure is not fatal and
	# its complaint does not belong on the user's screen.
	stty -echo 2>/dev/null || true
	IFS= read -r MASTER_PW
	stty echo 2>/dev/null || true
	printf '\n' >&2
}

ensure_master_password_loaded() {
	if [ -z "${MASTER_PW:-}" ]; then
		read_master_password_once
	fi
}

re_verify_master_password() {
	# If master password is not yet loaded, capture it once (counts as verification)
	if [ -z "${MASTER_PW:-}" ]; then
		read_master_password_once
		return
	fi

	local entered_pw
	if [ "$SPM_LANG" = "id" ]; then
		printf 'Masukkan kata sandi utama untuk verifikasi: '
	else
		printf 'Enter master password for verification: '
	fi
	stty -echo
	IFS= read -r entered_pw
	stty echo
	printf '\n'

	if [ "$entered_pw" != "$MASTER_PW" ]; then
		if [ "$SPM_LANG" = "id" ]; then
			die "Verifikasi kata sandi utama gagal."
		else
			die "Master password verification failed."
		fi
	fi
	# Securely wipe the entered password from local variable
	entered_pw="$(printf '%*s' "${#entered_pw}" '' | tr ' ' 'X')"
	unset entered_pw 2>/dev/null || true
}

# ----- GPG encrypt / decrypt wrapper -----------------------------------------

# ----- The trusted core ------------------------------------------------------
# Everything that decides how a vault is protected -- the container format, key
# wrapping, version stamping, vault mutation, history archiving and the recovery
# file -- lives in one reviewable Python module and nowhere else. This half of
# SPM and the SPM Dashboard both reach it rather than each carrying a copy: the
# two used to, and a regression test existed purely to prove the copies still
# agreed, which is a test a shared implementation does not need.
#
# Secrets reach it on stdin, never in argv, because argv is world-readable
# through `ps` and /proc/<pid>/cmdline.

SPM_CORE_PATH=""

ensure_core_script() {
	require_cmd python3
	local base_dir
	base_dir="${1:-${SPM_CORE_DIR:-${XDG_DATA_HOME:-$HOME/.local/share}/spm}}"
	mkdir -p "$base_dir" || die "Cannot create the SPM data directory."
	# A stable name, because the SPM Dashboard imports this module by path.
	SPM_CORE_PATH="${base_dir}/spm_core.py"
	# Written unconditionally and installed atomically. The write is a
	# millisecond against a vault operation's second, and always writing means
	# an upgraded spm can never be left running last release's core.
	local staged
	staged="$(mktemp "${base_dir}/.spm_core.XXXXXX")" || die "Cannot stage the SPM core."
	cat >"$staged" <<'SPMCORE'
"""SPM trusted core: vault format, key handling and vault mutation.

Everything that decides how a vault is protected lives here and nowhere else.
The CLI reaches it through the command interface at the bottom of this file;
the SPM Dashboard imports it directly. Before this module both surfaces
carried their own copy of the container format, the key wrapping, the version
stamping and the history archiving, and a regression test existed purely to
prove the two copies still agreed -- which is a test that a shared
implementation does not need.

Secrets never appear in argv. The command interface reads them from stdin,
and gpg receives them on a dedicated file descriptor, because argv is
world-readable through `ps` and /proc/<pid>/cmdline.
"""

import base64
import calendar
import concurrent.futures
import hashlib
import hmac
import json
import os
import re
import shutil
import stat
import subprocess
import sys
import tempfile
import time
import unicodedata
import urllib.parse
import urllib.request

# ----- format and policy -----------------------------------------------------

# The vault records the format it was written in, so a later change can migrate
# instead of guessing. A vault with no META_VAULT_VERSION row predates this and
# is format 1; every write stamps the current version.
# 5 because a record may now carry a `hidden` flag inside its attributes, and
# an older build that edited such a record would re-encode the attributes
# without it -- quietly un-hiding an entry someone deliberately hid. Reading a
# format-5 vault still works on 4.1.0; stamp_version is what stops it writing
# one back.
VAULT_FORMAT_VERSION = 5

CONTAINER_MAGIC = b"SPM-VAULT-3"

# Key derivation is pinned rather than inherited: a user's gpg.conf can change
# all of it underneath the application, and a security parameter that is
# implicit can be neither reviewed nor migrated. GnuPG 2.2 already defaults to
# s2k mode 3 at the maximum count, so the measurable change is the digest,
# whose default is SHA1.
#
# From 4.0.0 nothing in production writes a gpg vault -- the openssl backend
# below does -- so this policy now describes only vaults written by earlier
# releases, and gpg_encrypt exists to build them for the tests that prove the
# migration path. It stays here rather than in the suite so that there is still
# exactly one statement of the policy in the repository.
S2K_ARGS = ["--s2k-mode", "3", "--s2k-digest-algo", "SHA512",
            "--s2k-count", "65011712"]

HISTORY_RETENTION_DEFAULT = 20


class VaultError(Exception):
    """Anything that should reach a user as a refusal rather than a traceback."""


class VaultSecretError(VaultError):
    """The supplied secret does not open this vault.

    gpg could not tell a caller this: it refused a wrong passphrase and a
    damaged file with the same non-zero exit, so every caller that wanted to
    say "wrong master password" was guessing. An authenticated envelope makes
    the two separable, and separating them is the point of naming them.
    """


class VaultIntegrityError(VaultError):
    """The envelope opened but the sealed data failed authentication.

    Which means the secret was right and the bytes are damaged -- a distinction
    worth surfacing, because the two have opposite remedies: retype, or
    restore.
    """


# ----- gpg backend -----------------------------------------------------------

def _passphrase_fd(secret):
    """A read fd holding `secret`, for gpg's --passphrase-fd.

    A pipe rather than argv: argv is world-readable through `ps` and
    /proc/<pid>/cmdline, so every local user could read the master password.
    """
    read_fd, write_fd = os.pipe()
    try:
        os.write(write_fd, secret.encode("utf-8"))
    finally:
        os.close(write_fd)
    return read_fd


def gpg_encrypt(secret, payload, timeout=60):
    """Seal under gpg, the way releases before 4.0.0 did.

    No production path calls this any more. It is what the migration tests
    build a pre-4.0.0 vault with, so that they upgrade a real one rather than
    an approximation of one.
    """
    fd = _passphrase_fd(secret)
    try:
        return subprocess.check_output(
            ["gpg", "--batch", "--yes", "--pinentry-mode", "loopback",
             "--passphrase-fd", str(fd)] + S2K_ARGS +
            ["--cipher-algo", "AES256", "-c"],
            input=payload, stderr=subprocess.DEVNULL,
            timeout=timeout, pass_fds=(fd,))
    finally:
        os.close(fd)


def gpg_decrypt(secret, payload, timeout=60):
    fd = _passphrase_fd(secret)
    try:
        return subprocess.check_output(
            ["gpg", "--batch", "--quiet", "--pinentry-mode", "loopback",
             "--passphrase-fd", str(fd), "-d"],
            input=payload, stderr=subprocess.DEVNULL,
            timeout=timeout, pass_fds=(fd,))
    finally:
        os.close(fd)


# ----- openssl backend -------------------------------------------------------
# gpg seals both layers of a vault by stretching a passphrase. That is right
# for the master password and pure waste for the vault key, which is 256
# random bits and has nothing left to stretch -- format 3 established the
# separation and then paid the stretching cost twice anyway. Format 5 stops:
# the master password goes through scrypt, which is memory-hard where gpg's
# SHA512 iteration is not, and the data is sealed under the vault key directly.
#
# openssl is the cipher because it is the only one on every platform SPM
# supports. Python's hashlib carries scrypt, HMAC and PBKDF2 but no AES, and a
# third-party dependency is the portability rule this project is built on.
# Using its command line imposes three constraints, and each one shapes the
# code below rather than being worked around:
#
#   Keys reach it on a file descriptor. `openssl enc -K` puts the key in argv,
#   where any local user reads it out of /proc/<pid>/cmdline. OpenSSL 3 scrubs
#   argv shortly after startup, but there is a window, and LibreSSL is not
#   known to scrub at all. `-pass fd:` has no such window.
#
#   A passphrase read from that descriptor is read as a *line*, so key
#   material handed to openssl must be text containing no newline: a raw
#   32-byte key with an 0x0A byte in it would be silently truncated, and the
#   vault would still encrypt and decrypt perfectly with a key a fifth of the
#   intended length. Everything passed here is base64.
#
#   Authentication is ours. `openssl enc` offers no AEAD mode that carries a
#   tag, so this is encrypt-then-MAC, with a MAC key derived in-process that
#   never crosses to another program at all.

# Named for what it is rather than numbered, deliberately. The gpg container
# was "SPM-VAULT-3" back when the record format was also 3; the two drifted at
# format 4, and a header reading "SPM-VAULT-5" beside a META_VAULT_VERSION row
# saying 4 would invite exactly the confusion that gets a format misread. This
# magic names the sealing generation; the record format keeps its own number.
CONTAINER_MAGIC_AEAD = b"SPM-VAULT-AEAD1"

SEAL_MAGIC = b"SPMSEAL1"
# openssl's PKCS5 salt is eight bytes and it discards anything longer with a
# warning, so eight is what the format carries rather than a size that only
# looks stronger. The IV is separate and full width: a salt collision alone
# must not repeat a CTR keystream, and an IV is not secret, so it is the one
# value here that may travel in argv.
SEAL_SALT_BYTES = 8
SEAL_IV_BYTES = 16
SEAL_TAG_BYTES = 32
SEAL_CIPHER = "aes-256-ctr"
SEAL_MAC_INFO = b"SPMSEAL1-mac"

# The vault records the KDF by name and parameters, which is what turns a
# later move to Argon2id into a value the reader dispatches on instead of
# another format change. n=2**15 is 32 MiB and measures ~145 ms here, against
# ~390 ms for the gpg envelope it replaces.
KDF_NAME = "scrypt"
KDF_N = 1 << 15
KDF_R = 8
KDF_P = 1
KDF_SALT_BYTES = 16
KDF_DKLEN = 32
# hashlib.scrypt refuses anything past its default maxmem with "memory limit
# exceeded", and the default is below what n=2**15 needs, so the bound is
# stated rather than inherited: 128 * n * r is the working set.
KDF_MAXMEM = 128 * KDF_N * KDF_R * 2

# ----- hardware-held wrapping ------------------------------------------------
# A security key can derive a stable secret from a credential and a salt --
# WebAuthn calls it the PRF extension, CTAP2 calls it hmac-secret. That secret
# never leaves the device except as its output, and the device will not produce
# it without the user verification it was enrolled with.
#
# SPM uses it as key material and nothing more: the vault key is sealed under it
# with the same encrypt-then-MAC the master password path uses, so the only new
# cryptography here is the derivation of a wrapping key from the device's 32
# bytes, and that is one HMAC with a fixed label.
HARDWARE_SECRET_BYTES = 32
HARDWARE_WRAP_INFO = b"SPM-HARDWARE-WRAP-v1"
HARDWARE_SALT_BYTES = 32


def _key_fd(key_text):
    """A read fd holding `key_text`, for openssl's -pass fd:.

    Same reasoning as _passphrase_fd: argv is world-readable. The newline is
    what openssl strips when it reads the line back, so it is not part of the
    passphrase.
    """
    try:
        material = key_text.encode("ascii")
    except UnicodeEncodeError:
        # Every key this format seals with is base64, so non-ASCII here means
        # the caller passed something else -- an old master password from a
        # recovery file, which recover() tries speculatively. A refusal it can
        # catch is better than a UnicodeEncodeError out of a crypto path.
        raise VaultError("key material for openssl must be ASCII")
    if b"\n" in material or b"\r" in material:
        raise VaultError("key material for openssl must be a single line")
    read_fd, write_fd = os.pipe()
    try:
        os.write(write_fd, material + b"\n")
    finally:
        os.close(write_fd)
    return read_fd


def openssl_ctr(key_text, salt, iv, payload, decrypt=False, timeout=60):
    """AES-256-CTR under a key openssl derives from `key_text` and `salt`.

    The derivation is PBKDF2-HMAC-SHA256 at one iteration, which
    hashlib.pbkdf2_hmac reproduces byte for byte -- the known-answer test in
    the suite depends on exactly that, so a platform whose openssl derives
    differently fails a test rather than writing a vault nothing can open.

    One iteration is not an oversight. Both callers pass full-entropy key
    material -- a random vault key, or an scrypt output -- so this step exists
    to produce a key and an IV, not to stretch a guessable secret. The
    stretching happens once, in scrypt, where the low-entropy secret actually
    is.
    """
    fd = _key_fd(key_text)
    try:
        return subprocess.check_output(
            ["openssl", "enc", "-" + SEAL_CIPHER, "-d" if decrypt else "-e",
             "-pbkdf2", "-iter", "1", "-md", "sha256",
             "-S", salt.hex(), "-iv", iv.hex(), "-pass", "fd:%d" % fd],
            input=payload, stderr=subprocess.DEVNULL,
            timeout=timeout, pass_fds=(fd,))
    finally:
        os.close(fd)


def _seal_mac_key(key_text, salt):
    """A MAC key independent of the encryption key openssl derives.

    openssl computes HMAC(key_text, salt || counter) for its blocks; this
    computes HMAC(key_text, "SPMSEAL1-mac" || salt), a different message under the
    same key, so neither derivation reveals the other.
    """
    return hmac.new(key_text.encode("ascii"), SEAL_MAC_INFO + salt,
                    hashlib.sha256).digest()


def seal(key_text, payload):
    """Encrypt-then-MAC `payload` under `key_text`. Returns one opaque blob."""
    salt = os.urandom(SEAL_SALT_BYTES)
    iv = os.urandom(SEAL_IV_BYTES)
    cipher = openssl_ctr(key_text, salt, iv, payload)
    body = SEAL_MAGIC + salt + iv + cipher
    return body + hmac.new(_seal_mac_key(key_text, salt), body,
                           hashlib.sha256).digest()


def unseal(key_text, blob):
    """`payload` from a blob `seal` produced, or a refusal.

    The tag is checked before anything is decrypted, so a modified blob is
    never fed to a cipher. CTR decryption cannot fail on its own -- it will
    happily turn corrupted input into corrupted output -- which is precisely
    why the tag has to be the gate rather than an afterthought.
    """
    head = len(SEAL_MAGIC) + SEAL_SALT_BYTES + SEAL_IV_BYTES
    if len(blob) < head + SEAL_TAG_BYTES or not blob.startswith(SEAL_MAGIC):
        raise VaultError("sealed block is not in this format")
    body, tag = blob[:-SEAL_TAG_BYTES], blob[-SEAL_TAG_BYTES:]
    salt = body[len(SEAL_MAGIC):len(SEAL_MAGIC) + SEAL_SALT_BYTES]
    iv = body[len(SEAL_MAGIC) + SEAL_SALT_BYTES:head]
    expected = hmac.new(_seal_mac_key(key_text, salt), body, hashlib.sha256)
    if not hmac.compare_digest(expected.digest(), tag):
        raise VaultError("sealed block failed authentication")
    return openssl_ctr(key_text, salt, iv, body[head:], decrypt=True)


def derive_kek(master, salt, n=KDF_N, r=KDF_R, p=KDF_P):
    """The key-encryption key for the master password, as openssl-safe text."""
    raw = hashlib.scrypt(master.encode("utf-8"), salt=salt, n=n, r=r, p=p,
                         dklen=KDF_DKLEN, maxmem=KDF_MAXMEM)
    return base64.b64encode(raw).decode("ascii")


# ----- container -------------------------------------------------------------
# A format-3 vault is one file: a header line, the vault key sealed under the
# master password, then the vault ciphertext sealed under that key. Keeping it
# to a single self-contained file is why every path that copies, backs up,
# syncs or bundles "the vault" needed no change when the format did.

def is_container(raw):
    """True for any sealed vault, whichever backend sealed it."""
    return (raw.startswith(CONTAINER_MAGIC + b"\n")
            or raw.startswith(CONTAINER_MAGIC_AEAD + b"\n"))


def container_backend(raw):
    """"openssl", "gpg", or None for a vault that predates the container."""
    if raw.startswith(CONTAINER_MAGIC_AEAD + b"\n"):
        return "openssl"
    if raw.startswith(CONTAINER_MAGIC + b"\n"):
        return "gpg"
    return None


def build_container(envelope, cipher):
    return (CONTAINER_MAGIC + b"\nKEY " + base64.b64encode(envelope) +
            b"\nDATA\n" + base64.b64encode(cipher) + b"\n")


def parse_container(raw):
    """(envelope, cipher) for a gpg-sealed vault, else None.

    The magic is checked exactly rather than through is_container, which
    answers for both backends: an AEAD header also carries a KEY line and a
    DATA marker, so the lenient test parsed one happily and handed back an
    envelope no gpg would ever open.
    """
    if not raw.startswith(CONTAINER_MAGIC + b"\n"):
        return None
    try:
        key_line, data = raw.split(b"\nDATA\n", 1)
        envelope = base64.b64decode(key_line.split(b"\nKEY ", 1)[1])
        cipher = base64.b64decode(data)
    except Exception as exc:
        raise VaultError("vault key container is corrupt") from exc
    if not envelope or not cipher:
        raise VaultError("vault key container is incomplete")
    return envelope, cipher


def new_vault_key():
    return base64.b64encode(os.urandom(32)).decode("ascii")


# An AEAD-format vault keeps the shape format 3 established -- one file, a key
# envelope, then the data -- and adds the line that made the whole exercise
# worth doing: the KDF, by name and by parameter. Without it a change of
# stretching function is another format version; with it, it is a value the
# reader already knows how to dispatch on.

def build_container_aead(kdf_salt, envelope, cipher, n=KDF_N, r=KDF_R, p=KDF_P):
    return (CONTAINER_MAGIC_AEAD +
            b"\nKDF " + KDF_NAME.encode("ascii") +
            b" n=%d r=%d p=%d salt=" % (n, r, p) +
            base64.b64encode(kdf_salt) +
            b"\nKEY " + base64.b64encode(envelope) +
            b"\nDATA\n" + base64.b64encode(cipher) + b"\n")


def parse_container_aead(raw):
    """(kdf, envelope, cipher) for an AEAD vault, else None.

    `kdf` is a dict carrying the name and every parameter the vault was
    written with, so the unwrap uses the vault's own numbers rather than this
    build's constants -- which is what lets a cost parameter be raised without
    stranding vaults written before the change.
    """
    if not raw.startswith(CONTAINER_MAGIC_AEAD + b"\n"):
        return None
    try:
        header, data = raw.split(b"\nDATA\n", 1)
        _, kdf_line, key_line = header.split(b"\n", 2)
        name, params = kdf_line[len(b"KDF "):].split(b" ", 1)
        fields = dict(item.split(b"=", 1) for item in params.split(b" "))
        kdf = {"name": name.decode("ascii"),
               "n": int(fields[b"n"]), "r": int(fields[b"r"]),
               "p": int(fields[b"p"]),
               "salt": base64.b64decode(fields[b"salt"])}
        envelope = base64.b64decode(key_line[len(b"KEY "):])
        cipher = base64.b64decode(data)
    except Exception as exc:
        raise VaultError("vault key container is corrupt") from exc
    if not envelope or not cipher or not kdf["salt"]:
        raise VaultError("vault key container is incomplete")
    if kdf["name"] != KDF_NAME:
        # Named, not guessed. A vault written by a build that adopted a
        # different stretching function must refuse here rather than derive
        # the wrong key and report a wrong master password.
        raise VaultError(
            "this vault was written with the %s key derivation and this SPM "
            "implements %s; upgrade SPM rather than guessing"
            % (kdf["name"], KDF_NAME))
    return kdf, envelope, cipher


def vault_seal_summary(vault_path):
    """(backend, kdf) describing how a vault file on disk is sealed.

    kdf is None for anything gpg sealed, which is the point: the old format
    had no way to say what it stretched a password with, so a report about it
    can only name the backend.
    """
    # An unreadable file is the caller's problem and raises. Only a readable
    # one that is not a container returns None -- "there is no vault here" and
    # "this vault predates the container" are different answers and must not
    # arrive as the same one.
    with open(vault_path, "rb") as handle:
        raw = handle.read()
    backend = container_backend(raw)
    if backend != "openssl":
        return backend, None
    return backend, parse_container_aead(raw)[0]


def unwrap_key_aead(kdf, envelope, master):
    kek = derive_kek(master, kdf["salt"], kdf["n"], kdf["r"], kdf["p"])
    try:
        return unseal(kek, envelope).decode("utf-8")
    except VaultError:
        raise VaultSecretError("that secret does not open this vault")


def hardware_kek(secret):
    """The wrapping key for a secret a security key derived.

    The device's output is not used as a key directly. One HMAC under a fixed
    label separates this use from any other the same PRF secret is put to --
    a second application asking the same credential for the same salt gets the
    same 32 bytes, and this makes SPM's wrapping key not be those 32 bytes.
    """
    if not isinstance(secret, (bytes, bytearray)):
        raise VaultError("a hardware secret must be bytes")
    if len(secret) != HARDWARE_SECRET_BYTES:
        raise VaultError("a hardware secret must be exactly %d bytes"
                         % HARDWARE_SECRET_BYTES)
    raw = hmac.new(bytes(secret), HARDWARE_WRAP_INFO, hashlib.sha256).digest()
    return base64.b64encode(raw).decode("ascii")


def hardware_wrap_key(secret, vault_key):
    """The vault key sealed under a security key's secret, as base64 text."""
    blob = seal(hardware_kek(secret), vault_key.encode("utf-8"))
    return base64.b64encode(blob).decode("ascii")


def hardware_unwrap_key(secret, wrapped):
    """The vault key back, or a refusal that names the security key.

    Wrong-secret and tampered-blob both arrive here as the same failure from
    `unseal`, which is deliberate: the tag is checked before anything is
    decrypted, so neither case reveals which it was.
    """
    try:
        blob = base64.b64decode(wrapped, validate=True)
    except ValueError as exc:          # binascii.Error subclasses it
        raise VaultSecretError("that security key does not open this vault") from exc
    try:
        return unseal(hardware_kek(secret), blob).decode("utf-8")
    except VaultError as exc:
        raise VaultSecretError("that security key does not open this vault") from exc


# ----- version stamping ------------------------------------------------------

def stamp_version(plaintext):
    """Exactly one current META_VAULT_VERSION row, first, on every write.

    Refuses to restamp a vault written by a newer SPM. Without this an older
    build opens a newer vault, keeps only the columns it knows, and writes it
    back stamped with its own version -- a silent downgrade that discards
    whatever the newer format added. The vault reads fine afterwards, which is
    what makes it dangerous: nothing announces the loss.

    Reading stays permitted. This guards the write, which is where the loss
    would happen.
    """
    found = format_version(plaintext)
    if found > VAULT_FORMAT_VERSION:
        raise VaultError(
            "this vault is format %d and this SPM understands %d; upgrade SPM "
            "rather than writing it back and losing what it holds"
            % (found, VAULT_FORMAT_VERSION))
    lines = plaintext.split("\n")
    if lines and lines[-1] == "":
        lines.pop()
    rows = [l for l in lines if l.split("\t", 1)[0] != "META_VAULT_VERSION"]
    head = "META_VAULT_VERSION\t%d\t-\t-\t-\t-" % VAULT_FORMAT_VERSION
    return "\n".join([head] + rows) + "\n"


def format_version(plaintext):
    for line in plaintext.splitlines():
        parts = line.split("\t")
        if parts[0] == "META_VAULT_VERSION" and len(parts) > 1:
            try:
                return int(parts[1])
            except ValueError:
                return 1
    return 1


# ----- durability ------------------------------------------------------------

# The `read` command returns the vault key on stdout, so an output path that
# resolves to stdout would interleave plaintext with it and silently lose both.
# Refusing is better than a corrupted read that looks like it worked.
_STDOUT_ALIASES = ("-", "/dev/stdout", "/dev/fd/1", "/proc/self/fd/1")


def write_plaintext(path, text):
    """Write decrypted vault material to a file, restricted to its owner."""
    if path in _STDOUT_ALIASES:
        raise VaultError("refusing to write vault plaintext to stdout; "
                         "give a file path")
    with open(path, "w", encoding="utf-8") as handle:
        handle.write(text)
    try:
        if stat.S_ISREG(os.stat(path).st_mode):
            os.chmod(path, 0o600)
    except OSError:
        pass


def _fsync_path(path):
    fd = os.open(path, os.O_RDONLY)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


def _fsync_dir(path):
    # A directory fsync is what makes a rename survive a crash. Not every
    # filesystem permits it, so a refusal must not fail the write.
    try:
        fd = os.open(path, os.O_RDONLY)
    except OSError:
        return
    try:
        os.fsync(fd)
    except OSError:
        pass
    finally:
        os.close(fd)


# ----- history ---------------------------------------------------------------
# The CLI and the dashboard must agree on this hash exactly, or the two would
# write snapshots into different directories and each would see only its own.

def vault_scope_id(vault_path):
    return hashlib.sha256(
        os.path.abspath(vault_path).encode("utf-8")).hexdigest()[:16]


def data_dir():
    explicit = os.environ.get("SPM_DATA_DIR")
    if explicit:
        return explicit
    base = os.environ.get("XDG_DATA_HOME") or os.path.join(
        os.path.expanduser("~"), ".local", "share")
    return os.path.join(base, "spm")


def history_dir(vault_path):
    return os.path.join(data_dir(), "history", vault_scope_id(vault_path))


def _retention():
    try:
        keep = int(os.environ.get("SPM_HISTORY_RETENTION", ""))
    except ValueError:
        return HISTORY_RETENTION_DEFAULT
    return keep if keep > 0 else HISTORY_RETENTION_DEFAULT


# ----- security events -------------------------------------------------------
#
# What this is for: noticing that someone else opened, or tried to open, your
# vault. That is the whole reason it exists, and it decides both of the awkward
# choices below.
#
# It lives outside the vault, in plaintext. Inside would be tidier and would be
# encrypted, but a failed unlock is exactly the event you most want recorded
# and exactly the one that cannot be written into a vault nobody could open.
#
# So it must carry nothing worth reading. No labels, no usernames, no URLs, no
# paths, no secrets -- only a time, what kind of operation it was, whether it
# succeeded, and a detail drawn from a fixed vocabulary. Someone who can read
# this file can already see the vault file beside it and its modification time,
# so "this vault was opened at these times" is not new information to them.
# Anything beyond that would be.

EVENT_RETENTION_DEFAULT = 500
# The dashboard reads the vault on nearly every page view, so an event per read
# buries the handful of lines anyone actually came to see. Identical successful
# events inside this window are recorded once.
#
# Failures are never coalesced, whatever the window says. A burst of failed
# unlocks is precisely the signal this log exists to show, and collapsing five
# attempts into one would be the log lying about the thing it is for.
EVENT_COALESCE_DEFAULT = 60
EVENT_KINDS = ("unlock", "write", "rewrap", "recover", "restore", "archive",
               "hardware")
EVENT_OUTCOMES = ("ok", "fail")
# Details are key=value with both sides constrained, rather than free text.
# Free text is how a label ends up in a log one day: someone adds a helpful
# "which record" to an error path and nobody notices it is now on disk in the
# clear. A closed vocabulary makes that a test failure instead of a leak.
EVENT_DETAIL_KEYS = ("records", "format", "scope", "reason")
# "reason" carries why a security-key event happened as well as why an
# unlock failed. Constrained the same way and for the same reason: a
# free-text detail is how a device label reaches the log in the clear.
EVENT_REASONS = ("bad-master", "corrupt", "missing", "unreadable",
                 "enrolled", "forgotten", "bad-secret", "vault-replaced")
EVENT_SCOPES = ("live", "other")


# ----- record attributes: folders and custom fields --------------------------
#
# Format 4 appends one optional column to a password row, after the URL. It
# holds a folder name and any number of user-named fields, base64-encoded JSON
# so that a tab, a newline or a non-ASCII name in a value cannot break the
# row-per-line format that everything else depends on.
#
# A column rather than new row types: a folder and a custom field belong to the
# record they describe, and keeping them on the row means every existing path
# that moves, exports or deletes a record carries them along without being
# taught to. The cost is that an older SPM writing this vault back would drop
# them, which is what the guard in stamp_version exists to prevent.

ATTRS_FOLDER_MAX = 128
ATTRS_FIELD_NAME_MAX = 128
ATTRS_FIELD_VALUE_MAX = 4096
ATTRS_FIELD_MAX = 64


def encode_attrs(folder="", fields=None, hidden=False):
    """The attributes column for a record, or "" when there is nothing to say.

    Empty is empty rather than an encoded empty object, so a record that uses
    none of this is byte-identical to how format 3 wrote it.
    """
    folder = (folder or "").strip()
    fields = [(str(n).strip(), str(v)) for n, v in (fields or []) if str(n).strip()]
    hidden = bool(hidden)
    if not folder and not fields and not hidden:
        return ""
    if len(folder) > ATTRS_FOLDER_MAX:
        raise VaultError("folder name is longer than %d characters"
                         % ATTRS_FOLDER_MAX)
    if len(fields) > ATTRS_FIELD_MAX:
        raise VaultError("a record may carry at most %d custom fields"
                         % ATTRS_FIELD_MAX)
    seen = set()
    for name, value in fields:
        if len(name) > ATTRS_FIELD_NAME_MAX:
            raise VaultError("custom field name is longer than %d characters"
                             % ATTRS_FIELD_NAME_MAX)
        if len(value) > ATTRS_FIELD_VALUE_MAX:
            raise VaultError("custom field value is longer than %d characters"
                             % ATTRS_FIELD_VALUE_MAX)
        key = name.casefold()
        if key in seen:
            raise VaultError("duplicate custom field name %r" % (name,))
        seen.add(key)
    payload = {}
    if folder:
        payload["folder"] = folder
    if fields:
        payload["fields"] = [{"name": n, "value": v} for n, v in fields]
    if hidden:
        payload["hidden"] = True
    raw = json.dumps(payload, separators=(",", ":"), ensure_ascii=False)
    return base64.b64encode(raw.encode("utf-8")).decode("ascii")


def decode_attrs(column):
    """(folder, [(name, value)], hidden) for an attributes column.

    Never raises. A column this build cannot read is a record it should still
    show, minus the part it did not understand -- refusing would make one bad
    row hide a whole vault.

    Three values rather than two, deliberately. Every caller unpacked two, so
    adding `hidden` breaks each of them at the point of use instead of letting
    a writer re-encode a record without the flag it never read. That silent
    drop is exactly how folders and custom fields went missing from twenty
    export formats until 4.1.0.
    """
    column = (column or "").strip()
    if not column:
        return "", [], False
    try:
        payload = json.loads(base64.b64decode(column, validate=True)
                             .decode("utf-8"))
    except Exception:
        return "", [], False
    if not isinstance(payload, dict):
        return "", [], False
    folder = payload.get("folder") or ""
    if not isinstance(folder, str):
        folder = ""
    fields = []
    raw = payload.get("fields")
    if isinstance(raw, list):
        for item in raw[:ATTRS_FIELD_MAX]:
            if not isinstance(item, dict):
                continue
            name, value = item.get("name"), item.get("value")
            if isinstance(name, str) and name.strip() and isinstance(value, str):
                fields.append((name, value))
    return folder[:ATTRS_FOLDER_MAX], fields, payload.get("hidden") is True


# The column order every export writes and every headerless or positional
# reader maps against. One ordered definition, because the places that had
# their own each stopped at a different column: the SQL writer named eight
# while writing eleven, the SQL reader named nine, and the headerless CSV
# readers stopped at `url`. None of them failed a test, because SPM was
# reading back exactly what SPM wrote.
EXPORT_FIELDNAMES = ("type", "id", "label", "username", "secret", "notes",
                     "created", "extra", "url", "folder", "fields", "hidden")


def export_row_from_values(values):
    """A row dict from a positional record, for headerless and SQL readers."""
    return {name: (values[index] if index < len(values) else "")
            for index, name in enumerate(EXPORT_FIELDNAMES)}


# ----- attributes across an export -------------------------------------------
# A folder and its custom fields cross an export as their own readable columns
# rather than as the stored base64 blob: an export is meant to be opened in a
# spreadsheet, and a column of opaque base64 is neither readable nor editable
# by whatever the user opens it with.
#
# Both directions live here because both surfaces need them and only one of
# them had them. Until 4.1.0 these were private to the dashboard, so a vault
# exported and re-imported through the CLI lost every folder and every custom
# field, on all twenty formats, silently -- which is exactly the disagreement
# between two surfaces that a shared core exists to make impossible.

def attrs_export_columns(column):
    """The folder and fields columns an export carries for one record."""
    folder, fields, hidden = decode_attrs(column)
    return {
        "folder": folder,
        "fields": json.dumps(
            [{"name": n, "value": v} for n, v in fields],
            separators=(",", ":"), ensure_ascii=False) if fields else "",
        "hidden": "1" if hidden else "",
    }


def attrs_from_export_row(row):
    """The attributes column for an imported row.

    Tolerant on purpose: an import is the one place rows arrive from software
    that never heard of this format. A folder or a fields list that does not
    parse is dropped rather than failing the import, because losing one
    optional column is better than refusing a file of real passwords.
    """
    folder = str(row.get("folder", "") or "")
    fields = []
    raw = row.get("fields", "")
    if isinstance(raw, list):
        candidates = raw
    elif isinstance(raw, str) and raw.strip():
        try:
            candidates = json.loads(raw)
        except Exception:
            candidates = []
    else:
        candidates = []
    if isinstance(candidates, list):
        for item in candidates:
            if isinstance(item, dict):
                name, value = item.get("name"), item.get("value")
                if isinstance(name, str) and name.strip():
                    fields.append((name, str(value if value is not None else "")))
    # Anything a spreadsheet or another manager might put in a truthy cell.
    # An unrecognised value means not hidden, because the safe direction for a
    # flag nobody understood is the one that shows the entry rather than the
    # one that pretends a vault holds less than it does.
    raw_hidden = row.get("hidden", "")
    hidden = (raw_hidden is True
              or (isinstance(raw_hidden, str)
                  and raw_hidden.strip().lower() in ("1", "true", "yes", "y", "hidden")))
    try:
        return encode_attrs(folder, fields, hidden)
    except Exception:
        return ""


def record_folders(plaintext):
    """Every folder in use, sorted, without duplicates differing only in case."""
    seen = {}
    for line in (plaintext or "").splitlines():
        parts = line.split("\t")
        if not parts or parts[0].startswith("META_") or not parts[0].isdigit():
            continue
        folder, _, _ = decode_attrs(parts[7] if len(parts) > 7 else "")
        if folder:
            seen.setdefault(folder.casefold(), folder)
    return [seen[k] for k in sorted(seen)]


def _record_count(plaintext):
    """Rows that are records rather than META_ headers. A count, and nothing
    that says what any of them are."""
    return sum(1 for line in (plaintext or "").splitlines()
               if line.strip() and not line.startswith("META_"))


def events_path(vault_path):
    return os.path.join(data_dir(), "events",
                        vault_scope_id(vault_path) + ".log")


def _event_retention():
    try:
        keep = int(os.environ.get("SPM_EVENT_RETENTION", ""))
    except ValueError:
        return EVENT_RETENTION_DEFAULT
    return keep if keep > 0 else EVENT_RETENTION_DEFAULT


def _event_coalesce_window():
    try:
        seconds = int(os.environ.get("SPM_EVENT_COALESCE", ""))
    except ValueError:
        return EVENT_COALESCE_DEFAULT
    return seconds if seconds >= 0 else EVENT_COALESCE_DEFAULT


def _last_event(path):
    """The final line of the log, without reading the whole file."""
    try:
        size = os.path.getsize(path)
        with open(path, "rb") as handle:
            handle.seek(max(0, size - 4096))
            tail = handle.read().decode("utf-8", "ignore").splitlines()
    except OSError:
        return None
    return tail[-1] if tail else None


def _coalesces(path, kind, outcome, detail, now):
    """True when this event repeats the last one inside the window."""
    if outcome != "ok":
        return False
    window = _event_coalesce_window()
    if window <= 0:
        return False
    previous = _last_event(path)
    if not previous:
        return False
    fields = previous.split("\t")
    if len(fields) != 4:
        return False
    if (fields[1], fields[2], fields[3]) != (kind, outcome, detail):
        return False
    try:
        before = calendar.timegm(time.strptime(fields[0], "%Y-%m-%dT%H:%M:%SZ"))
    except ValueError:
        return False
    return 0 <= now - before < window


def event_line(when, kind, outcome, detail=""):
    """One log line, or ValueError if it would carry something it should not.

    Deliberately strict and deliberately raising: misuse here is a programming
    error and should fail a test. Callers wrap it so that a rejected line can
    never take a vault operation down with it.
    """
    if kind not in EVENT_KINDS:
        raise ValueError("unknown event kind %r" % (kind,))
    if outcome not in EVENT_OUTCOMES:
        raise ValueError("unknown event outcome %r" % (outcome,))
    parts = []
    for item in (detail or "").split(","):
        item = item.strip()
        if not item:
            continue
        if "=" not in item:
            raise ValueError("event detail %r is not key=value" % (item,))
        key, value = item.split("=", 1)
        if key not in EVENT_DETAIL_KEYS:
            raise ValueError("event detail key %r is not permitted" % (key,))
        if key == "reason" and value not in EVENT_REASONS:
            raise ValueError("event reason %r is not permitted" % (value,))
        if key == "scope" and value not in EVENT_SCOPES:
            raise ValueError("event scope %r is not permitted" % (value,))
        if key in ("records", "format") and not value.isdigit():
            raise ValueError("event %s must be a number, got %r" % (key, value))
        parts.append("%s=%s" % (key, value))
    return "\t".join((when, kind, outcome, ",".join(parts)))


def _audit_target():
    """The vault whose log receives events, or "" when there is none.

    Taken from the environment rather than from the path being operated on, so
    that reading a snapshot or a .bak records against the vault the session is
    actually about instead of scattering a log file per file touched.
    """
    return os.environ.get("SPM_VAULT_PATH", "") or ""


def record_event(kind, outcome="ok", detail="", vault_path=None):
    """Append one event. Never raises, and never fails the caller.

    Same rule as archive_generation below: losing a log line is a nuisance,
    losing the operation it describes is data loss.
    """
    try:
        target = vault_path or _audit_target()
        if not target:
            return False
        now = time.time()
        when = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(now))
        line = event_line(when, kind, outcome, detail)
        path = events_path(target)
        os.makedirs(os.path.dirname(path), mode=0o700, exist_ok=True)
        # Computed from the formatted line so the comparison is against exactly
        # what was written, not against a detail string that might normalise
        # differently on the way in.
        written = line.split("\t")
        if _coalesces(path, written[1], written[2], written[3], now):
            return False
        handle = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_APPEND, 0o600)
        try:
            os.write(handle, (line + "\n").encode("utf-8"))
        finally:
            os.close(handle)
        _prune_events(path)
        return True
    except Exception:
        return False


def _prune_events(path):
    """Keep the log bounded, rewritten atomically so a reader sees one or the
    other. Trimmed only when it has drifted well past the limit, so an append
    is an append almost every time rather than a whole-file rewrite."""
    keep = _event_retention()
    try:
        with open(path, "r", encoding="utf-8") as handle:
            lines = handle.readlines()
    except OSError:
        return
    if len(lines) <= keep * 2:
        return
    staged = path + ".tmp"
    with open(staged, "w", encoding="utf-8") as handle:
        handle.writelines(lines[-keep:])
    os.chmod(staged, 0o600)
    os.replace(staged, path)


def read_events(vault_path=None, limit=None):
    """Recorded events, oldest first. Malformed lines are skipped, not raised:
    a log is a record of what happened, not a thing that gets to fail."""
    target = vault_path or _audit_target()
    if not target:
        return []
    try:
        with open(events_path(target), "r", encoding="utf-8") as handle:
            raw = handle.read().splitlines()
    except OSError:
        return []
    out = []
    for line in raw:
        fields = line.split("\t")
        if len(fields) < 3:
            continue
        when, kind, outcome = fields[0], fields[1], fields[2]
        if kind not in EVENT_KINDS or outcome not in EVENT_OUTCOMES:
            continue
        detail = {}
        for item in (fields[3] if len(fields) > 3 else "").split(","):
            if "=" in item:
                key, value = item.split("=", 1)
                if key in EVENT_DETAIL_KEYS:
                    detail[key] = value
        out.append({"when": when, "kind": kind,
                    "outcome": outcome, "detail": detail})
    if limit and limit > 0:
        return out[-limit:]
    return out


def _scope_of(vault_path):
    try:
        target = _audit_target()
        if not target:
            return "other"
        same = os.path.abspath(vault_path) == os.path.abspath(target)
        return "live" if same else "other"
    except Exception:
        return "other"


def archive_generation(vault_path):
    """Snapshot the current ciphertext before it is replaced.

    Failure here must never fail the write it protects: losing an undo point
    is bad, losing the edit is worse.
    """
    if not os.path.exists(vault_path):
        return
    try:
        target = history_dir(vault_path)
        os.makedirs(target, exist_ok=True)
        os.chmod(target, 0o700)
        with open(vault_path, "rb") as handle:
            digest = hashlib.sha256(handle.read()).hexdigest()[:12]
        stamp = time.strftime("%Y%m%dT%H%M%S", time.gmtime())
        snapshot = os.path.join(
            target, "%s.%d.%s.gpg" % (stamp, os.getpid(), digest))
        shutil.copy2(vault_path, snapshot)
        os.chmod(snapshot, 0o600)
        _prune(target, ".gpg", _retention())
    except Exception:
        return


def _prune(directory, suffix, keep):
    try:
        entries = [os.path.join(directory, n) for n in os.listdir(directory)
                   if n.endswith(suffix)]
        entries = [p for p in entries if os.path.isfile(p)]
        entries.sort(key=lambda p: os.stat(p).st_mtime, reverse=True)
        for stale in entries[keep:]:
            os.remove(stale)
    except Exception:
        return


# ----- recovery --------------------------------------------------------------

def recovery_path(vault_path):
    return vault_path + ".recovery"


# The enrolled security keys live beside the vault rather than inside it, for
# the reason that decides the whole shape of this feature: a cold unlock has to
# read them BEFORE anything is decrypted. A META_ row inside the vault could
# only ever be read by someone who had already opened it, which is exactly the
# person who does not need it. The recovery file established this pattern in
# 3.0.0 and this follows it.
#
# What the file discloses if taken: which credential ids are enrolled, and a
# vault key sealed under 32 bytes that exist only inside an authenticator.
# There is no password in that path to guess at, so unlike the master-password
# envelope beside it, this one offers an offline attacker nothing to work on.
def hardware_path(vault_path):
    return vault_path + ".hardware"


def read_hardware(vault_path):
    """{"salt": <b64>, "keys": [...]} for this vault. No file means none.

    One salt for the whole vault rather than one per key, because the salt has
    to be chosen before the ceremony and the ceremony is what reveals which key
    answered. A single salt keeps the request unambiguous, and it costs
    nothing: the PRF secret is per credential, so two keys given the same salt
    still derive two different secrets and seal two different envelopes.
    """
    target = hardware_path(vault_path)
    if not os.path.exists(target):
        return {"salt": "", "keys": []}
    try:
        with open(target, "r", encoding="utf-8") as handle:
            document = json.load(handle)
        entries = document["keys"]
        salt = str(document.get("salt") or "")
        if not isinstance(entries, list):
            raise ValueError("keys is not a list")
    except (OSError, ValueError, KeyError, TypeError) as exc:
        # Named rather than reported as "no keys enrolled". Turning a damaged
        # file into "your security key was never registered" invites the user
        # to enrol again over the top of it.
        raise VaultError("the security-key file for this vault is unreadable") from exc
    return {"salt": salt,
            "keys": [entry for entry in entries if isinstance(entry, dict)
                     and entry.get("credential_id") and entry.get("wrapped")]}


def write_hardware(vault_path, salt, entries):
    """Replace the security-key file durably, or remove it when empty."""
    target = hardware_path(vault_path)
    if not entries:
        if os.path.exists(target):
            os.remove(target)
            _fsync_dir(os.path.dirname(os.path.abspath(target)) or ".")
        return target
    directory = os.path.dirname(os.path.abspath(target)) or "."
    handle, staged = tempfile.mkstemp(
        prefix="." + os.path.basename(target) + ".stage.", dir=directory)
    try:
        with os.fdopen(handle, "w", encoding="utf-8") as out:
            json.dump({"version": 1, "salt": salt, "keys": entries},
                      out, indent=2, sort_keys=True)
            out.write("\n")
            out.flush()
            os.fsync(out.fileno())
        os.chmod(staged, 0o600)
        os.replace(staged, target)
        staged = ""
        _fsync_dir(directory)
    finally:
        if staged and os.path.exists(staged):
            os.remove(staged)
    return target


def new_hardware_salt():
    return base64.b64encode(os.urandom(HARDWARE_SALT_BYTES)).decode("ascii")


def hardware_salt(vault_path):
    """The salt an enrolment ceremony must evaluate the PRF with.

    Returned rather than written, because the salt is only worth keeping once a
    key has actually been enrolled under it -- a minted-and-abandoned salt in
    the file would be a vault that claims security keys it does not have.
    add_hardware_key is what persists it, and it refuses a salt that disagrees
    with one already in use.
    """
    return read_hardware(vault_path)["salt"] or new_hardware_salt()


def add_hardware_key(vault_path, credential_id, wrapped, rp_id, label, created,
                     salt=""):
    """Enrol one security key, replacing any entry for the same credential."""
    label = re.sub(r"[\t\r\n]+", " ", str(label or "Security key")).strip()[:64]
    current = read_hardware(vault_path)
    if current["salt"] and salt and salt != current["salt"]:
        # Two enrolments raced, each having minted its own salt while the file
        # was still absent. The loser's envelope was sealed under a secret this
        # vault will never ask an authenticator for again, so it would enrol a
        # key that can never open it. Refusing is the only honest answer; the
        # user retries and picks up the salt that won.
        raise VaultError("this vault already uses a different security-key salt")
    salt = current["salt"] or salt or new_hardware_salt()
    entries = [entry for entry in current["keys"]
               if entry.get("credential_id") != credential_id]
    entries.append({"credential_id": credential_id, "wrapped": wrapped,
                    "rp_id": rp_id, "label": label or "Security key",
                    "created": created})
    write_hardware(vault_path, salt, entries)
    return {"salt": salt, "keys": entries}


def remove_hardware_key(vault_path, credential_id):
    current = read_hardware(vault_path)
    entries = [entry for entry in current["keys"]
               if entry.get("credential_id") != credential_id]
    write_hardware(vault_path, current["salt"], entries)
    return {"salt": current["salt"] if entries else "", "keys": entries}


def recovery_pubkey_pem(plaintext):
    """The vault's own recovery public key, or an exception saying why not."""
    for line in plaintext.splitlines():
        parts = line.split("\t")
        if parts[0] == "META_RECOVERY_PUBKEY" and len(parts) > 1 and parts[1].strip():
            try:
                return base64.b64decode(parts[1].strip())
            except Exception:
                raise VaultError("recovery public key is not valid base64")
    raise VaultError("no META_RECOVERY_PUBKEY row in vault")


def stage_recovery(vault_path, plaintext, vault_key):
    """Seal `vault_key` under the vault's recovery pubkey; return a staged path.

    Staging is the safety property. Decoding the stored key only proves it is
    base64; the vault must not be touched until openssl has actually accepted
    it and produced the ciphertext. The caller installs the result once the
    vault it describes is in place.

    Deliberately the same `openssl rsautl -encrypt -pubin` the rest of the
    project uses. It is deprecated in OpenSSL 3, but `spm doctor` and
    `spm forgot` read this file back with `rsautl -decrypt`; switching only the
    writer would be a padding decision made in one place out of three.
    """
    pub_pem = recovery_pubkey_pem(plaintext)
    target = recovery_path(vault_path)
    rec_dir = os.path.dirname(os.path.abspath(target)) or "."
    pub_fd, pub_file = tempfile.mkstemp(prefix="spm.recpub.")
    staged = ""
    try:
        os.write(pub_fd, pub_pem)
        os.close(pub_fd)
        pub_fd = -1
        out_fd, staged = tempfile.mkstemp(
            prefix="." + os.path.basename(target) + ".stage.", dir=rec_dir)
        os.close(out_fd)
        os.chmod(staged, 0o600)
        proc = subprocess.Popen(
            ["openssl", "rsautl", "-encrypt", "-pubin",
             "-inkey", pub_file, "-out", staged],
            stdin=subprocess.PIPE, stderr=subprocess.DEVNULL)
        try:
            proc.communicate(input=vault_key.encode("utf-8"), timeout=30)
        except subprocess.TimeoutExpired:
            proc.kill()
            raise VaultError("recovery encryption timed out")
        if proc.returncode != 0 or not os.path.getsize(staged):
            raise VaultError("the recovery public key was not usable")
        _fsync_path(staged)
        result, staged = staged, ""
        return result
    finally:
        if pub_fd != -1:
            os.close(pub_fd)
        if os.path.exists(pub_file):
            os.remove(pub_file)
        if staged and os.path.exists(staged):
            os.remove(staged)


# ----- tidying imported entries ----------------------------------------------
# A vault filled by importing from a phone arrives in two states worth fixing in
# bulk. Its notes carry the folder the entry belonged to, as text, because the
# exporting app had folders and the export format did not. And its service names
# are Android package identifiers -- com.duolingo, id.go.kemensos.pelaporan --
# which are what the phone knew the app by and not what its owner does.
#
# Both are proposals, never edits. `tidy_proposals` computes what would change
# and touches nothing; `apply_tidy` performs exactly the changes it was handed.
# Nothing here guesses in place: with hundreds of records the difference between
# a preview and a surprise is the whole feature.

TIDY_ORIGINAL_PREFIX = "app:"
_TIDY_FOLDER_RE = re.compile(r"(?i)\bfolder\s*:\s*(.*)$")
# A later "word:" ends the folder value. Notes are stored with their line breaks
# collapsed to spaces, so "folder: Work url: https://..." is one string and the
# folder is not the rest of it.
_TIDY_MARKER_RE = re.compile(r"\b[A-Za-z][A-Za-z0-9_-]{0,20}\s*:")

# The first label of a reverse-DNS package identifier. A name whose *first*
# segment is one of these reads backwards -- com.duolingo -- where a name whose
# *last* segment is one reads forwards, as duolingo.com does.
_TIDY_TLDS = frozenset("""
com net org edu gov mil int io co me app dev xyz info biz online site
id uk de fr jp cn au ca in br ru it es nl se no fi dk pl ch at be cz gr pt
ro hu tr kr tw hk sg my th vn ph nz za mx ar cl pe ve ir sa ae il eg ng ke
""".split())
# Second-level labels that are part of the suffix rather than the name, so
# example.co.uk yields "Example" and not "Co".
_TIDY_SECOND_LEVEL = frozenset(("co", "com", "net", "org", "ac", "gov", "edu",
                                "go", "or", "ne", "sch", "mil"))
# Trailing segments that name the platform rather than the app, so
# com.example.android resolves to "Example".
_TIDY_GENERIC_TAIL = frozenset(("android", "app", "apps", "mobile", "client",
                                "application", "main", "prod", "release",
                                "free", "pro", "lite", "beta"))


def _tidy_titlecase(word):
    parts = [p for p in re.split(r"[_\-\s]+", word) if p]
    out = []
    for part in parts:
        # Something already capitalised the way a brand is stays as it is:
        # "eBay" and "PayPal" must not become "Ebay" and "Paypal".
        out.append(part if any(c.isupper() for c in part) else part.capitalize())
    return " ".join(out)


def derive_app_name(label):
    """A human name for a package identifier or domain, or "" to leave it be.

    Deliberately conservative: anything that does not clearly read as a package
    identifier or a hostname is returned unchanged, because a label somebody
    typed themselves is not this function's business.
    """
    text = (label or "").strip()
    if not text or " " in text or "/" in text:
        return ""
    parts = [p for p in text.split(".") if p]
    if len(parts) < 2 or len(parts) != text.count(".") + 1:
        return ""
    if not all(re.fullmatch(r"[A-Za-z0-9_-]+", p) for p in parts):
        return ""

    head, tail = parts[0].lower(), parts[-1].lower()
    if head in _TIDY_TLDS and tail not in _TIDY_TLDS:
        # Reverse-DNS: com.duolingo, id.go.kemensos.pelaporan.
        chosen = parts[-1]
        if chosen.lower() in _TIDY_GENERIC_TAIL and len(parts) > 2:
            chosen = parts[-2]
    elif tail in _TIDY_TLDS:
        # Forward hostname: mail.google.com, example.co.uk.
        index = -2
        if len(parts) >= 3 and parts[-2].lower() in _TIDY_SECOND_LEVEL:
            index = -3
        chosen = parts[index]
    else:
        return ""

    if chosen.lower() in _TIDY_TLDS or chosen.lower() in _TIDY_SECOND_LEVEL:
        return ""
    name = _tidy_titlecase(chosen)
    if not name or name == text:
        return ""
    return name


def folder_from_notes(notes):
    """The folder a note names, or "" when it names none."""
    match = _TIDY_FOLDER_RE.search(notes or "")
    if not match:
        return ""
    value = match.group(1)
    following = _TIDY_MARKER_RE.search(value)
    if following:
        value = value[:following.start()]
    value = " ".join(value.split())
    if not value or len(value) > ATTRS_FOLDER_MAX:
        return ""
    return value


def _tidy_note_with_original(notes, original):
    """Keep the identifier the phone knew, once, and only if it is not there."""
    text = notes or ""
    marker = "%s %s" % (TIDY_ORIGINAL_PREFIX, original)
    if original in text:
        return text
    return ("%s %s" % (text.strip(), marker)).strip() if text.strip() else marker


# Which hosts count as sensitive is the user's list, kept in the vault. SPM
# ships no opinion about it and no examples: a built-in list would be a
# maintenance burden, would be wrong for somebody, and would put in the source
# and in every clone of the repository exactly the words this feature exists to
# keep off a screen. The list lives in META_HIDDEN_HOSTS because it is itself
# sensitive -- a plaintext config file naming them would leak the very thing
# being protected.
HIDDEN_HOSTS_TAG = "META_HIDDEN_HOSTS"
HIDDEN_HOSTS_MAX = 200


def hidden_hosts(plaintext):
    """The host words this vault treats as sensitive, lowercased and unique."""
    for line in (plaintext or "").splitlines():
        parts = line.split("\t")
        if parts[0] == HIDDEN_HOSTS_TAG and len(parts) > 1:
            return _split_hosts(parts[1])
    return []


def _split_hosts(raw):
    seen, out = set(), []
    for token in re.split(r"[^A-Za-z0-9.-]+", (raw or "").lower()):
        token = token.strip(".-")
        if not token or token in seen:
            continue
        seen.add(token)
        out.append(token)
        if len(out) >= HIDDEN_HOSTS_MAX:
            break
    return out


def set_hidden_hosts(plaintext, raw):
    """Store the list, replacing any previous one. Returns the new plaintext."""
    hosts = _split_hosts(raw)
    rows = [line for line in (plaintext or "").splitlines()
            if line.split("\t")[0] != HIDDEN_HOSTS_TAG]
    if hosts:
        rows.append("%s\t%s\t-\t-\t-\t-" % (HIDDEN_HOSTS_TAG, " ".join(hosts)))
    return "\n".join(rows) + "\n"


def looks_sensitive(label, url, hosts):
    """Whether an entry matches the vault's own list.

    A suggestion, and only ever that: the stored per-entry flag is what
    governs, and nothing here changes it.

    Matching is on whole hosts, not on the pieces of one. Splitting a listed
    host into its labels and looking for any of them proposed hiding every
    entry that merely shared a suffix -- one list of ".invalid" hosts had SPM
    offering to hide an unrelated admin account, because both ended in
    "invalid". A URL matches the host itself or a subdomain of it; a label
    matches only when it is the whole host or its leading name.
    """
    if not hosts:
        return False
    host = ""
    try:
        host = (urllib.parse.urlsplit(url or "").hostname or "").lower()
    except ValueError:
        host = ""
    key = re.sub(r"[^a-z0-9]", "", (label or "").lower())
    for listed in hosts:
        if host and (host == listed or host.endswith("." + listed)):
            return True
        if not key:
            continue
        if key == re.sub(r"[^a-z0-9]", "", listed):
            return True
        # The leading name on its own, so a bare label matches a listed host.
        # Long enough not to collide with a common word by accident.
        leading = listed.split(".")[0]
        if len(leading) >= 4 and key == leading:
            return True
    return False


# --- Browser bindings: which records a page may see, and on what terms ------
#
# One implementation. The CLI's `bridge-list` and `bridge-get` each carried
# their own copy of this, built inline in a shell heredoc, and the two had
# already begun to disagree in shape if not yet in behaviour. A matcher that
# decides whether a page may see a credential is the last place to keep two of.

BRIDGE_URL_RE = re.compile(r"https?://[^\s]+")
BRIDGE_SCHEME_RE = re.compile(r"(?i)^https?://")


def _binding_host(token):
    """The host a bound URL names, wildcard preserved. '' if it names none."""
    try:
        return (urllib.parse.urlsplit(token).hostname or "").lower().strip(".")
    except ValueError:
        return ""


def wildcard_scope(pattern):
    """The parent host an opt-in '*.' scope covers, or '' if it is not one.

    A wildcard is only ever written by hand into a record's URL field. It is
    never inferred from a bare hostname: without a public suffix list, treating
    'foo.co.uk' as also covering '.co.uk' would bind a record to every site in
    the United Kingdom, and bundling a PSL is a data dependency this project
    does not have.

    The one guard that does not need a PSL is a floor on how much can be
    claimed: '*.com' is refused because no record legitimately covers a whole
    top-level domain. It is a floor and not a substitute -- '*.co.uk' still
    parses, because SPM cannot tell it from '*.example.com'. That is the cost
    of having no PSL, and the reason this is opt in per record rather than
    inferred for every record.
    """
    if not pattern.startswith("*."):
        return ""
    parent = pattern[2:].strip(".")
    if not parent or "*" in parent:
        return ""
    if len(parent.split(".")) < 2:
        return ""
    return parent


def host_in_scope(requested, pattern):
    """Whether a page's host is covered by one binding pattern."""
    requested = (requested or "").lower().strip(".")
    pattern = (pattern or "").lower().strip(".")
    if not requested or not pattern:
        return False
    parent = wildcard_scope(pattern)
    if parent:
        # The parent itself and anything under it. The dot is what keeps
        # '*.example.com' off 'notexample.com', which a bare suffix test
        # would match.
        return requested == parent or requested.endswith("." + parent)
    return requested == pattern


def record_bindings(label, notes, url):
    """Every host pattern a record is bound to, with the scheme each requires.

    Returns a list of (pattern, scheme) pairs. The scheme is 'https' only when
    the binding was written as an https URL; a label-derived binding has no
    scheme of its own and does not demand one.
    """
    bindings, seen = [], set()

    def add(pattern, scheme):
        pattern = (pattern or "").lower().strip(".")
        if not pattern or (pattern, scheme) in seen:
            return
        seen.add((pattern, scheme))
        bindings.append((pattern, scheme))

    add((label or "").lower().strip("."), "")
    # The url field is the intended binding source. Notes are still scanned so
    # that vaults written before 2.12.0 -- where a URL could only live in the
    # notes -- keep matching exactly as they did, with no rewrite on upgrade.
    tokens = ([url] if url else []) + BRIDGE_URL_RE.findall(notes or "")
    for token in tokens:
        if not BRIDGE_SCHEME_RE.match(token):
            continue
        host = _binding_host(token)
        if host:
            add(host, "https" if token.lower().startswith("https://") else "http")
    return bindings


# Refusals the bridge can produce. Named here because the native host projects
# every error onto a fixed set, and a refusal the host has not been told about
# reaches the extension as a generic one.
BRIDGE_NOT_BOUND = "record is not bound to this hostname"
BRIDGE_INSECURE = "record requires a secure page"


def bridge_match(requested, scheme, label, notes, url):
    """Whether this page may see this record, and why not when it may not.

    Returns (True, "") or (False, reason).

    Downgrade protection is the second half and it fails closed. A record bound
    to an https URL is refused on an http page, and refused again when the
    caller did not say what the page's scheme was -- an unknown scheme cannot
    be shown to be https, and a credential fill is not the place to assume the
    safe answer. A caller that predates the scheme argument therefore stops
    filling https-bound records rather than quietly keeping the old behaviour.
    """
    scheme = (scheme or "").lower().strip(":")
    matched = [(pattern, bound) for pattern, bound in record_bindings(label, notes, url)
               if host_in_scope(requested, pattern)]
    if not matched:
        return False, BRIDGE_NOT_BOUND
    # Any binding that permits this page is enough; a record bound to both
    # http and https on the same host is not downgraded by the https one.
    for _pattern, bound in matched:
        if bound != "https" or scheme == "https":
            return True, ""
    return False, BRIDGE_INSECURE


def tidy_proposals(plaintext):
    """What a tidy would change, as data. Changes nothing.

    Each proposal names the record, what is proposed for it, and the before and
    after of every field involved, so a caller can render it for review without
    knowing any of the rules above.
    """
    proposals = []
    hosts = hidden_hosts(plaintext)
    for line in (plaintext or "").splitlines():
        parts = line.split("\t")
        if not parts or not parts[0].isdigit() or len(parts) < 6:
            continue
        record_id, label = parts[0], parts[1]
        notes = parts[4] if len(parts) > 4 else ""
        attrs = parts[7] if len(parts) > 7 else ""
        folder, fields, hidden = decode_attrs(attrs)

        changes = {}
        proposed_folder = folder_from_notes(notes)
        if proposed_folder and proposed_folder != folder:
            changes["folder"] = {"from": folder, "to": proposed_folder}

        new_notes = notes
        proposed_label = derive_app_name(label)
        if proposed_label and proposed_label != label:
            changes["label"] = {"from": label, "to": proposed_label}
            new_notes = _tidy_note_with_original(notes, label)
            if new_notes != notes:
                changes["notes"] = {"from": notes, "to": new_notes}

        # Proposed, never applied here, and only for an entry that is not
        # already hidden -- re-proposing a decision someone has made is how a
        # review becomes noise people click through.
        url = parts[6] if len(parts) > 6 else ""
        if not hidden and looks_sensitive(label, url, hosts):
            changes["hidden"] = {"from": False, "to": True}

        if changes:
            proposals.append({"id": record_id, "label": label,
                              "changes": changes})
    return proposals


TIDY_LABEL_MAX = 200


def apply_tidy(plaintext, selections):
    """Apply reviewed changes. `selections` maps id -> {"label": str,
    "hidden": bool}.

    No rule here decides anything. The guess `tidy_proposals` made is only a
    guess -- no heuristic gets both com.lsdroid.cerberuss and com.spotify.music
    right -- so what gets written is what came back from the review, and this
    function's job is to refuse anything that review should not be able to say.

    A record may only be touched if it had a proposal: a stale preview, or a
    request naming a record that has since changed, must not be able to write
    something the vault was never asked about. The folder is taken from the
    record's own notes rather than from the request, because that one is not a
    guess and there is nothing to review.
    """
    proposals = {p["id"]: p for p in tidy_proposals(plaintext)}
    chosen = {}
    for record_id, values in (selections or {}).items():
        key = str(record_id)
        if key not in proposals:
            continue
        chosen[key] = values or {}
    if not chosen:
        return plaintext, 0

    out, changed = [], 0
    for line in (plaintext or "").splitlines():
        parts = line.split("\t")
        record_id = parts[0] if parts else ""
        if not record_id.isdigit() or record_id not in chosen:
            out.append(line)
            continue
        while len(parts) < 8:
            parts.append("")
        proposal = proposals[record_id]
        changes = proposal["changes"]
        touched = False

        if "label" in changes:
            label = str(chosen[record_id].get("label") or "").strip()
            if not label:
                label = changes["label"]["to"]
            label = " ".join(label.split())[:TIDY_LABEL_MAX]
            if label and label != parts[1]:
                original = parts[1]
                parts[1] = label
                parts[4] = _tidy_note_with_original(parts[4], original)
                touched = True

        # Both attribute changes go through one decode/encode. Two of them
        # would make the second overwrite whatever the first had just written,
        # because encode_attrs takes the whole column and not a patch.
        if "folder" in changes or "hidden" in changes:
            folder, fields, hidden = decode_attrs(parts[7])
            if "folder" in changes:
                folder = changes["folder"]["to"]
            if "hidden" in changes:
                # Only when the review said so. An unticked row keeps the
                # decision it already had.
                hidden = bool(chosen[record_id].get("hidden", True))
            parts[7] = encode_attrs(folder, fields, hidden)
            touched = True

        out.append("\t".join(parts))
        if touched:
            changed += 1
    return "\n".join(out) + ("\n" if (plaintext or "").endswith("\n") else ""), changed


# ----- split recovery --------------------------------------------------------
# The recovery file and its private key have to survive together: lose the PEM
# and the capsule is inert, leak the PEM while somebody holds the capsule and
# the vault is open. Shamir shares replace that pair with a threshold -- any
# `t` of `n` reconstruct the vault key, any `t - 1` reveal nothing at all --
# so the material can be spread across people or places without any single one
# of them being either a single point of failure or a single point of trust.
#
# What is split is the vault key itself, which is stable for the life of the
# vault: `rewrap` changes only the master-password envelope around it. Shares
# minted once therefore keep working after a master-password change, which is
# the property that makes them worth writing on paper. They are also exactly
# what `recover()` already consumes, so this adds an input to the existing
# recovery path rather than a second one beside it.

SHARE_MAGIC = "SPMS1"
SHARE_SET_BYTES = 4
_GF_EXP = [0] * 512
_GF_LOG = [0] * 256


def _build_gf_tables():
    """Log tables for GF(2**8) with the AES polynomial, generator 3.

    Not generator 2: 2 has multiplicative order 51 under 0x11b, so powers of it
    reach a fifth of the field and the tables would be silently wrong for the
    rest. 3 is primitive and enumerates all 255 non-zero elements.
    """
    x = 1
    for power in range(255):
        _GF_EXP[power] = x
        _GF_LOG[x] = power
        # x * 3 == (x * 2) XOR x, with the reduction when the high bit is set.
        doubled = (x << 1) ^ (0x11B if x & 0x80 else 0)
        x = doubled ^ x
    for power in range(255, 512):
        _GF_EXP[power] = _GF_EXP[power - 255]


_build_gf_tables()


def _gf_mul(a, b):
    if a == 0 or b == 0:
        return 0
    return _GF_EXP[_GF_LOG[a] + _GF_LOG[b]]


def _gf_inv(a):
    if a == 0:
        raise VaultError("share arithmetic divided by zero")
    return _GF_EXP[255 - _GF_LOG[a]]


def split_secret(secret, threshold, count):
    """Split `secret` (bytes) into `count` shares, any `threshold` sufficing.

    Every coefficient above the constant term is drawn uniformly, including
    the highest, and including zero. That is deliberate and should not be
    "fixed" into drawing the top coefficient from 1..255: the security proof
    needs the polynomial to be uniform over all of degree <= threshold-1, and
    forcing the leading term non-zero excludes one candidate secret for any
    given set of threshold-1 shares. Uniform coefficients leak exactly nothing.
    """
    if not isinstance(secret, bytes) or not secret:
        raise VaultError("there is no secret to split")
    if not 2 <= threshold <= 255:
        raise VaultError("threshold must be between 2 and 255")
    if not threshold <= count <= 255:
        raise VaultError(
            "a set of %d shares cannot have a threshold of %d"
            % (count, threshold))

    shares = [bytearray() for _ in range(count)]
    for byte in secret:
        coefficients = [byte] + list(os.urandom(threshold - 1))
        for index in range(count):
            x = index + 1  # never 0: f(0) is the secret itself
            acc = 0
            for coefficient in reversed(coefficients):
                acc = _gf_mul(acc, x) ^ coefficient
            shares[index].append(acc)
    return [(index + 1, bytes(share)) for index, share in enumerate(shares)]


def combine_shares(shares):
    """Reconstruct the secret from (x, bytes) pairs by interpolating at 0."""
    if len(shares) < 2:
        raise VaultError("at least two shares are needed")
    xs = [x for x, _ in shares]
    if len(set(xs)) != len(xs):
        raise VaultError("the same share was given more than once")
    if any(not 1 <= x <= 255 for x in xs):
        raise VaultError("a share carries an impossible index")
    lengths = {len(payload) for _, payload in shares}
    if len(lengths) != 1:
        raise VaultError("these shares are different lengths and cannot belong "
                         "to one set")

    secret = bytearray()
    for position in range(lengths.pop()):
        total = 0
        for i, (xi, payload) in enumerate(shares):
            numerator, denominator = 1, 1
            for j, (xj, _) in enumerate(shares):
                if i == j:
                    continue
                numerator = _gf_mul(numerator, xj)
                denominator = _gf_mul(denominator, xi ^ xj)
            total ^= _gf_mul(payload[position],
                             _gf_mul(numerator, _gf_inv(denominator)))
        secret.append(total)
    return bytes(secret)


def _share_body(threshold, index, set_id, payload):
    return "%s-%d-%d-%s-%s" % (
        SHARE_MAGIC, threshold, index, set_id.hex().upper(),
        base64.b32encode(payload).decode("ascii").rstrip("="))


def _share_checksum(body):
    return hashlib.sha256(body.encode("ascii")).hexdigest()[:4].upper()


def encode_share(threshold, index, set_id, payload):
    """One share as a single transcribable token, with its own checksum.

    The checksum covers the share's own text, not the secret. A mistyped share
    is then rejected the moment it is read, rather than combining cleanly into
    a wrong key that only fails later against the vault -- at which point
    nothing says which of the shares was wrong.
    """
    body = _share_body(threshold, index, set_id, payload)
    return "%s-%s" % (body, _share_checksum(body))


def decode_share(text):
    """(threshold, index, set_id, payload) or an exception naming the problem."""
    token = "".join((text or "").split()).upper()
    parts = token.split("-")
    if len(parts) != 6 or parts[0] != SHARE_MAGIC:
        raise VaultError("this is not an SPM recovery share")
    _, threshold_text, index_text, set_text, data_text, checksum = parts
    body = "-".join(parts[:5])
    if _share_checksum(body) != checksum:
        raise VaultError("share %s did not survive transcription; its checksum "
                         "does not match" % (index_text or "?"))
    if not threshold_text.isdigit() or not index_text.isdigit():
        raise VaultError("a share carries a non-numeric threshold or index")
    threshold, index = int(threshold_text), int(index_text)
    if not 2 <= threshold <= 255 or not 1 <= index <= 255:
        raise VaultError("a share carries an impossible threshold or index")
    try:
        set_id = bytes.fromhex(set_text)
    except ValueError:
        raise VaultError("a share carries a malformed set identifier")
    if len(set_id) != SHARE_SET_BYTES:
        raise VaultError("a share carries a set identifier of the wrong size")
    padding = "=" * (-len(data_text) % 8)
    try:
        payload = base64.b32decode(data_text + padding)
    except Exception:
        raise VaultError("a share carries a malformed payload")
    if not payload:
        raise VaultError("a share carries no payload")
    return threshold, index, set_id, payload


def shares_meta(plaintext):
    """(set_id, threshold, count, minted) for the vault's share set, or None.

    The row records that a set exists and which one, never any share. It is
    what lets `doctor` say a vault has split recovery and what catches shares
    from a different vault before they are combined.
    """
    for line in plaintext.splitlines():
        parts = line.split("\t")
        if parts[0] == "META_RECOVERY_SHARES" and len(parts) >= 5:
            try:
                set_id = bytes.fromhex(parts[1].strip())
            except ValueError:
                return None
            if len(set_id) != SHARE_SET_BYTES:
                return None
            if not parts[2].strip().isdigit() or not parts[3].strip().isdigit():
                return None
            return (set_id, int(parts[2].strip()), int(parts[3].strip()),
                    parts[4].strip())
    return None


def stamp_shares_meta(plaintext, set_id, threshold, count, minted):
    """Replace any existing share row; a vault has at most one live set."""
    rows = [line for line in plaintext.splitlines()
            if line.split("\t", 1)[0] != "META_RECOVERY_SHARES"]
    row = "META_RECOVERY_SHARES\t%s\t%d\t%d\t%s" % (
        set_id.hex().upper(), threshold, count, minted)
    # After the version row, which stamp_version keeps first.
    insert_at = 1 if rows and rows[0].split("\t", 1)[0] == "META_VAULT_VERSION" else 0
    rows.insert(insert_at, row)
    return "\n".join(rows) + ("\n" if plaintext.endswith("\n") else "")


def install_vault_file(source, dest, archive=True, expect_sha256=""):
    """Put `source` at `dest` durably, keeping what was there recoverable.

    The shell carried three separate copies of cp-chmod-mv for this -- bundle
    restore, history restore, sync install -- and none of them fsynced, so a
    crash immediately after any of them could leave the new name over blocks
    that were never written. Worse, bundle restore overwrote a live vault with
    no archive and no .bak at all, which is the one write in SPM that could not
    be undone.

    Ordering matches write_vault: the previous generation is archived and
    copied to .bak BEFORE the rename, because after it there is nothing left to
    copy. Returns True when something was replaced.

    `expect_sha256` is checked against the staged copy, before the rename and
    after the bytes have been written -- so a copy that silently lost or
    changed bytes is caught while the destination is still intact. Sync pull
    already did this by hand; every caller gets it by asking for it.
    """
    dest_dir = os.path.dirname(os.path.abspath(dest)) or "."
    dest_name = os.path.basename(dest)
    replaced = os.path.exists(dest)

    tmp_fd, tmp_path = tempfile.mkstemp(prefix="." + dest_name + ".install.",
                                        dir=dest_dir)
    os.close(tmp_fd)
    try:
        shutil.copyfile(source, tmp_path)
        os.chmod(tmp_path, 0o600)
        if expect_sha256:
            digest = hashlib.sha256()
            with open(tmp_path, "rb") as handle:
                for chunk in iter(lambda: handle.read(1 << 20), b""):
                    digest.update(chunk)
            if not hmac.compare_digest(digest.hexdigest(), expect_sha256.lower()):
                raise VaultError(
                    "the staged copy does not match the digest it was promised; "
                    "%s was left untouched" % dest)
        if replaced:
            # .bak always, archiving only when asked. A recovery file has no
            # history directory of its own -- archiving one would file it under
            # a scope derived from its own path -- but it is still the only
            # wrapper around the previous vault key, so it gets a .bak like
            # everything else.
            if archive:
                archive_generation(dest)
            shutil.copy2(dest, dest + ".bak")
            os.chmod(dest + ".bak", 0o600)
        _fsync_path(tmp_path)
        os.replace(tmp_path, dest)
        tmp_path = ""
        os.chmod(dest, 0o600)
        _fsync_dir(dest_dir)
    finally:
        if tmp_path and os.path.exists(tmp_path):
            os.remove(tmp_path)
    return replaced


def install_recovery(vault_path, staged):
    target = recovery_path(vault_path)
    os.replace(staged, target)
    os.chmod(target, 0o600)
    _fsync_dir(os.path.dirname(os.path.abspath(target)) or ".")


# ----- reading ---------------------------------------------------------------

def unwrap_key(vault_path, master):
    """The vault key alone, or None when the vault predates the container."""
    with open(vault_path, "rb") as handle:
        raw = handle.read()
    modern = parse_container_aead(raw)
    if modern is not None:
        kdf, envelope, _ = modern
        key = unwrap_key_aead(kdf, envelope, master)
    else:
        parts = parse_container(raw)
        if parts is None:
            return None
        key = gpg_decrypt(master, parts[0]).decode("utf-8")
    if not key:
        raise VaultError("vault key envelope decrypted to nothing")
    return key


def read_vault(vault_path, master):
    """(plaintext, vault_key) for any vault file, whatever format it is in.

    Not only the live vault: .bak files, history snapshots and synced copies
    are the same container, and everything that proves one opens before
    overwriting the live vault has to come through here.

    vault_key is None for formats 1 and 2, which were sealed under the master
    password directly.
    """
    scope = "scope=%s" % _scope_of(vault_path)
    try:
        with open(vault_path, "rb") as handle:
            raw = handle.read()
    except OSError:
        record_event("unlock", "fail", scope + ",reason=missing")
        raise
    modern = parse_container_aead(raw)
    if modern is not None:
        kdf, envelope, cipher = modern
        try:
            key = unwrap_key_aead(kdf, envelope, master)
        except Exception:
            record_event("unlock", "fail", scope + ",reason=bad-master")
            raise
        if not key:
            record_event("unlock", "fail", scope + ",reason=bad-master")
            raise VaultError("vault key envelope decrypted to nothing")
        try:
            plaintext = unseal(key, cipher).decode("utf-8", errors="ignore")
        except VaultError:
            # The envelope opened, so the password was right and the data
            # block is damaged. gpg could never separate these two -- it
            # refused both identically, and the log had to say so -- and an
            # authenticated data block is what makes the distinction real.
            record_event("unlock", "fail", scope + ",reason=corrupt")
            raise VaultIntegrityError(
                "this vault's data failed authentication; the master password "
                "was right, so the file itself is damaged -- restore the .bak "
                "or a history snapshot beside it")
        record_event("unlock", "ok", scope)
        return plaintext, key
    try:
        parts = parse_container(raw)
        if parts is None:
            plaintext = gpg_decrypt(master, raw).decode("utf-8", errors="ignore")
            record_event("unlock", "ok", scope)
            return plaintext, None
        key = gpg_decrypt(master, parts[0]).decode("utf-8")
        if not key:
            raise VaultError("vault key envelope decrypted to nothing")
        plaintext = gpg_decrypt(key, parts[1]).decode("utf-8", errors="ignore")
    except Exception:
        # For a gpg-sealed vault a wrong master password and a damaged file
        # stay indistinguishable -- gpg refuses both the same way -- so the log
        # says the honest thing rather than guessing which it was.
        record_event("unlock", "fail", scope + ",reason=bad-master")
        raise
    record_event("unlock", "ok", scope)
    return plaintext, key


def read_vault_with_key(vault_path, vault_key):
    """Plaintext from a format-3 vault using a key that is already unwrapped.

    Returns None when the file is not a container -- formats 1 and 2 are sealed
    under the master password directly and have no separate key -- so a caller
    holding a stale key falls back to the master rather than failing.

    A format-3 read is two gpg invocations: one to unwrap the key envelope
    under the master password, one to decrypt the data under that key. The
    envelope is the expensive half and its answer does not change between
    reads, so a caller that can hold the key skips it. Nothing here weakens the
    format: the key is exactly what the master password would have produced.
    """
    with open(vault_path, "rb") as handle:
        raw = handle.read()
    modern = parse_container_aead(raw)
    if modern is not None:
        return unseal(vault_key, modern[2]).decode("utf-8", errors="ignore")
    parts = parse_container(raw)
    if parts is None:
        return None
    return gpg_decrypt(vault_key, parts[1]).decode("utf-8", errors="ignore")


# ----- writing ---------------------------------------------------------------

def write_vault(vault_path, master, plaintext, vault_key=None):
    """Install `plaintext` as an AEAD vault. Returns the vault key used.

    A gpg-sealed vault becomes an openssl-sealed one here, on its next write,
    with no flag day and nothing for the user to run. The upgrade is invisible
    to everything downstream because the vault key does not change: the
    recovery file still names it, Shamir shares still reconstruct it, and a
    .bak from before the upgrade still opens under the same master password.
    That is the whole reason format 3 separated the key from the password.

    A write reuses the key the vault already has. Minting a fresh one whenever
    the caller did not supply it would strand every .bak, history snapshot and
    synced copy that the current recovery file can still open, and the whole
    point of a separate vault key is that it survives password changes.

    Migration from formats 1 and 2 is ordered so that no instant is
    unrecoverable. The new recovery file is staged first, before anything is
    encrypted, so a vault whose recovery pubkey is unusable refuses with
    nothing changed. The container is then installed BEFORE the recovery file
    is swapped, with the key envelope sealed under the master password that
    .recovery still names -- which makes the window between the two harmless,
    because the recovered secret still opens the vault as a password. The
    reverse order has no such route.
    """
    vault_dir = os.path.dirname(os.path.abspath(vault_path)) or "."
    vault_name = os.path.basename(vault_path)
    plaintext = stamp_version(plaintext)

    # `master is None` means "keep the key envelope exactly as it is". A caller
    # holding the vault key but not the password -- a session unlocked by a
    # security key -- has nothing to seal an envelope with, and the empty
    # string is not a safe stand-in: it would succeed, and quietly re-wrap the
    # vault under an empty password. Distinguishing None from "" is the whole
    # of that guard.
    keep_envelope = master is None
    if keep_envelope and vault_key is None:
        raise VaultError("a write without a master password needs the vault key")

    migrating = False
    if vault_key is None and os.path.exists(vault_path):
        vault_key = unwrap_key(vault_path, master)
    if vault_key is None:
        vault_key = new_vault_key()
        migrating = True

    staged_recovery = stage_recovery(vault_path, plaintext, vault_key) if migrating else ""

    tmp_fd, tmp_path = tempfile.mkstemp(prefix="." + vault_name + ".stage.", dir=vault_dir)
    os.close(tmp_fd)
    try:
        os.chmod(tmp_path, 0o600)
        cipher = seal(vault_key, plaintext.encode("utf-8"))
        if keep_envelope:
            with open(vault_path, "rb") as handle:
                existing = parse_container_aead(handle.read())
            if existing is None:
                raise VaultError("this vault has no key envelope to keep")
            kdf, envelope, _ = existing
            container = build_container_aead(kdf["salt"], envelope, cipher,
                                             kdf["n"], kdf["r"], kdf["p"])
        else:
            kdf_salt = os.urandom(KDF_SALT_BYTES)
            envelope = seal(derive_kek(master, kdf_salt), vault_key.encode("utf-8"))
            container = build_container_aead(kdf_salt, envelope, cipher)
        with open(tmp_path, "wb") as handle:
            handle.write(container)

        if os.path.exists(vault_path):
            archive_generation(vault_path)
            shutil.copy2(vault_path, vault_path + ".bak")
            os.chmod(vault_path + ".bak", 0o600)

        # The rename is atomic but not durable on its own: flush the ciphertext
        # first so a crash cannot leave the new name over unwritten blocks.
        _fsync_path(tmp_path)
        os.replace(tmp_path, vault_path)
        tmp_path = ""
        os.chmod(vault_path, 0o600)
        _fsync_dir(vault_dir)

        if staged_recovery:
            # Second, deliberately. A failure here leaves .recovery naming the
            # master password, which still unwraps this container, so it is
            # reported rather than undoing the user's save.
            try:
                install_recovery(vault_path, staged_recovery)
                staged_recovery = ""
            except Exception as exc:
                sys.stderr.write(
                    "warning: the vault was migrated but its recovery file "
                    "still holds the master password (%s)\n" % exc)
        # After os.replace and the fsync, so a recorded write is one that
        # actually reached the disk rather than one that was attempted.
        record_event("write", "ok", "scope=%s,records=%d" % (
            _scope_of(vault_path), _record_count(plaintext)))
        return vault_key
    finally:
        if tmp_path and os.path.exists(tmp_path):
            os.remove(tmp_path)
        if staged_recovery and os.path.exists(staged_recovery):
            os.remove(staged_recovery)


def rewrap(vault_path, old_master, new_master):
    """Change only the master-password envelope, given the old password."""
    key = unwrap_key(vault_path, old_master)
    if key is None:
        raise VaultError("vault must be migrated before its key can be rewrapped")
    if not key:
        raise VaultError("vault key envelope decrypted to nothing")
    return rewrap_with_key(vault_path, key, new_master)


def rewrap_with_key(vault_path, vault_key, new_master):
    """Change only the master-password envelope, given the vault key.

    The vault ciphertext stays byte-identical -- for a vault already on the
    current format -- and the recovery file is not touched at all, because
    both key off the vault key, which does not change.
    This is the reason for separating the vault key: a password change stops
    being a re-encryption of everything the user owns.

    Taking the key rather than the old password lets a caller that has just
    read the vault skip an entire gpg invocation, which is the dominant cost
    of any vault operation.
    """
    with open(vault_path, "rb") as handle:
        raw = handle.read()
    key = vault_key
    kdf_salt = os.urandom(KDF_SALT_BYTES)
    envelope = seal(derive_kek(new_master, kdf_salt), key.encode("utf-8"))
    modern = parse_container_aead(raw)
    if modern is not None:
        updated = build_container_aead(kdf_salt, envelope, modern[2])
    else:
        parts = parse_container(raw)
        if parts is None:
            raise VaultError(
                "vault must be migrated before its key can be rewrapped")
        # A gpg-sealed vault is upgraded here rather than rewrapped in place.
        # The two cannot both hold: the new envelope is openssl-sealed, so the
        # gpg data block beside it would be unreadable to the reader that
        # opens the envelope. Re-sealing the data costs one decryption, which
        # a password change was already paying for, and it means the last
        # vaults on the old backend leave it the next time anyone touches
        # them rather than lingering until a write happens to come along.
        updated = build_container_aead(
            kdf_salt, envelope,
            seal(key, gpg_decrypt(key, parts[1])))

    vault_dir = os.path.dirname(os.path.abspath(vault_path)) or "."
    fd, staged = tempfile.mkstemp(
        prefix="." + os.path.basename(vault_path) + ".rewrap.", dir=vault_dir)
    try:
        os.write(fd, updated)
        os.fsync(fd)
        os.close(fd)
        fd = -1
        os.chmod(staged, 0o600)
        archive_generation(vault_path)
        shutil.copy2(vault_path, vault_path + ".bak")
        os.chmod(vault_path + ".bak", 0o600)
        os.replace(staged, vault_path)
        staged = ""
        os.chmod(vault_path, 0o600)
        _fsync_dir(vault_dir)
    finally:
        if fd != -1:
            os.close(fd)
        if staged and os.path.exists(staged):
            os.remove(staged)
    record_event("rewrap", "ok", "scope=%s" % _scope_of(vault_path))
    return key


def recover(vault_path, secret, out_path):
    """Open a vault with a secret recovered from the .recovery file.

    What that file holds depends on when it was last written: formats 3 and 5
    store the vault key, the formats before them stored the master password,
    and a
    vault caught mid-migration is described by neither. Try every reading
    rather than assume -- the master-password route is also what makes the
    migration window recoverable, because the key envelope of a just-migrated
    vault is sealed under exactly the password the stale file still names.

    Returns (vault_key, recovery_is_stale). A stale recovery file recovered
    this vault by luck and will not recover it again once the envelope is
    rewrapped, so the caller must refresh it.
    """
    with open(vault_path, "rb") as handle:
        raw = handle.read()

    modern = parse_container_aead(raw)
    if modern is not None:
        kdf, envelope, cipher = modern
        try:
            plaintext = unseal(secret, cipher).decode("utf-8", errors="ignore")
            key, stale = secret, False
        except VaultError:
            # Not the vault key, so read it as the master password the older
            # recovery files hold. A failure here is genuinely "this file does
            # not open this vault" rather than a guess between the two.
            try:
                key = unwrap_key_aead(kdf, envelope, secret)
            except VaultError:
                raise VaultError("the recovery file does not open this vault")
            if not key:
                raise VaultError("vault key envelope decrypted to nothing")
            plaintext = unseal(key, cipher).decode("utf-8", errors="ignore")
            stale = True
        write_plaintext(out_path, plaintext)
        return key, stale

    parts = parse_container(raw)

    if parts is None:
        # Formats 1 and 2: the recovery file can only hold the password.
        write_plaintext(out_path, gpg_decrypt(secret, raw).decode("utf-8", errors="ignore"))
        return None, False

    try:
        plaintext = gpg_decrypt(secret, parts[1]).decode("utf-8", errors="ignore")
        key, stale = secret, False
    except subprocess.CalledProcessError:
        try:
            key = gpg_decrypt(secret, parts[0]).decode("utf-8")
        except subprocess.CalledProcessError:
            raise VaultError("the recovery file does not open this vault")
        if not key:
            raise VaultError("vault key envelope decrypted to nothing")
        plaintext = gpg_decrypt(key, parts[1]).decode("utf-8", errors="ignore")
        stale = True
    write_plaintext(out_path, plaintext)
    return key, stale


# ----- command interface -----------------------------------------------------
# How the shell half reaches the core. Secrets arrive on stdin, one per line,
# never in argv. A master password cannot contain a newline: every prompt that
# collects one reads a single line.

# ----- foreign export formats ------------------------------------------------
# Bitwarden's export is the one people arrive with, and its shape has nothing
# in common with SPM's. Normalising it here rather than in either surface means
# the CLI and the dashboard cannot disagree about what a Bitwarden file means.

# Bitwarden item types. 3 and 4 carry structured data with no SPM equivalent,
# so they become notes rather than being dropped -- an import that silently
# loses a card is worse than one that stores it as text the user can read.
BITWARDEN_LOGIN = 1
BITWARDEN_SECURE_NOTE = 2
BITWARDEN_CARD = 3
BITWARDEN_IDENTITY = 4


def looks_like_bitwarden_json(payload):
    return isinstance(payload, dict) and isinstance(payload.get("items"), list)


def looks_like_bitwarden_csv_header(fieldnames):
    names = {(name or "").strip().lower() for name in (fieldnames or ())}
    return "login_password" in names or "login_username" in names


def _bitwarden_uri(item):
    login = item.get("login") or {}
    for entry in login.get("uris") or []:
        if isinstance(entry, dict) and entry.get("uri"):
            return entry["uri"]
        if isinstance(entry, str) and entry:
            return entry
    return ""


def _bitwarden_structured(item):
    """Card and identity fields rendered as readable lines."""
    for key in ("card", "identity"):
        section = item.get(key)
        if isinstance(section, dict):
            pairs = [(k, v) for k, v in section.items() if v not in (None, "")]
            if pairs:
                return "\n".join("%s: %s" % (k, v) for k, v in sorted(pairs))
    return ""


def _hkdf_expand_sha256(prk, info, length=32):
    """HKDF-Expand, the half Bitwarden uses to split one key into enc and mac."""
    okm, block, counter = b"", b"", 1
    while len(okm) < length:
        block = hmac.new(prk, block + info + bytes([counter]), hashlib.sha256).digest()
        okm += block
        counter += 1
    return okm[:length]


def _split_cipher_string(value):
    """(type, iv, ciphertext, mac) from Bitwarden's "2.iv|ct|mac" encoding."""
    text = (value or "").strip()
    if "." not in text:
        raise VaultError("malformed encrypted field in the export")
    kind, _, rest = text.partition(".")
    parts = rest.split("|")
    if kind != "2" or len(parts) != 3:
        raise VaultError(
            "unsupported encryption type %r in the export; SPM reads "
            "AesCbc256_HmacSha256_B64 exports" % kind)
    try:
        return (kind, base64.b64decode(parts[0]),
                base64.b64decode(parts[1]), base64.b64decode(parts[2]))
    except Exception:
        raise VaultError("the encrypted field is not valid base64")


def decrypt_bitwarden_export(payload, password):
    """The plaintext JSON inside a Bitwarden password-protected export.

    Two deliberate refusals rather than approximations:

    Argon2id (kdfType 1) is not derivable here for the same reason SPM does not
    use it for its own vaults -- no stdlib implementation, and no dependency
    this project is willing to take. Such an export is refused by name.

    AES-256-CBC needs a real implementation. `cryptography` is used when it is
    importable and the import is refused when it is not. The alternatives were
    to shell out to `openssl enc -K`, which puts the key in argv where any
    local user can read it and which this module forbids by design, or to
    hand-write AES, which is not something that belongs in a password
    manager's trusted core for the sake of a one-off conversion.
    """
    if not isinstance(payload, dict) or not payload.get("encrypted"):
        raise VaultError("this file is not an encrypted Bitwarden export")

    kdf_type = payload.get("kdfType", 0)
    if kdf_type not in (0, None):
        raise VaultError(
            "this export was protected with Argon2id, which SPM cannot derive. "
            "Re-export from Bitwarden without a password, or export as CSV.")

    try:
        from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
    except ImportError:
        raise VaultError(
            "reading a password-protected export needs the python3 "
            "'cryptography' package, which is not installed. Re-export from "
            "Bitwarden without a password, or install it and try again.")

    salt = (payload.get("salt") or "").encode("utf-8")
    iterations = int(payload.get("kdfIterations") or 600000)
    if not salt:
        raise VaultError("the export carries no salt")

    master = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt,
                                 iterations, dklen=32)
    enc_key = _hkdf_expand_sha256(master, b"enc", 32)
    mac_key = _hkdf_expand_sha256(master, b"mac", 32)

    _, iv, ciphertext, mac = _split_cipher_string(payload.get("data"))

    # Authenticate before decrypting, and compare in constant time. A wrong
    # password fails here, which is why it is reported as a wrong password
    # rather than as corrupt data.
    expected = hmac.new(mac_key, iv + ciphertext, hashlib.sha256).digest()
    if not hmac.compare_digest(expected, mac):
        raise VaultError("wrong export password, or the file has been altered")

    decryptor = Cipher(algorithms.AES(enc_key), modes.CBC(iv)).decryptor()
    padded = decryptor.update(ciphertext) + decryptor.finalize()
    if not padded:
        raise VaultError("the export decrypted to nothing")
    pad = padded[-1]
    if pad < 1 or pad > 16 or padded[-pad:] != bytes([pad]) * pad:
        raise VaultError("the export did not decrypt cleanly")
    return padded[:-pad].decode("utf-8")


def parse_otpauth(value):
    """(secret, period, algorithm) from a TOTP value Bitwarden might store.

    Bitwarden's `totp` field is either a bare base32 secret or a whole
    otpauth:// URI. SPM's authenticator row holds the secret, the period and
    the algorithm in separate fields, so a URI stored verbatim produces an
    authenticator that cannot generate a code -- it would try to base32-decode
    the URI itself.
    """
    text = (value or "").strip()
    if not text:
        return "", "30", "sha1"
    if not text.lower().startswith("otpauth://"):
        return text, "30", "sha1"
    query = urllib.parse.urlparse(text).query
    params = urllib.parse.parse_qs(query)
    secret = (params.get("secret") or [""])[0].strip()
    period = (params.get("period") or ["30"])[0].strip() or "30"
    algorithm = (params.get("algorithm") or ["sha1"])[0].strip().lower() or "sha1"
    if not period.isdigit():
        period = "30"
    if algorithm not in ("sha1", "sha256", "sha512"):
        algorithm = "sha1"
    return secret, period, algorithm


def bitwarden_rows(payload):
    """Bitwarden's JSON export as rows in SPM's import schema.

    Custom fields, folder names and TOTP secrets are carried across rather than
    dropped. A TOTP becomes an authenticator row; everything else Bitwarden
    kept as structure is appended to the notes, because silently losing it
    during a migration is the kind of failure people notice months later.
    """
    rows = []
    folders = {}
    for folder in payload.get("folders") or []:
        if isinstance(folder, dict) and folder.get("id"):
            folders[folder["id"]] = folder.get("name") or ""

    for item in payload.get("items") or []:
        if not isinstance(item, dict):
            continue
        name = item.get("name") or ""
        created = item.get("creationDate") or ""
        extras = []
        for field in item.get("fields") or []:
            if isinstance(field, dict) and field.get("name"):
                extras.append("%s: %s" % (field["name"], field.get("value") or ""))
        structured = _bitwarden_structured(item)
        if structured:
            extras.append(structured)
        folder = folders.get(item.get("folderId") or "", "")
        if folder:
            extras.append("folder: %s" % folder)
        notes = "\n".join([n for n in [item.get("notes") or ""] + extras if n])

        login = item.get("login") or {}
        if item.get("type") == BITWARDEN_LOGIN or login:
            rows.append({"type": "password", "label": name,
                         "username": login.get("username") or "",
                         "secret": login.get("password") or "",
                         "notes": notes, "created": created,
                         "url": _bitwarden_uri(item)})
            secret, period, algorithm = parse_otpauth(login.get("totp"))
            if secret:
                rows.append({"type": "authenticator", "label": name,
                             "secret": secret, "period": period,
                             "algorithm": algorithm, "notes": "",
                             "created": created})
        else:
            rows.append({"type": "note", "label": name, "secret": notes,
                         "notes": "", "created": created})
    return rows


def bitwarden_csv_rows(records):
    """Bitwarden's CSV export as rows in SPM's import schema."""
    rows = []
    for record in records:
        def field(key):
            return (record.get(key) or "").strip()
        name = field("name")
        extras = [v for v in (field("fields"),) if v]
        if field("folder"):
            extras.append("folder: %s" % field("folder"))
        notes = "\n".join([n for n in [record.get("notes") or ""] + extras if n])

        if field("type").lower() == "login" or field("login_password") or field("login_username"):
            rows.append({"type": "password", "label": name,
                         "username": field("login_username"),
                         "secret": record.get("login_password") or "",
                         "notes": notes, "created": "",
                         "url": field("login_uri")})
            secret, period, algorithm = parse_otpauth(field("login_totp"))
            if secret:
                rows.append({"type": "authenticator", "label": name,
                             "secret": secret, "period": period,
                             "algorithm": algorithm, "notes": "",
                             "created": ""})
        else:
            rows.append({"type": "note", "label": name, "secret": notes,
                         "notes": "", "created": ""})
    return rows


# ----- per-record password history -------------------------------------------

# A rotated credential keeps its predecessors, so a bad rotation is recoverable
# without restoring a whole vault generation. Distinct from the vault-level
# snapshots in history_dir(), which capture everything at a point in time; this
# captures one field's past.
HISTORY_TAG = "PWHIST"

# Per record, not per vault. A credential rotated on a schedule would otherwise
# grow without bound inside the vault it is stored in.
HISTORY_KEEP = 10


def _password_rows(plaintext):
    """{id: fields} for password rows, identified the way every surface does."""
    rows = {}
    for line in plaintext.splitlines():
        if not line or line.startswith("#"):
            continue
        parts = line.split("\t")
        if len(parts) >= 6 and parts[0].isdigit():
            rows[parts[0]] = parts
    return rows


def record_password_history(old_plaintext, new_plaintext, when=None,
                            keep=HISTORY_KEEP):
    """new_plaintext with a history row for every password that just changed.

    Called at the write boundary rather than at each place that edits a record,
    so a new edit path cannot forget to record history -- the same reasoning
    that makes parse_entries an allowlist.

    Three rules, all of them things a caller would otherwise get wrong:

    - A secret that did not change writes nothing. Saving an unrelated field
      must not manufacture a history entry.
    - An empty previous secret is not history. A record created empty and then
      filled in has no predecessor worth keeping.
    - History for a deleted record is deleted with it. Otherwise removing an
      entry would leave its old passwords in the vault, which is the opposite
      of what deleting it means.
    """
    stamp = when or time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())
    before = _password_rows(old_plaintext)
    after = _password_rows(new_plaintext)

    kept = []
    carried = {}
    for line in new_plaintext.splitlines():
        parts = line.split("\t")
        if parts and parts[0] == HISTORY_TAG and len(parts) >= 4:
            carried.setdefault(parts[1], []).append(parts)
            continue
        kept.append(line)

    for record_id, old_parts in before.items():
        new_parts = after.get(record_id)
        if new_parts is None:
            continue
        old_secret = old_parts[3] if len(old_parts) > 3 else ""
        new_secret = new_parts[3] if len(new_parts) > 3 else ""
        if not old_secret or old_secret == new_secret:
            continue
        carried.setdefault(record_id, []).append([
            HISTORY_TAG, record_id,
            base64.b64encode(old_secret.encode("utf-8")).decode("ascii"),
            stamp, "-", "-",
        ])

    lines = [line for line in kept if line != ""]
    for record_id in sorted(carried, key=lambda v: (len(v), v)):
        if record_id not in after:
            # The record is gone; its history goes with it.
            continue
        entries = carried[record_id][-keep:]
        for parts in entries:
            lines.append("\t".join(parts))
    return "\n".join(lines) + "\n"


def password_history(plaintext, record_id):
    """[(when, secret)] oldest first, for one record."""
    out = []
    for line in plaintext.splitlines():
        parts = line.split("\t")
        if len(parts) >= 4 and parts[0] == HISTORY_TAG and parts[1] == record_id:
            try:
                secret = base64.b64decode(parts[2]).decode("utf-8", errors="replace")
            except Exception:
                continue
            out.append((parts[3], secret))
    return out


# ----- local security and opt-in breach review ------------------------------

PWNED_PASSWORDS_RANGE_URL = "https://api.pwnedpasswords.com/range/"


def _password_security_rows(plaintext):
    """Password rows and malformed authenticators, with no secret in output."""
    rows, malformed = [], []
    for line in plaintext.splitlines():
        if not line or line.startswith("#") or line.startswith("META_"):
            continue
        parts = line.split("\t")
        if len(parts) >= 6 and parts[0].isdigit():
            rows.append(parts)
        elif parts[0] == "AUTH" and (
                len(parts) < 7 or parts[6] not in ("sha1", "sha256", "sha512")
                or not parts[3]):
            malformed.append(parts[1] if len(parts) > 1 else "?")
    return rows, malformed


def _pwned_range(prefix, timeout=5, opener=None):
    """Suffix -> breach count for one HIBP range response.

    Only a five-character SHA-1 prefix reaches the service. Add-Padding asks
    for dummy rows so response size does not reveal how many real suffixes the
    range contains. The caller has already made an explicit opt-in decision.
    """
    if not re.fullmatch(r"[0-9A-F]{5}", prefix):
        raise VaultError("invalid breach-check prefix")
    request = urllib.request.Request(
        PWNED_PASSWORDS_RANGE_URL + prefix,
        headers={"Add-Padding": "true", "User-Agent": "Sans-Password-Manager"})
    open_url = opener or urllib.request.urlopen
    try:
        response = open_url(request, timeout=timeout)
        try:
            payload = response.read().decode("ascii", errors="strict")
        finally:
            close = getattr(response, "close", None)
            if close:
                close()
    except Exception as exc:
        raise VaultError("breach service unavailable") from exc
    found = {}
    for line in payload.splitlines():
        suffix, separator, raw_count = line.partition(":")
        suffix = suffix.strip().upper()
        raw_count = raw_count.strip()
        if (separator and re.fullmatch(r"[0-9A-F]{35}", suffix)
                and raw_count.isdigit()):
            found[suffix] = int(raw_count)
    if not found:
        raise VaultError("invalid breach-service response")
    return found


def breached_password_ids(rows, timeout=5, opener=None):
    """[{id, count}] for passwords present in Pwned Passwords.

    Full hashes remain in memory on this device and are never returned. One
    request is made per unique five-character prefix, not per record.
    """
    by_prefix = {}
    for parts in rows:
        secret = parts[3] if len(parts) > 3 else ""
        if not secret:
            continue
        try:
            digest = hashlib.sha1(secret.encode("utf-8")).hexdigest().upper()
        except Exception as exc:
            raise VaultError("breach hashing unavailable") from exc
        by_prefix.setdefault(digest[:5], []).append((parts[0], digest[5:]))
    breached = []
    prefixes = sorted(by_prefix)
    if not prefixes:
        return breached
    # A slow service must not cost one full timeout per password, but the
    # client also must not turn a large vault into unbounded request fan-out.
    workers = min(4, len(prefixes))
    with concurrent.futures.ThreadPoolExecutor(max_workers=workers) as pool:
        ranges = pool.map(
            lambda prefix: _pwned_range(prefix, timeout=timeout, opener=opener),
            prefixes)
        fetched = dict(zip(prefixes, ranges))
    for prefix in prefixes:
        suffixes = fetched[prefix]
        for record_id, suffix in by_prefix[prefix]:
            count = suffixes.get(suffix, 0)
            if count:
                breached.append({"id": record_id, "count": count})
    return breached


def security_report(plaintext, rotation_days=365, check_breaches=False,
                    timeout=5, opener=None):
    """One secret-free security report shared by CLI and Dashboard."""
    rows, malformed = _password_security_rows(plaintext)
    now = time.time()
    seen = {}
    weak, old, incomplete = [], [], []
    for parts in rows:
        record_id = parts[0]
        secret = parts[3] if len(parts) > 3 else ""
        seen.setdefault(secret, []).append(record_id)
        classes = sum(bool(re.search(pattern, secret)) for pattern in
                      (r"[a-z]", r"[A-Z]", r"\d", r"[^A-Za-z0-9]"))
        if len(secret) < 12 or classes < 3:
            weak.append(record_id)
        if not parts[1] or not parts[2]:
            incomplete.append(record_id)
        try:
            stamp = time.mktime(time.strptime(
                parts[5].replace("Z", ""), "%Y-%m-%dT%H:%M:%S"))
            if (now - stamp) / 86400.0 > rotation_days:
                old.append(record_id)
        except (IndexError, ValueError, OverflowError):
            pass
    reused = [ids for secret, ids in seen.items() if secret and len(ids) > 1]
    reused_flat = [record_id for ids in reused for record_id in ids]
    penalty = min(100, len(weak) * 12 + len(reused_flat) * 10
                  + len(old) * 4 + len(incomplete) * 3 + len(malformed) * 8)
    report = {
        "score": max(0, 100 - penalty), "passwords": len(rows),
        "weak": weak, "reused": reused, "reused_flat": reused_flat,
        "old": old, "incomplete": incomplete, "malformed": malformed,
        "rotation_days": rotation_days, "breach_status": "not_checked",
        "breached": [],
    }
    if check_breaches:
        try:
            report["breached"] = breached_password_ids(
                rows, timeout=timeout, opener=opener)
            report["breach_status"] = "checked"
        except VaultError:
            report["breach_status"] = "unavailable"
    return report


# ----- diagnostics -----------------------------------------------------------

# Characters that splitlines() honours but a TAB-delimited, line-based record
# format does not survive. A value carrying one of these was written as a
# single record and reads back as two, so the tail becomes an orphan fragment
# that no surface displays. See the 2.10.12 sanitiser, which stops new ones.
RECORD_BREAKS = {
    "\v": "U+000B VERTICAL TAB",
    "\f": "U+000C FORM FEED",
    "\x1c": "U+001C FILE SEPARATOR",
    "\x1d": "U+001D GROUP SEPARATOR",
    "\x1e": "U+001E RECORD SEPARATOR",
    "\x85": "U+0085 NEXT LINE",
    "\u2028": "U+2028 LINE SEPARATOR",
    "\u2029": "U+2029 PARAGRAPH SEPARATOR",
}

# Field 3 holds the secret in every record shape SPM writes, so nothing here
# ever reads it. Only type, id and label are reported.
_RECORD_TAGS = {"NOTE": "NOTE", "PASSPHRASE": "PASSPHRASE",
                "BACKUP_CODE": "BACKUP_CODE", "AUTH": "AUTHENTICATOR"}


def _describe_record(line):
    parts = line.split("\t")
    tag = parts[0] if parts else ""
    if tag in _RECORD_TAGS:
        return (_RECORD_TAGS[tag],
                parts[1] if len(parts) > 1 else "?",
                parts[2] if len(parts) > 2 else "")
    if tag.isdigit():
        return "PASSWORD", tag, (parts[1] if len(parts) > 1 else "")
    return tag or "(unknown)", "?", ""


def _safe_text(text, limit=32):
    """A label rendered for a terminal: no raw control characters, ever."""
    out = []
    for ch in text:
        if ch in RECORD_BREAKS or ch == "\t":
            out.append("\u2423")
        elif unicodedata.category(ch).startswith("C"):
            out.append("?")
        else:
            out.append(ch)
    shown = "".join(out)
    return shown[:limit] + ("..." if len(shown) > limit else "")


def scan_broken_records(plaintext):
    """(broken, orphans) for records split by an embedded line break.

    Split on "\n" only, because that is how the record was physically written.
    """
    broken, orphans = [], []
    for number, line in enumerate(plaintext.split("\n"), start=1):
        if not line or line.startswith("#"):
            continue
        hits = [name for ch, name in RECORD_BREAKS.items() if ch in line]
        if hits:
            kind, rid, label = _describe_record(line)
            broken.append((number, kind, rid, _safe_text(label), hits))
            continue
        if line.startswith("META_"):
            continue
        if len(line.split("\t")) < 5:
            orphans.append((number, _safe_text(line, 48)))
    return broken, orphans


def looks_like_vault(plaintext):
    """Whether decrypted bytes are plausibly a vault rather than any old file.

    "The command exited zero" is not the same as "this decrypted". gpg exits 0
    on inputs it never decrypted at all -- an unencrypted OpenPGP literal-data
    packet is parsed and emitted as-is -- and it does so for roughly 1.1% of
    random 512-byte blobs, because byte 0 is read as a packet header and a few
    tags are processed without a key. Every caller of this is about to replace
    a live vault with the file in question, so exit status alone is too weak a
    thing to stake that on.

    Deliberately generous: any META_ row or any record line. A vault SPM wrote
    always carries META_VAULT_VERSION, and this must not start refusing odd but
    genuine vaults -- it exists to reject files that are not vaults at all.
    """
    for line in plaintext.split("\n"):
        tag = line.split("\t", 1)[0]
        if tag.startswith("META_") or tag in _RECORD_TAGS or tag.isdigit():
            return True
    return False


def vault_counts(plaintext):
    """Record counts, duplicate password ids and empty password fields."""
    counts = {"passwords": 0, "notes": 0, "passphrases": 0,
              "backup_codes": 0, "authenticators": 0}
    by_tag = {"NOTE": "notes", "PASSPHRASE": "passphrases",
              "BACKUP_CODE": "backup_codes", "AUTH": "authenticators"}
    seen, duplicates, empty = {}, [], 0
    for line in plaintext.splitlines():
        if not line or line.startswith("#"):
            continue
        parts = line.split("\t")
        tag = parts[0]
        if tag in by_tag:
            counts[by_tag[tag]] += 1
        elif tag.isdigit():
            counts["passwords"] += 1
            seen[tag] = seen.get(tag, 0) + 1
            if len(parts) > 3 and not parts[3]:
                empty += 1
    duplicates = sorted((rid for rid, n in seen.items() if n > 1), key=int)
    return counts, duplicates, empty


def _check(identifier, status, summary, **extra):
    entry = {"id": identifier, "status": status, "summary": summary}
    entry.update(extra)
    return entry


def doctor_report(plaintext, vault_path, recovery_status="unchecked",
                  sensitive_files=()):
    """A machine-readable health report. Never contains a secret.

    Structured as a list of checks with stable ids rather than a bag of
    booleans, so a caller can act on one without parsing prose, and so a check
    added later does not change the shape of the ones already there.
    """
    checks = []
    counts, duplicates, empty = vault_counts(plaintext)

    if duplicates:
        checks.append(_check("duplicate_ids", "fail",
                             "%d password id(s) appear more than once" % len(duplicates),
                             ids=duplicates))
    else:
        checks.append(_check("duplicate_ids", "ok", "no duplicate password ids"))

    if empty:
        checks.append(_check("empty_passwords", "warn",
                             "%d entr(y/ies) have an empty password field" % empty,
                             count=empty))
    else:
        checks.append(_check("empty_passwords", "ok", "no empty password fields"))

    broken, orphans = scan_broken_records(plaintext)
    if broken or orphans:
        checks.append(_check(
            "split_records", "fail",
            "%d record(s) contain a line-break character; %d orphan fragment(s)"
            % (len(broken), len(orphans)),
            broken=[{"line": n, "kind": k, "id": i, "label": l, "characters": h}
                    for n, k, i, l, h in broken],
            orphans=[{"line": n, "text": t} for n, t in orphans]))
    else:
        checks.append(_check("split_records", "ok",
                             "no records split by a line-break character"))

    found = format_version(plaintext)
    if found >= VAULT_FORMAT_VERSION:
        checks.append(_check("vault_format", "ok",
                             "format version %d is current" % found,
                             found=found, current=VAULT_FORMAT_VERSION))
    else:
        checks.append(_check(
            "vault_format", "warn",
            "format version %d; %d is available and the next write upgrades in place"
            % (found, VAULT_FORMAT_VERSION),
            found=found, current=VAULT_FORMAT_VERSION))

    # Which backend actually sealed this file, not which one this build would
    # write. A vault upgrades on its next write, so between installing a
    # release and saving anything the two genuinely differ, and a report that
    # showed the build's answer would be describing itself.
    try:
        backend, kdf = vault_seal_summary(vault_path)
    except (OSError, VaultError) as exc:
        backend, kdf = "unreadable", None
        checks.append(_check("vault_cipher", "fail", str(exc)))
    if backend == "openssl":
        checks.append(_check(
            "vault_cipher", "ok",
            "sealed with AES-256-CTR and HMAC-SHA256; key derivation %s "
            "n=%d r=%d p=%d" % (kdf["name"], kdf["n"], kdf["r"], kdf["p"]),
            backend=backend, kdf=kdf["name"],
            kdf_n=kdf["n"], kdf_r=kdf["r"], kdf_p=kdf["p"]))
    elif backend == "gpg":
        checks.append(_check(
            "vault_cipher", "warn",
            "sealed with gpg; the next write upgrades it to AES-256-CTR with "
            "a memory-hard key derivation, in place and without a new key",
            backend=backend))
    elif backend is None:
        checks.append(_check(
            "vault_cipher", "warn",
            "predates the key container; the next write upgrades it in place",
            backend="legacy"))

    try:
        recovery_pubkey_pem(plaintext)
        checks.append(_check("recovery_pubkey", "ok",
                             "recovery public key present and decodable"))
    except VaultError as exc:
        checks.append(_check("recovery_pubkey", "fail", str(exc)))

    pairing = {
        "match-current": ("ok", "recovery file holds this vault's current key"),
        "match-legacy": ("ok", "recovery file decrypts; this format predates vault keys"),
        "match-stale": ("fail", "recovery file does not hold this vault's key; "
                                "run change-master to refresh it"),
        "mismatch": ("fail", "private key does not match the recovery file"),
        "no-private-key": ("fail", "no default private key found"),
        "no-recovery-file": ("fail", "no recovery file found"),
        "unchecked": ("warn", "recovery pairing was not checked"),
    }
    status, summary = pairing.get(recovery_status,
                                  ("warn", "unrecognised recovery state"))
    checks.append(_check("recovery_pairing", status, summary, state=recovery_status))

    # Split recovery is optional, so its absence is not a defect on its own.
    # The combination is: a vault whose recovery file or private key is gone
    # AND which records no share set has no way back at all, and neither check
    # can see that alone.
    shares = shares_meta(plaintext)
    if shares:
        set_id, threshold, count, minted = shares
        checks.append(_check(
            "split_recovery", "ok",
            "%d of %d shares recorded, set %s" % (
                threshold, count, set_id.hex().upper()),
            state="set", threshold=threshold, shares=count,
            set_id=set_id.hex().upper(), minted=minted))
    elif status == "fail":
        checks.append(_check(
            "split_recovery", "fail",
            "no share set and no usable recovery file: this vault has no "
            "recovery path left",
            state="none"))
    else:
        checks.append(_check(
            "split_recovery", "ok",
            "no share set recorded; recovery rests on the recovery file",
            state="none"))

    exposed = []
    for path in sensitive_files:
        try:
            mode = stat.S_IMODE(os.stat(path).st_mode)
        except OSError:
            continue
        if mode & (stat.S_IRWXG | stat.S_IRWXO):
            exposed.append({"path": path, "mode": "%03o" % mode})
    if exposed:
        checks.append(_check("file_permissions", "fail",
                             "%d sensitive file(s) readable by other users" % len(exposed),
                             files=exposed))
    else:
        checks.append(_check("file_permissions", "ok",
                             "sensitive files are not group- or world-accessible"))

    failed = sum(1 for c in checks if c["status"] == "fail")
    warned = sum(1 for c in checks if c["status"] == "warn")
    return {
        "schema": 1,
        "vault": {"path": vault_path,
                  "format_version": found,
                  "current_format_version": VAULT_FORMAT_VERSION},
        "counts": counts,
        "checks": checks,
        "summary": {"failed": failed, "warned": warned,
                    "status": "fail" if failed else ("warn" if warned else "ok")},
    }


def _secrets(count):
    data = sys.stdin.buffer.read().decode("utf-8")
    fields = data.split("\n")
    if len(fields) < count:
        raise VaultError("expected %d secret(s) on stdin" % count)
    return fields[:count]


def main(argv):
    if len(argv) < 2:
        sys.stderr.write("usage: spm_core.py <command> [args]\n")
        return 2
    command = argv[1]
    try:
        if command == "read":
            # read <vault> <out> [--require-vault]
            # stdin: master ; stdout: vault key (may be empty)
            #
            # --require-vault is for the callers that are about to overwrite a
            # live vault with this file. They need "this decrypted" and not
            # merely "the command exited zero"; see looks_like_vault.
            vault, out = argv[2], argv[3]
            (master,) = _secrets(1)
            plaintext, key = read_vault(vault, master)
            if "--require-vault" in argv[4:] and not looks_like_vault(plaintext):
                raise VaultError(
                    "%s decrypted to something that is not a vault" % vault)
            write_plaintext(out, plaintext)
            sys.stdout.write(key or "")
        elif command == "write":
            # write <vault> <plainfile> ; stdin: master[\nvault key]
            vault, source = argv[2], argv[3]
            fields = sys.stdin.buffer.read().decode("utf-8").split("\n")
            master = fields[0]
            key = fields[1] if len(fields) > 1 and fields[1] else None
            with open(source, "r", encoding="utf-8") as handle:
                plaintext = handle.read()
            sys.stdout.write(write_vault(vault, master, plaintext, key))
        elif command == "rewrap":
            # rewrap <vault> ; stdin: old master\nnew master
            old, new = _secrets(2)
            rewrap(argv[2], old, new)
        elif command == "rewrap-key":
            # rewrap-key <vault> ; stdin: vault key\nnew master
            key, new = _secrets(2)
            if not key:
                raise VaultError("a vault key is required")
            rewrap_with_key(argv[2], key, new)
        elif command == "shares-split":
            # shares-split <vault> <threshold> <count> ; stdin: master
            # stdout: set id, then one share per line
            vault = argv[2]
            threshold, count = int(argv[3]), int(argv[4])
            (master,) = _secrets(1)
            plaintext, key = read_vault(vault, master)
            if not key:
                raise VaultError(
                    "this vault predates the key container and has no vault "
                    "key to split; open and save it once to migrate it")
            set_id = os.urandom(SHARE_SET_BYTES)
            minted = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())
            parts = split_secret(key.encode("utf-8"), threshold, count)
            # The vault records that a set exists before the shares are shown.
            # A crash between the two leaves a recorded set nobody holds, which
            # `shares status` reports and a re-split replaces; the reverse
            # order would leave live shares the vault never mentions.
            write_vault(vault, master,
                        stamp_shares_meta(plaintext, set_id, threshold, count,
                                          minted),
                        key)
            sys.stdout.write("%s\n" % set_id.hex().upper())
            for index, payload in parts:
                sys.stdout.write("%s\n" % encode_share(
                    threshold, index, set_id, payload))
        elif command == "shares-combine":
            # shares-combine <vault> ; stdin: one share per line
            # stdout: the vault key, once it has been shown to open the vault
            vault = argv[2]
            lines = [line.strip() for line
                     in sys.stdin.buffer.read().decode("utf-8").splitlines()]
            decoded = [decode_share(line) for line in lines if line]
            if not decoded:
                raise VaultError("no shares were given")
            thresholds = {threshold for threshold, _, _, _ in decoded}
            sets = {set_id for _, _, set_id, _ in decoded}
            if len(sets) != 1:
                raise VaultError(
                    "these shares come from %d different sets; every share "
                    "must carry the same set identifier" % len(sets))
            if len(thresholds) != 1:
                raise VaultError("these shares disagree about the threshold")
            threshold = thresholds.pop()
            set_id = sets.pop()
            seen = {index for _, index, _, _ in decoded}
            if len(seen) != len(decoded):
                raise VaultError("the same share was given more than once")
            if len(decoded) < threshold:
                raise VaultError(
                    "%d share(s) given; this set needs %d"
                    % (len(decoded), threshold))
            secret = combine_shares(
                [(index, payload) for _, index, _, payload in decoded])
            # Reconstruction always produces *something*. Proving it is the
            # right something means opening the vault with it -- the share
            # format deliberately carries no digest of the secret to check
            # against, because that digest would be the one thing an attacker
            # holding threshold-1 shares could attack offline.
            try:
                key = secret.decode("utf-8")
            except UnicodeDecodeError:
                raise VaultError(
                    "these shares did not reconstruct a usable key; one of "
                    "them is probably from a different set")
            with open(vault, "rb") as handle:
                raw = handle.read()
            modern = parse_container_aead(raw)
            container = modern[1:] if modern else parse_container(raw)
            if container is None:
                raise VaultError("this vault predates the key container")
            try:
                if modern:
                    unseal(key, container[1])
                else:
                    gpg_decrypt(key, container[1])
            except (subprocess.CalledProcessError, VaultError):
                raise VaultError(
                    "these shares reconstructed a key that does not open this "
                    "vault; check that every share belongs to set %s"
                    % set_id.hex().upper())
            sys.stdout.write(key)
        elif command == "shares-status":
            # shares-status <vault> ; stdin: master ; stdout: tsv or nothing
            (master,) = _secrets(1)
            plaintext, _ = read_vault(argv[2], master)
            meta = shares_meta(plaintext)
            if meta:
                set_id, threshold, count, minted = meta
                sys.stdout.write("%s\t%d\t%d\t%s\n"
                                 % (set_id.hex().upper(), threshold, count,
                                    minted))
        elif command == "recover":
            # recover <vault> <out> ; stdin: recovered secret
            # stdout: "<vault key>\n<1 if the recovery file is stale else 0>"
            (secret,) = _secrets(1)
            key, stale = recover(argv[2], secret, argv[3])
            sys.stdout.write("%s\n%d\n" % (key or "", 1 if stale else 0))
        elif command == "unwrap":
            # unwrap <vault> ; stdin: master ; stdout: vault key
            (master,) = _secrets(1)
            sys.stdout.write(unwrap_key(argv[2], master) or "")
        elif command == "is-container":
            # Enough bytes for the longest magic, not for one of them. Sized to
            # CONTAINER_MAGIC alone, this read truncated an AEAD header mid-word
            # and reported every current vault as not a container.
            with open(argv[2], "rb") as handle:
                head = handle.read(
                    max(len(CONTAINER_MAGIC), len(CONTAINER_MAGIC_AEAD)) + 1)
            return 0 if is_container(head) else 1
        elif command == "seal-info":
            # seal-info <vault> ; stdout: backend<TAB>kdf<TAB>n<TAB>r<TAB>p
            # No secret is read: this describes the header, not the contents,
            # so `doctor` can report it without holding the vault open.
            backend, kdf = vault_seal_summary(argv[2])
            if kdf:
                sys.stdout.write("%s\t%s\t%d\t%d\t%d\n" % (
                    backend, kdf["name"], kdf["n"], kdf["r"], kdf["p"]))
            else:
                sys.stdout.write("%s\t-\t-\t-\t-\n" % (backend or "legacy"))
        elif command == "format-version":
            with open(argv[2], "r", encoding="utf-8", errors="ignore") as handle:
                sys.stdout.write("%d\n" % format_version(handle.read()))
        elif command == "stamp-version":
            with open(argv[2], "r", encoding="utf-8") as handle:
                stamped = stamp_version(handle.read())
            with open(argv[3], "w", encoding="utf-8") as handle:
                handle.write(stamped)
        elif command == "write-recovery":
            # write-recovery <vault> <plainfile> ; stdin: vault key
            (key,) = _secrets(1)
            with open(argv[3], "r", encoding="utf-8") as handle:
                plaintext = handle.read()
            install_recovery(argv[2], stage_recovery(argv[2], plaintext, key))
        elif command == "attrs-encode":
            # attrs-encode <folder> ; stdin: name\tvalue per line
            # stdout: the attributes column
            rows = []
            for line in sys.stdin.read().splitlines():
                if not line.strip():
                    continue
                name, _, value = line.partition("\t")
                rows.append((name, value))
            sys.stdout.write(encode_attrs(argv[2] if len(argv) > 2 else "", rows,
                                          "--hidden" in argv[3:]))
        elif command == "attrs-decode":
            # attrs-decode <column> ; stdout: one JSON document
            folder, fields, hidden = decode_attrs(argv[2] if len(argv) > 2 else "")
            sys.stdout.write(json.dumps(
                {"folder": folder, "hidden": hidden,
                 "fields": [{"name": n, "value": v} for n, v in fields]}) + "\n")
        elif command == "folders":
            # folders <plainfile> ; stdout: one folder per line
            with open(argv[2], "r", encoding="utf-8", errors="ignore") as handle:
                for name in record_folders(handle.read()):
                    sys.stdout.write(name + "\n")
        elif command == "security-report":
            # security-report <plainfile> [rotation-days] [--breaches]
            # stdout is secret-free JSON; breach checking is explicit opt-in.
            days = int(argv[3]) if len(argv) > 3 and argv[3] else 365
            check_breaches = "--breaches" in argv[4:]
            with open(argv[2], "r", encoding="utf-8", errors="replace") as handle:
                report = security_report(handle.read(), days, check_breaches)
            sys.stdout.write(json.dumps(report, indent=2) + "\n")
        elif command == "events":
            # events <vault> [limit] ; stdout: one JSON document
            limit = int(argv[3]) if len(argv) > 3 and argv[3] else 0
            sys.stdout.write(json.dumps(
                {"events": read_events(argv[2], limit)}, indent=2) + "\n")
        elif command == "events-path":
            sys.stdout.write(events_path(argv[2]) + "\n")
        elif command == "scope-id":
            sys.stdout.write(vault_scope_id(argv[2]))
        elif command == "current-version":
            sys.stdout.write("%d\n" % VAULT_FORMAT_VERSION)
        elif command == "history-dir":
            sys.stdout.write(history_dir(argv[2]) + "\n")
        elif command == "archive":
            archive_generation(argv[2])
        elif command == "install-file":
            # stdout: "replaced" or "created", so the caller can say which.
            # install-file <source> <dest> [--no-archive] [--sha256 <hex>]
            options = argv[4:]
            expect = ""
            if "--sha256" in options:
                expect = options[options.index("--sha256") + 1]
            replaced = install_vault_file(
                argv[2], argv[3], archive="--no-archive" not in options,
                expect_sha256=expect)
            sys.stdout.write("replaced\n" if replaced else "created\n")
        elif command == "record-history":
            # record-history <previous plainfile> <new plainfile> <out>
            # Writes <new> plus a history row for every password that changed.
            with open(argv[2], "r", encoding="utf-8", errors="surrogateescape") as handle:
                previous = handle.read()
            with open(argv[3], "r", encoding="utf-8", errors="surrogateescape") as handle:
                current = handle.read()
            write_plaintext(argv[4], record_password_history(previous, current))
        elif command == "password-history":
            # password-history <plainfile> <record id> ; stdout: TSV of when/secret
            with open(argv[2], "r", encoding="utf-8", errors="surrogateescape") as handle:
                plaintext = handle.read()
            for when, secret in password_history(plaintext, argv[3]):
                sys.stdout.write("%s\t%s\n" % (when, secret))
        elif command == "scan-records":
            # scan-records <plainfile> ; stdout: the TSV the CLI's doctor renders
            with open(argv[2], "r", encoding="utf-8", errors="surrogateescape") as handle:
                broken, orphans = scan_broken_records(handle.read())
            for number, kind, rid, label, hits in broken:
                sys.stdout.write("BROKEN\t%d\t%s\t%s\t%s\t%s\n"
                                 % (number, kind, rid, label, "; ".join(hits)))
            for number, text in orphans:
                sys.stdout.write("ORPHAN\t%d\t%s\n" % (number, text))
            sys.stdout.write("SUMMARY\t%d\t%d\n" % (len(broken), len(orphans)))
        elif command == "doctor-report":
            # doctor-report <plainfile> <vault> <recovery state> [sensitive file ...]
            # stdout: JSON. Exit 1 when any check failed, so a script can gate
            # on the status without parsing the document.
            with open(argv[2], "r", encoding="utf-8", errors="surrogateescape") as handle:
                plaintext = handle.read()
            report = doctor_report(plaintext, argv[3], argv[4], argv[5:])
            sys.stdout.write(json.dumps(report, indent=2) + "\n")
            return 1 if report["summary"]["failed"] else 0
        elif command == "bridge-list":
            # bridge-list <plainfile> <page host> <page scheme>
            # stdout: JSON. Secret-free by construction -- a match is a
            # summary, and the secret column is never read here.
            host = (argv[3] or "").lower().strip(".")
            scheme = argv[4] if len(argv) > 4 else ""
            if not host or any(ch.isspace() for ch in host):
                sys.stdout.write(json.dumps(
                    {"ok": False, "error": "invalid browser hostname"}) + "\n")
                return 2
            with open(argv[2], "r", encoding="utf-8", errors="replace") as handle:
                matches = []
                for line in handle:
                    parts = line.rstrip("\n").split("\t")
                    if not parts or not parts[0].isdigit() or len(parts) < 6:
                        continue
                    url = parts[6] if len(parts) > 6 else ""
                    ok, _reason = bridge_match(host, scheme, parts[1], parts[4], url)
                    if ok:
                        matches.append({"id": parts[0], "label": parts[1],
                                        "username": parts[2], "url": url})
            sys.stdout.write(json.dumps({"ok": True, "matches": matches}) + "\n")
        elif command == "bridge-get":
            # bridge-get <plainfile> <record id> <page host> <page scheme>
            rid, host = argv[3], (argv[4] or "").lower().strip(".")
            scheme = argv[5] if len(argv) > 5 else ""
            with open(argv[2], "r", encoding="utf-8", errors="replace") as handle:
                for line in handle:
                    parts = line.rstrip("\n").split("\t")
                    if parts and parts[0] == rid and len(parts) >= 6:
                        url = parts[6] if len(parts) > 6 else ""
                        ok, reason = bridge_match(host, scheme, parts[1], parts[4], url)
                        if not ok:
                            sys.stdout.write(json.dumps(
                                {"ok": False, "error": reason}) + "\n")
                            return 2
                        sys.stdout.write(json.dumps(
                            {"ok": True, "username": parts[2],
                             "password": parts[3]}, ensure_ascii=False) + "\n")
                        break
                else:
                    sys.stdout.write(json.dumps(
                        {"ok": False, "error": "record not found"}) + "\n")
                    return 1
        elif command == "self-test":
            return 0
        else:
            sys.stderr.write("unknown command: %s\n" % command)
            return 2
    except VaultError as exc:
        sys.stderr.write("%s\n" % exc)
        return 1
    except subprocess.CalledProcessError:
        sys.stderr.write("the cipher refused the supplied secret\n")
        return 1
    except (OSError, IndexError) as exc:
        sys.stderr.write("%s\n" % exc)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
SPMCORE
	chmod 600 "$staged" 2>/dev/null || true
	mv -f "$staged" "$SPM_CORE_PATH" || { rm -f "$staged"; die "Cannot install the SPM core."; }
}

# The path to the installed core, for the two Python helpers that import it as
# a module rather than running it as a command. SPM_CORE_PATH alone is not
# enough: `core` is usually called inside a command substitution, and the
# assignment ensure_core_script makes there dies with the subshell -- so a
# caller reading the variable afterwards finds it empty and hands an empty path
# to importlib, which returns a spec of None.
core_script_path() {
	[ -n "${SPM_CORE_PATH:-}" ] && [ -f "$SPM_CORE_PATH" ] || ensure_core_script
	printf '%s' "$SPM_CORE_PATH"
}

core() {
	[ -n "${SPM_CORE_PATH:-}" ] && [ -f "$SPM_CORE_PATH" ] || ensure_core_script
	# The core writes security events against SPM_VAULT_PATH. The dashboard
	# already sets it; the CLI never did, so every CLI unlock and write went
	# unrecorded and the log described only half the product. Exported here,
	# at the one place the core is invoked, rather than at the callers -- the
	# same reason history is recorded at the write boundary.
	if [ -n "${VAULT_FILE:-}" ]; then
		SPM_VAULT_PATH="$VAULT_FILE" python3 "$SPM_CORE_PATH" "$@"
	else
		python3 "$SPM_CORE_PATH" "$@"
	fi
}

is_vault_container() {
	core is-container "$1" 2>/dev/null
}

decrypt_vault_to_file() {
	local out_file="$1"
	[ -f "$VAULT_FILE" ] || die "Vault does not exist. Run '$0 init' first."

	ensure_master_password_loaded

	if ! VAULT_KEY="$(printf '%s' "$MASTER_PW" | core read "$VAULT_FILE" "$out_file" 2>/dev/null)"; then
		secure_wipe "$out_file"
		MASTER_PW=""
		VAULT_KEY=""
		if [ "$SPM_LANG" = "id" ]; then
			die "Gagal mendekripsi vault. Kata sandi utama salah?"
		else
			die "Failed to decrypt vault. Wrong master password?"
		fi
	fi

	# A copy of what was just decrypted, before any caller edits it. This is
	# what the write boundary compares against to find changed passwords.
	SPM_VAULT_PRISTINE="$(make_tmp)"
	cat "$out_file" > "$SPM_VAULT_PRISTINE" 2>/dev/null || SPM_VAULT_PRISTINE=""
}

# Decrypt any SPM vault file -- a .bak, a history snapshot, a synced copy --
# under "$3". Returns non-zero instead of dying, because its callers are
# proving that a file opens and own their own error message.
#
# The vault key is deliberately NOT captured here: a key unwrapped from a
# snapshot must never become the key the live vault is written under.
decrypt_vault_container() {
	# Every caller is proving a file opens before it replaces the live vault,
	# so this asks the core for the stronger answer: not "gpg exited zero" but
	# "what came out is a vault". gpg exits zero on inputs it never decrypted.
	printf '%s' "$3" | core read "$1" "$2" --require-vault >/dev/null 2>&1
}

# The plaintext as it was when this process decrypted it, so a write can tell
# which passwords changed. Set by decrypt_vault_to_file and consumed here.
SPM_VAULT_PRISTINE=""

encrypt_file_to_vault() {
	local in_file="$1"
	[ "${MASTER_PW:-}" ] || die "MASTER_PW is empty in encrypt_file_to_vault"

	# Per-record password history is recorded at the write boundary rather
	# than at each of the twenty-one places that edit a record, so a new edit
	# path cannot forget to record it. A write with no pristine copy -- an
	# import that never read the old vault, a first init -- simply records
	# nothing, which is correct rather than merely convenient.
	if [ -n "${SPM_VAULT_PRISTINE:-}" ] && [ -f "$SPM_VAULT_PRISTINE" ]; then
		local with_history
		with_history="$(make_tmp)"
		if core record-history "$SPM_VAULT_PRISTINE" "$in_file" "$with_history"; then
			in_file="$with_history"
		else
			printf 'Warning: password history was not recorded for this change.\n' >&2
		fi
	fi

	# The key is passed back in so an ordinary write does not pay to unwrap
	# the envelope it already holds. Passing none makes the core recover it
	# from the vault; only a vault with no key at all gets a new one.
	if ! VAULT_KEY="$(printf '%s\n%s' "$MASTER_PW" "${VAULT_KEY:-}" \
		| core write "$VAULT_FILE" "$in_file")"; then
		die "Failed to write the vault. The existing vault was not changed; plaintext remains in '$in_file'."
	fi

	if ! ( maybe_auto_backup ); then
		printf 'Warning: vault write succeeded, but the automatic backup failed.\n' >&2
	fi
}

rewrap_vault_key() {
	local new_master="$1"
	[ -n "${VAULT_KEY:-}" ] || die "Vault key is not loaded."
	printf '%s\n%s' "$VAULT_KEY" "$new_master" | core rewrap-key "$VAULT_FILE" \
		|| die "Failed to rewrap the vault key. The vault was not changed."
}

stamp_vault_version() {
	core stamp-version "$1" "$2" || die "Failed to stamp the vault format version."
}

vault_format_version() {
	core format-version "$1" 2>/dev/null || printf '1\n'
}


# The advisory lock the CLI shares with the SPM Dashboard.
#
# This used to require flock(1), which is util-linux and which macOS does not
# ship. The dashboard never needed it -- Python's fcntl.flock exists on every
# platform SPM supports -- so on macOS the dashboard was locking and the CLI
# was not. That is the worst of the two arrangements, because one side
# believed it was protected while the other walked straight through.
#
# python3 is already a hard dependency, and locking through it uses the same
# primitive on the same file, so the two genuinely exclude each other. The
# lock is taken on fd 9, which this shell holds open for the duration: the
# helper exiting does not release it, because the lock belongs to the open
# file description and the shell still has a descriptor for it.
#
# There is no stale lock to detect and no PID file to get wrong. The kernel
# drops the lock when the last descriptor for it closes, which includes the
# process being killed. That is the property a mkdir-based lock would have had
# to reimplement badly.
vault_lock_hold_fd9() {
	if command -v flock >/dev/null 2>&1; then
		flock -x 9
		return $?
	fi
	python3 -c 'import fcntl; fcntl.flock(9, fcntl.LOCK_EX)' 2>/dev/null
}

# Restore is the one command whose target is not VAULT_FILE, so it needs a
# second lock on a second descriptor. Held until the process exits, which is
# the whole of the restore.
acquire_restore_lock() {
	local target="$1"
	if ! command -v flock >/dev/null 2>&1 && ! command -v python3 >/dev/null 2>&1; then
		return 0
	fi
	exec 8>"${target}.lock" || die "Cannot open the destination vault lock file."
	chmod 600 "${target}.lock" 2>/dev/null || true
	if command -v flock >/dev/null 2>&1; then
		flock -x 8 || die "Cannot lock the destination vault."
	else
		python3 -c 'import fcntl; fcntl.flock(8, fcntl.LOCK_EX)' 2>/dev/null \
			|| die "Cannot lock the destination vault."
	fi
}

acquire_cli_vault_lock() {
	if ! command -v flock >/dev/null 2>&1 && ! command -v python3 >/dev/null 2>&1; then
		printf "Warning: neither 'flock' nor python3 is available; do not run concurrent CLI or web vault operations.\n" >&2
		return 0
	fi
	exec 9>"${VAULT_FILE}.lock" || die "Cannot open vault lock file."
	chmod 600 "${VAULT_FILE}.lock" 2>/dev/null || true
	vault_lock_hold_fd9 || die "Cannot lock vault."
	CLI_VAULT_LOCKED=1
}

# Memoised: the scope id is a pure function of the vault path, and
# maybe_auto_backup asks for it several times per write.
SPM_VAULT_SCOPE_ID=""
vault_scope_id() {
	if [ -z "$SPM_VAULT_SCOPE_ID" ]; then
		SPM_VAULT_SCOPE_ID="$(core scope-id "$VAULT_FILE")" \
			|| die "Cannot determine the vault scope id."
	fi
	printf '%s' "$SPM_VAULT_SCOPE_ID"
}

history_dir() {
	core history-dir "$VAULT_FILE"
}

archive_current_vault() {
	core archive "$VAULT_FILE" || true
}

auto_backup_config() {
	printf '%s/auto-backup-%s.conf\n' "$SPM_CONFIG_DIR" "$(vault_scope_id)"
}

maybe_auto_backup() {
	[ -f "$VAULT_FILE" ] || return 0
	local cfg enabled target interval retention last now name digest
	cfg="$(auto_backup_config)"
	[ -f "$cfg" ] || return 0
	enabled="$(sed -n '1p' "$cfg")"; [ "$enabled" = "enabled" ] || return 0
	target="$(sed -n '2p' "$cfg")"; interval="$(sed -n '3p' "$cfg")"
	retention="$(sed -n '4p' "$cfg")"; last="$(sed -n '5p' "$cfg")"
	printf '%s' "$interval" | grep -Eq '^[1-9][0-9]*$' || interval=24
	printf '%s' "$retention" | grep -Eq '^[1-9][0-9]*$' || retention=14
	printf '%s' "$last" | grep -Eq '^[0-9]+$' || last=0
	now="$(date +%s)"
	[ $((now - last)) -ge $((interval * 3600)) ] || return 0
	mkdir -p "$target" || die "Failed to create automatic-backup directory."
	chmod 700 "$target" 2>/dev/null || true
	name="spm-$(vault_scope_id)-$(date -u +%Y%m%dT%H%M%SZ).gpg"
	cp "$VAULT_FILE" "$target/$name" || die "Automatic encrypted backup failed."
	chmod 600 "$target/$name" 2>/dev/null || true
	digest="$(sha256sum "$VAULT_FILE" | awk '{print $1}')"
	[ "$digest" = "$(sha256sum "$target/$name" | awk '{print $1}')" ] || die "Automatic backup verification failed."
	find "$target" -maxdepth 1 -type f -name "spm-$(vault_scope_id)-*.gpg" -print 2>/dev/null \
		| while IFS= read -r item; do printf '%s\t%s\n' "$(stat -c '%Y' "$item" 2>/dev/null || stat -f '%m' "$item")" "$item"; done \
		| sort -nr | awk -F '\t' -v keep="$retention" 'NR > keep { print $2 }' \
		| while IFS= read -r old; do secure_wipe "$old"; done
	{
		printf 'enabled\n%s\n%s\n%s\n%s\n' "$target" "$interval" "$retention" "$now"
	} > "$cfg"
	chmod 600 "$cfg" 2>/dev/null || true
}

release_cli_vault_lock() {
	[ "${CLI_VAULT_LOCKED:-0}" = "1" ] || return 0
	# Closing the descriptor releases the lock on every platform, which is the
	# only mechanism available where flock(1) is not. `flock -u` is kept for
	# the platforms that have it, but it is no longer what does the work.
	flock -u 9 2>/dev/null || true
	exec 9>&-
	CLI_VAULT_LOCKED=0
}

# ----- Vault format helpers ---------------------------------------------------
# Password entry line:
# id<TAB>service<TAB>username<TAB>password<TAB>notes<TAB>created_at
#
# Secure note line:
# NOTE<TAB>note_id<TAB>title<TAB>base64_body<TAB>created_at<TAB>-
#
# Meta line (recovery public key):
# META_RECOVERY_PUBKEY<TAB><base64_pubkey><TAB>-<TAB>-<TAB>-<TAB>-

next_id_from_vault() {
	local file="$1"
	if [ ! -s "$file" ]; then
		printf '1\n'
		return
	fi

	awk -F '\t' '
		$1 ~ /^[0-9]+$/ {
			if ($1 > max) max = $1
		}
		END {
			if (max == 0) print 1;
			else print max + 1;
		}
	' "$file"
}

next_note_id_from_vault() {
	local file="$1"
	if [ ! -s "$file" ]; then
		printf '1\n'
		return
	fi
	awk -F '\t' '
		$1=="NOTE" && $2 ~ /^[0-9]+$/ {
			if ($2 > max) max = $2
		}
		END {
			if (max == 0) print 1;
			else print max + 1;
		}
	' "$file"
}

next_backup_code_id_from_vault() {
	local file="$1"
	if [ ! -s "$file" ]; then
		printf '1\n'
		return
	fi
	awk -F '\t' '
		$1=="BACKUP_CODE" && $2 ~ /^[0-9]+$/ {
			if ($2 > max) max = $2
		}
		END {
			if (max == 0) print 1;
			else print max + 1;
		}
	' "$file"
}

next_passphrase_id_from_vault() {
	local file="$1"
	if [ ! -s "$file" ]; then
		printf '1\n'
		return
	fi
	awk -F '\t' '
		$1=="PASSPHRASE" && $2 ~ /^[0-9]+$/ {
			if ($2 > max) max = $2
		}
		END {
			if (max == 0) print 1;
			else print max + 1;
		}
	' "$file"
}

next_authenticator_id_from_vault() {
	local file="$1"
	if [ ! -s "$file" ]; then
		printf '1\n'
		return
	fi
	awk -F '\t' '
		$1=="AUTH" && $2 ~ /^[0-9]+$/ {
			if ($2 > max) max = $2
		}
		END {
			if (max == 0) print 1;
			else print max + 1;
		}
	' "$file"
}

print_vault_table() {
	local file="$1"
	if [ ! -s "$file" ]; then
		if [ "$SPM_LANG" = "id" ]; then
			printf "Vault kosong.\n"
		else
			printf "Vault is empty.\n"
		fi
		return
	fi

	if [ "$SPM_LANG" = "id" ]; then
		printf '%-5s  %-20s  %-24s  %-20s  %s\n' "ID" "Layanan" "Username / Email" "Dibuat" "URL"
	else
		printf '%-5s  %-20s  %-24s  %-20s  %s\n' "ID" "Service" "Username / Email" "Created" "URL"
	fi
	printf '%.0s-' $(seq 1 96); printf '\n'

	awk -F '\t' '
		NF >= 6 && $1 ~ /^[0-9]+$/ {
			printf "%-5s  %-20s  %-24s  %-20s  %s\n", $1, $2, $3, $6, (NF >= 7 ? $7 : "")
		}
	' "$file"
}

search_vault() {
	local file="$1"
	local pattern="$2"

	awk -F '\t' -v p="$pattern" '
		$1 ~ /^[0-9]+$/ && (tolower($2) ~ tolower(p) || tolower($3) ~ tolower(p) \
			|| (NF >= 7 && tolower($7) ~ tolower(p))) {
			printf "%-5s  %-20s  %-24s  %-20s  %s\n", $1, $2, $3, $6, (NF >= 7 ? $7 : "")
		}
	' "$file"
}

get_entry_by_id() {
	local file="$1"
	local id="$2"

	awk -F '\t' -v target="$id" '
		$1 ~ /^[0-9]+$/ && $1 == target {
			print $0;
		}
	' "$file"
}

get_recovery_pub_b64_from_vault() {
	local file="$1"
	awk -F '\t' '$1=="META_RECOVERY_PUBKEY"{print $2; exit}' "$file"
}

write_recovery_file() {
	local vault_plain="$1"
	[ -n "${VAULT_KEY:-}" ] || die "Vault key is not loaded. Cannot update recovery file."
	printf '%s' "$VAULT_KEY" | core write-recovery "$VAULT_FILE" "$vault_plain" \
		|| die "Failed to create/update recovery file '$RECOVERY_FILE'."
}

# ----- Password strength coaching --------------------------------------------

password_strength_report() {
	local pw="$1"
	local len="${#pw}"
	local has_lower=0 has_upper=0 has_digit=0 has_symbol=0
	local i ch

	for (( i=0; i<len; i++ )); do
		ch="${pw:i:1}"
		case "$ch" in
			[a-z]) has_lower=1 ;;
			[A-Z]) has_upper=1 ;;
			[0-9]) has_digit=1 ;;
			*) has_symbol=1 ;;
		esac
	done

	local charset=0
	(( has_lower )) && charset=$((charset+26))
	(( has_upper )) && charset=$((charset+26))
	(( has_digit )) && charset=$((charset+10))
	(( has_symbol )) && charset=$((charset+32))
	[ "$charset" -le 0 ] && charset=1

	local entropy bits_int
	local types_en="" types_id=""

	entropy="$(awk -v L="$len" -v N="$charset" 'BEGIN {
		if (L<=0 || N<=1) {print 0; exit}
		e = L * log(N)/log(2);
		printf "%.1f", e;
	}')"

	bits_int="${entropy%.*}"

	(( has_lower )) && { types_en+="lowercase, "; types_id+="huruf kecil, "; }
	(( has_upper )) && { types_en+="uppercase, "; types_id+="huruf besar, "; }
	(( has_digit )) && { types_en+="digits, "; types_id+="angka, "; }
	(( has_symbol )) && { types_en+="symbols, "; types_id+="simbol, "; }

	if [ -z "$types_en" ]; then
		types_en="(none detected)"
		types_id="(tidak terdeteksi)"
	else
		types_en="${types_en%, }"
		types_id="${types_id%, }"
	fi

	local strength_en strength_id time_en time_id

	if [ "$bits_int" -lt 40 ]; then
		strength_en="VERY WEAK"
		strength_id="SANGAT LEMAH"
		time_en="likely crackable in seconds/minutes (offline attacker)"
		time_id="kemungkinan bisa dibobol dalam hitungan detik/menit (offline)"
	elif [ "$bits_int" -lt 60 ]; then
		strength_en="WEAK"
		strength_id="LEMAH"
		time_en="minutes to hours for strong attacker"
		time_id="menit hingga jam untuk penyerang kuat"
	elif [ "$bits_int" -lt 80 ]; then
		strength_en="MODERATE"
		strength_id="SEDANG"
		time_en="days to months of brute-force"
		time_id="hari hingga bulan brute-force"
	elif [ "$bits_int" -lt 100 ]; then
		strength_en="STRONG"
		strength_id="KUAT"
		time_en="many years of brute-force"
		time_id="bisa butuh bertahun-tahun brute-force"
	else
		strength_en="VERY STRONG"
		strength_id="SANGAT KUAT"
		time_en="decades or more of brute-force"
		time_id="puluhan tahun atau lebih brute-force"
	fi

	if [ "$SPM_LANG" = "id" ]; then
		printf "\n[Analisis Kekuatan Password / Password Strength Analysis]\n"
	else
		printf "\n[Password Strength Analysis / Analisis Kekuatan Password]\n"
	fi

	printf "  Length / Panjang          : %d\n" "$len"
	printf "  Entropy / Entropi         : %s bits\n" "$entropy"
	printf "  Types / Jenis karakter    : %s  |  %s\n" "$types_en" "$types_id"
	printf "  Strength / Kekuatan       : %s  |  %s\n" "$strength_en" "$strength_id"
	printf "  Guess time (rough)        : %s  |  %s\n" "$time_en" "$time_id"

	if [ "$SPM_LANG" = "id" ]; then
		printf "  Saran:\n"
	else
		printf "  Suggestions:\n"
	fi

	if [ "$len" -lt 12 ]; then
		printf "   - EN: Use at least 12–16 characters.\n"
		printf "   - ID: Gunakan minimal 12–16 karakter.\n"
	fi
	if [ "$has_lower" -eq 0 ] || [ "$has_upper" -eq 0 ] || [ "$has_digit" -eq 0 ] || [ "$has_symbol" -eq 0 ]; then
		printf "   - EN: Mix lowercase, UPPERCASE, digits, and symbols.\n"
		printf "   - ID: Campur huruf kecil, BESAR, angka, dan simbol.\n"
	fi
	printf "   - EN: Avoid real words, names, or patterns.\n"
	printf "   - ID: Hindari kata asli, nama, atau pola yang mudah ditebak.\n"
	printf "   - EN: Consider using a passphrase of random words.\n"
	printf "   - ID: Pertimbangkan pakai passphrase dari beberapa kata acak.\n"
}

# ----- Cryptographically secure randomness -----------------------------------
# Password material must never come from $RANDOM (a predictable 15-bit LCG).
# Values are drawn from a CSPRNG byte pool with rejection sampling so the
# result is uniform (a plain "% n" would bias the low indices of the charset).
SPM_RAND_POOL=""
SPM_RAND_BYTE=0
SPM_RAND_BELOW=0

# Refill the hex byte pool. Returns 1 if no CSPRNG source is available.
_spm_rand_refill() {
	SPM_RAND_POOL=""
	if command -v openssl >/dev/null 2>&1; then
		SPM_RAND_POOL="$(openssl rand -hex 128 2>/dev/null | tr -d '\n')" || SPM_RAND_POOL=""
	fi
	if [ -z "$SPM_RAND_POOL" ] && [ -r /dev/urandom ]; then
		SPM_RAND_POOL="$(od -An -tx1 -N128 /dev/urandom 2>/dev/null | tr -d ' \n')" || SPM_RAND_POOL=""
	fi
	[ -n "$SPM_RAND_POOL" ]
}

# Pull one random byte (0-255) into SPM_RAND_BYTE.
_spm_rand_byte() {
	if [ "${#SPM_RAND_POOL}" -lt 2 ]; then
		_spm_rand_refill || return 1
	fi
	local h="${SPM_RAND_POOL:0:2}"
	SPM_RAND_POOL="${SPM_RAND_POOL:2}"
	SPM_RAND_BYTE=$(( 16#$h ))
	return 0
}

# Uniform integer in [0, $1) into SPM_RAND_BELOW. Bound must be 1..256.
# Falls back to $RANDOM only if no CSPRNG source exists at all.
_spm_rand_below() {
	local bound="$1" limit
	[ "$bound" -gt 0 ] 2>/dev/null || bound=1
	if [ "$bound" -gt 256 ]; then
		bound=256
	fi
	limit=$(( 256 - (256 % bound) ))
	while :; do
		if ! _spm_rand_byte; then
			die "No cryptographically secure random source is available (need openssl or /dev/urandom)."
		fi
		if [ "$SPM_RAND_BYTE" -lt "$limit" ]; then
			SPM_RAND_BELOW=$(( SPM_RAND_BYTE % bound ))
			return 0
		fi
	done
}

generate_password() {
	local length="${1:-16}"
	local mode="${2:-secure}"   # secure / easy / numeric
	local include_symbols="${3:-1}"
	local include_upper="${4:-1}"
	local include_lower="${5:-1}"
	local include_digits="${6:-1}"

	# simple wordlist for memorable passwords
	local WORDS=(
		"sun" "moon" "star" "river" "ocean" "cloud" "stone" "tree" "leaf" "fern"
		"fire" "ember" "storm" "wind" "breeze" "shadow" "light" "silver" "gold"
		"amber" "flame" "nova" "comet" "aurora" "pulse" "echo" "vapor" "wave"
		"mist" "dawn" "dusk" "zen" "sage" "whale" "lynx" "orca" "hawk" "raven"
	)

	if ! printf '%s' "$length" | grep -Eq '^[0-9]+$'; then
		length=16
	fi
	if [ "$length" -lt 4 ]; then
		length=4
	elif [ "$length" -gt 128 ]; then
		length=128
	fi
	case "$mode" in
		secure|easy|numeric) ;;
		*) mode="secure" ;;
	esac

	if [ "$mode" = "easy" ]; then
		local words_needed
		words_needed="$length"
		[ "$words_needed" -lt 2 ] && words_needed=2
		[ "$words_needed" -gt 8 ] && words_needed=8
		local parts=() idx word
		for (( i=0; i<words_needed; i++ )); do
			_spm_rand_below "${#WORDS[@]}"; idx="$SPM_RAND_BELOW"
			word="${WORDS[idx]}"
			if [ "$include_upper" = "1" ] && [ "$include_lower" != "1" ]; then
				word="$(printf '%s' "$word" | tr '[:lower:]' '[:upper:]')"
			elif [ "$include_upper" = "1" ]; then
				word="$(printf '%s' "$word" | sed 's/^./\U&/')"
			elif [ "$include_lower" != "1" ]; then
				word="$(printf '%s' "$word" | tr '[:lower:]' '[:upper:]')"
			fi
			parts+=("$word")
		done
		local pw
		pw="$(IFS='-'; echo "${parts[*]}")"
		if [ "$include_digits" = "1" ]; then
			_spm_rand_below 100
			pw="${pw}-$(printf '%02d' "$SPM_RAND_BELOW")"
		fi
		if [ "$include_symbols" = "1" ]; then
			local syms="!@#$%^&*"
			_spm_rand_below "${#syms}"
			local s="${syms:$SPM_RAND_BELOW:1}"
			pw="${pw}${s}"
		fi
		printf '%s\n' "$pw"
		return
	fi

	local charset=""
	if [ "$mode" = "numeric" ]; then
		charset="0123456789"
	else
		[ "$include_upper" = "1" ] && charset="${charset}ABCDEFGHIJKLMNOPQRSTUVWXYZ"
		[ "$include_lower" = "1" ] && charset="${charset}abcdefghijklmnopqrstuvwxyz"
		[ "$include_digits" = "1" ] && charset="${charset}0123456789"
		[ "$include_symbols" = "1" ] && charset="${charset}!@#$%^&*()_-+=[]{}:;,.?/|~"
	fi

	if [ -z "$charset" ]; then
		charset="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"
	fi

	local pw=""
	local i idx ch set_len
	set_len="${#charset}"

	for (( i=0; i<length; i++ )); do
		_spm_rand_below "$set_len"; idx="$SPM_RAND_BELOW"
		ch="${charset:idx:1}"
		pw+="$ch"
	done

	printf '%s\n' "$pw"
}

cmd_generate_password() {
	local length=16
	local mode="secure"
	local symbols=1
	local upper=1
	local lower=1
	local digits=1

	while [ $# -gt 0 ]; do
		case "$1" in
			-l|--length)
				[ $# -ge 2 ] || die "Missing value for $1."
				length="$2"
				shift 2
				;;
			-m|--mode)
				[ $# -ge 2 ] || die "Missing value for $1."
				mode="$2"
				case "$mode" in secure|easy|numeric) ;; *) die "Invalid generator mode '$mode'." ;; esac
				shift 2
				;;
			--no-symbols)
				symbols=0
				shift
				;;
			--no-upper)
				upper=0
				shift
				;;
			--no-lower)
				lower=0
				shift
				;;
			--no-digits)
				digits=0
				shift
				;;
			-h|--help)
				echo "Usage: $0 generate [--length N] [--mode secure|easy|numeric] [--no-symbols] [--no-upper] [--no-lower] [--no-digits]"
				return 0
				;;
			*)
				die "Unknown generator option '$1'."
				;;
		esac
	done

	local pw
	pw="$(generate_password "$length" "$mode" "$symbols" "$upper" "$lower" "$digits")"
	printf "%s\n\n" "$pw"
	password_strength_report "$pw"
}

# ----- Clipboard + auto-clean -------------------------------------------------

clear_clipboard() {
	local method="$1"
	case "$method" in
		termux)
			if command -v termux-clipboard-set >/dev/null 2>&1; then
				termux-clipboard-set "" >/dev/null 2>&1 || true
			fi
			;;
		macos)
			if command -v pbcopy >/dev/null 2>&1; then
				printf '' | pbcopy >/dev/null 2>&1 || true
			fi
			;;
		xclip)
			if command -v xclip >/dev/null 2>&1; then
				xclip -selection clipboard /dev/null >/dev/null 2>&1 || true
			fi
			;;
		wlcopy)
			if command -v wl-copy >/dev/null 2>&1; then
				printf '' | wl-copy >/dev/null 2>&1 || true
			fi
			;;
	esac
}

copy_password_with_autoclear() {
	local password="$1"
	local method=""
	local copied=0

	if [ "$ENV_FLAVOR" = "termux" ] && command -v termux-clipboard-set >/dev/null 2>&1; then
		termux-clipboard-set "$password" >/dev/null 2>&1 && method="termux" && copied=1
	elif command -v pbcopy >/dev/null 2>&1; then
		printf '%s' "$password" | pbcopy >/dev/null 2>&1 && method="macos" && copied=1
	elif command -v xclip >/dev/null 2>&1 && [ -n "${DISPLAY:-}" ]; then
		printf '%s' "$password" | xclip -selection clipboard >/dev/null 2>&1 && method="xclip" && copied=1
	elif command -v wl-copy >/dev/null 2>&1; then
		printf '%s' "$password" | wl-copy >/dev/null 2>&1 && method="wlcopy" && copied=1
	fi

	if [ "$copied" -eq 1 ]; then
		if [ "$SPM_LANG" = "id" ]; then
			printf "\n[+] Password disalin ke clipboard. Clipboard akan dikosongkan otomatis dalam ~15 detik.\n"
		else
			printf "\n[+] Password copied to clipboard. Clipboard will be auto-cleared in ~15 seconds.\n"
		fi
		(
			sleep 15
			clear_clipboard "$method"
		) &
	else
		if [ "$SPM_LANG" = "id" ]; then
			printf "\n[!] Tidak ada helper clipboard tersedia. Password ditampilkan saja.\n"
		else
			printf "\n[!] No clipboard helper available. Password shown only.\n"
		fi
	fi
}

# ----- Recovery key generation (for init) ------------------------------------

generate_recovery_keypair_and_meta() {
	local vault_plain="$1"

	require_cmd openssl

	if [ "$SPM_LANG" = "id" ]; then
		printf "Membuat pasangan kunci RSA untuk pemulihan (4096-bit)...\n"
	else
		printf "Generating RSA key pair for recovery (4096-bit)...\n"
	fi

	if [ -f "$RECOVERY_PRIV_DEFAULT" ]; then
		printf "Warning: recovery private key '%s' already exists, leaving it as-is.\n" "$RECOVERY_PRIV_DEFAULT"
	else
		if ! openssl genrsa -out "$RECOVERY_PRIV_DEFAULT" 4096 >/dev/null 2>&1; then
			die "Failed to generate RSA private key."
		fi
		chmod 600 "$RECOVERY_PRIV_DEFAULT" 2>/dev/null || true
	fi

	local tmp_pub
	tmp_pub="$(make_tmp)"
	if ! openssl rsa -in "$RECOVERY_PRIV_DEFAULT" -pubout -out "$tmp_pub" >/dev/null 2>&1; then
		secure_wipe "$tmp_pub"
		die "Failed to derive RSA public key from private key."
	fi

	local pub_b64
	pub_b64="$(base64 <"$tmp_pub" | tr -d '\n')"

	printf 'META_RECOVERY_PUBKEY\t%s\t-\t-\t-\t-\n' "$pub_b64" >"$vault_plain"

	VAULT_KEY="$(openssl rand -base64 32 | tr -d '\n')" || die "Failed to generate a random vault key."
	if ! printf '%s' "$VAULT_KEY" | openssl rsautl -encrypt -pubin -inkey "$tmp_pub" -out "$RECOVERY_FILE" 2>/dev/null; then
		secure_wipe "$tmp_pub"
		die "Failed to create recovery file '$RECOVERY_FILE'."
	fi

	secure_wipe "$tmp_pub"
	chmod 600 "$RECOVERY_FILE" 2>/dev/null || true

	printf "\n[RECOVERY SETUP]\n"
	printf "  Private key saved at (in this folder): %s\n" "$RECOVERY_PRIV_DEFAULT"
	printf "  Recovery file saved at                : %s\n" "$RECOVERY_FILE"
	if [ "$SPM_LANG" = "id" ]; then
		printf "SIMPAN PRIVATE KEY INI DI TEMPAT AMAN (offline / USB). Jika hilang, fitur 'forgot' tidak bisa dipakai.\n\n"
	else
		printf "STORE THIS PRIVATE KEY SAFELY (offline / USB). If you lose it, 'forgot' recovery will NOT work.\n\n"
	fi
}

# ----- Password commands -----------------------------------------------------

cmd_init() {
	if [ -f "$VAULT_FILE" ]; then
		die "Vault already exists at '$VAULT_FILE'. If you want a new one, move or delete the old file."
	fi

	if [ "$SPM_LANG" = "id" ]; then
		printf "Inisialisasi vault baru di: %s\n" "$VAULT_FILE"
	else
		printf "Initializing new vault at: %s\n" "$VAULT_FILE"
	fi
	prompt_master_password

	local tmp
	tmp="$(make_tmp)"

	generate_recovery_keypair_and_meta "$tmp"
	encrypt_file_to_vault "$tmp"
	secure_wipe "$tmp"

	if [ "$SPM_LANG" = "id" ]; then
		printf "Vault berhasil dibuat.\n"
	else
		printf "Vault created successfully.\n"
	fi
}

cmd_add() {
	[ -f "$VAULT_FILE" ] || die "Vault not found. Run '$0 init' first."

	local tmp
	tmp="$(make_tmp)"
	decrypt_vault_to_file "$tmp"

	if [ "$SPM_LANG" = "id" ]; then
		printf 'Nama layanan: '
	else
		printf 'Service name: '
	fi
	IFS= read -r service
	[ "$service" ] || die "Service cannot be empty."

	if [ "$SPM_LANG" = "id" ]; then
		printf 'Username / Email: '
	else
		printf 'Username / Email: '
	fi
	IFS= read -r username

	if [ "$SPM_LANG" = "id" ]; then
		printf 'Password (kosongkan untuk auto-generate 32 karakter): '
	else
		printf 'Password (leave empty to auto-generate 32 chars): '
	fi
	stty -echo
	IFS= read -r pw
	stty echo
	printf '\n'

	if [ -z "$pw" ]; then
		if command -v openssl >/dev/null 2>&1; then
			pw="$(openssl rand -base64 48 | tr -d '\n' | head -c 32)"
		else
			pw="$(tr -dc 'A-Za-z0-9!@#$%^&*()_+-=' </dev/urandom | head -c 32)"
		fi
		if [ "$SPM_LANG" = "id" ]; then
			printf 'Password dibuat otomatis: %s\n' "$pw"
		else
			printf 'Generated password: %s\n' "$pw"
		fi
	fi

	if [ "$SPM_LANG" = "id" ]; then
		printf 'Catatan (opsional, satu baris): '
	else
		printf 'Notes (optional, single line): '
	fi
	IFS= read -r notes

	local url clean_url
	if [ "$SPM_LANG" = "id" ]; then
		printf 'URL (opsional, https://contoh.com): '
	else
		printf 'URL (optional, https://example.com): '
	fi
	IFS= read -r url
	if ! clean_url="$(sanitize_url "$url")"; then
		secure_wipe "$tmp"
		if [ "$SPM_LANG" = "id" ]; then
			die "URL harus diawali http:// atau https://."
		else
			die "URL must start with http:// or https://."
		fi
	fi

	local id created
	id="$(next_id_from_vault "$tmp")"
	created="$(now_iso)"

	printf '%s\t%s\t%s\t%s\t%s\t%s\t%s\n' "$id" \
		"$(sanitize_field "$service")" \
		"$(sanitize_field "$username")" \
		"$(sanitize_field "$pw")" \
		"$(sanitize_field "$notes")" \
		"$created" \
		"$clean_url" >>"$tmp"

	encrypt_file_to_vault "$tmp"
	secure_wipe "$tmp"

	if [ "$SPM_LANG" = "id" ]; then
		printf "Entry ditambahkan dengan ID %s.\n" "$id"
	else
		printf "Entry added with ID %s.\n" "$id"
	fi

	password_strength_report "$pw"
}

cmd_list() {
	[ -f "$VAULT_FILE" ] || die "Vault not found. Run '$0 init' first."

	local tmp
	tmp="$(make_tmp)"
	decrypt_vault_to_file "$tmp"

	print_vault_table "$tmp"

	secure_wipe "$tmp"
}

cmd_get() {
	[ $# -ge 1 ] || die "Usage: $0 get <id | search-pattern>"

	local query="$1"

	[ -f "$VAULT_FILE" ] || die "Vault not found. Run '$0 init' first."

	local tmp
	tmp="$(make_tmp)"
	decrypt_vault_to_file "$tmp"

	if printf '%s' "$query" | grep -Eq '^[0-9]+$'; then
		local line
		line="$(get_entry_by_id "$tmp" "$query")" || true
		if [ -z "$line" ]; then
			secure_wipe "$tmp"
			if [ "$SPM_LANG" = "id" ]; then
				die "Tidak ada entry dengan ID $query."
			else
				die "No entry found with ID $query."
			fi
		fi

		IFS=$'\t' read -r id service username password notes created url <<EOF
$line
EOF

		# Backward-compat: old rows might have created_at in notes field
		if [ -z "${created:-}" ] && printf '%s\n' "${notes:-}" | grep -Eq '^[0-9]{4}-[0-9]{2}-[0-9]{2}T'; then
			created="$notes"
			notes=""
		fi

		if [ "$SPM_LANG" = "id" ]; then
			printf "ID:              %s\n" "$id"
			printf "Layanan:         %s\n" "$service"
			printf "Username / Email: %s\n" "$username"
			printf "Password:        %s\n" "$password"
			printf "URL:             %s\n" "${url:-}"
			printf "Catatan:         %s\n" "$notes"
			printf "Dibuat:          %s\n" "$created"
		else
			printf "ID:               %s\n" "$id"
			printf "Service:          %s\n" "$service"
			printf "Username / Email: %s\n" "$username"
			printf "Password:         %s\n" "$password"
			printf "URL:              %s\n" "${url:-}"
			printf "Notes:            %s\n" "$notes"
			printf "Created:          %s\n" "$created"
		fi

		copy_password_with_autoclear "$password"
	else
		if [ "$SPM_LANG" = "id" ]; then
			printf "Hasil untuk pola '%s':\n" "$query"
		else
			printf "Matches for pattern '%s':\n" "$query"
		fi
		search_vault "$tmp" "$query"
	fi

	secure_wipe "$tmp"
}

cmd_edit() {
	[ -f "$VAULT_FILE" ] || die "Vault not found. Run '$0 init' first."

	local tmp
	tmp="$(make_tmp)"
	decrypt_vault_to_file "$tmp"

	if [ "$SPM_LANG" = "id" ]; then
		printf "Membuka vault di editor: %s\n" "$EDITOR_CMD"
		printf "# Format password: id<TAB>service<TAB>username<TAB>password<TAB>notes<TAB>created_at<TAB>url\n" >&2
		printf "# Format note    : NOTE<TAB>note_id<TAB>title<TAB>base64_note<TAB>created_at<TAB>-\n" >&2
		printf "# Format passphrase: PASSPHRASE<TAB>id<TAB>label<TAB>base64_passphrase<TAB>created_at<TAB>-\n" >&2
		printf "# Format backup code: BACKUP_CODE<TAB>id<TAB>label<TAB>base64_codes<TAB>created_at<TAB>-\n" >&2
		printf "# Format authenticator: AUTH<TAB>id<TAB>label<TAB>base32_secret<TAB>period<TAB>created_at<TAB>algorithm\n" >&2
		printf "# Baris meta     : META_RECOVERY_PUBKEY...\n" >&2
	else
		printf "Opening vault in editor: %s\n" "$EDITOR_CMD"
		printf "# Password rows: id<TAB>service<TAB>username<TAB>password<TAB>notes<TAB>created_at<TAB>url\n" >&2
		printf "# Note rows    : NOTE<TAB>note_id<TAB>title<TAB>base64_note<TAB>created_at<TAB>-\n" >&2
		printf "# Passphrase rows: PASSPHRASE<TAB>id<TAB>label<TAB>base64_passphrase<TAB>created_at<TAB>-\n" >&2
		printf "# Backup code rows: BACKUP_CODE<TAB>id<TAB>label<TAB>base64_codes<TAB>created_at<TAB>-\n" >&2
		printf "# Authenticator rows: AUTH<TAB>id<TAB>label<TAB>base32_secret<TAB>period<TAB>created_at<TAB>algorithm\n" >&2
		printf "# Meta row     : META_RECOVERY_PUBKEY...\n" >&2
	fi

	# EDITOR commonly carries arguments ("code --wait"); running the whole value
	# as one executable name made every such configuration fail.
	local editor_argv=()
	read -r -a editor_argv <<<"$EDITOR_CMD"
	[ "${#editor_argv[@]}" -gt 0 ] || editor_argv=(nano)
	"${editor_argv[@]}" "$tmp"

	encrypt_file_to_vault "$tmp"
	secure_wipe "$tmp"

	if [ "$SPM_LANG" = "id" ]; then
		printf "Vault diperbarui.\n"
	else
		printf "Vault updated.\n"
	fi
}

cmd_change_master() {
	[ -f "$VAULT_FILE" ] || die "Vault not found. Run '$0 init' first."
	require_cmd openssl

	local tmp
	tmp="$(make_tmp)"

	if [ "$SPM_LANG" = "id" ]; then
		printf "Masukkan kata sandi utama LAMA untuk membuka vault.\n"
	else
		printf "Enter OLD master password to decrypt vault.\n"
	fi
	decrypt_vault_to_file "$tmp"

	# A legacy vault is migrated FIRST, while MASTER_PW is still the old
	# password -- so the key envelope and the recovery file agree at every
	# instant. Doing it after the prompt would seal the envelope under the new
	# password while .recovery still named the old one, and neither would open
	# the vault if the process died in between.
	local migrated=0
	if [ -z "${VAULT_KEY:-}" ]; then
		encrypt_file_to_vault "$tmp"
		migrated=1
	fi

	if [ "$SPM_LANG" = "id" ]; then
		printf "Masukkan kata sandi utama BARU.\n"
	else
		printf "Enter NEW master password.\n"
	fi
	prompt_master_password

	# Only the small envelope is rewritten. The vault ciphertext and the
	# recovery file both key off the vault key, which does not change.
	rewrap_vault_key "$MASTER_PW"
	secure_wipe "$tmp"

	if [ "$SPM_LANG" = "id" ]; then
		printf "Kata sandi utama berhasil diubah.\n"
		if [ "$migrated" -eq 1 ]; then
			printf "Vault dimigrasikan ke format kunci terbungkus.\n"
			printf "File pemulihan diperbarui di: %s\n" "$RECOVERY_FILE"
		else
			printf "Kunci vault dibungkus ulang; data vault dan file pemulihan tidak berubah.\n"
		fi
	else
		printf "Master password changed successfully.\n"
		if [ "$migrated" -eq 1 ]; then
			printf "The vault was migrated to the wrapped-key format.\n"
			printf "Recovery file updated at: %s\n" "$RECOVERY_FILE"
		else
			printf "Vault key rewrapped; the vault data and recovery file are unchanged.\n"
		fi
	fi
}

cmd_delete() {
	[ $# -ge 1 ] || die "Usage: $0 delete <id>"

	local target_id="$1"

	[ -f "$VAULT_FILE" ] || die "Vault not found. Run '$0 init' first."

	local tmp
	tmp="$(make_tmp)"
	decrypt_vault_to_file "$tmp"

	if ! awk -F '\t' -v target="$target_id" '$1 ~ /^[0-9]+$/ && $1 == target {found=1} END {exit(found?0:1)}' "$tmp"; then
		secure_wipe "$tmp"
		if [ "$SPM_LANG" = "id" ]; then
			die "Tidak ada entry dengan ID $target_id."
		else
			die "No entry found with ID $target_id."
		fi
	fi

	local tmp2
	tmp2="$(make_tmp)"
	awk -F '\t' -v target="$target_id" '
		!($1 ~ /^[0-9]+$/ && $1 == target) {print $0}
	' "$tmp" >"$tmp2"

	encrypt_file_to_vault "$tmp2"
	secure_wipe "$tmp"
	secure_wipe "$tmp2"

	if [ "$SPM_LANG" = "id" ]; then
		printf "Entry dengan ID %s dihapus.\n" "$target_id"
	else
		printf "Entry with ID %s deleted.\n" "$target_id"
	fi
}

# ----- Secure notes commands -------------------------------------------------

cmd_notes_add() {
	[ -f "$VAULT_FILE" ] || die "Vault not found. Run '$0 init' first."
	local tmp
	tmp="$(make_tmp)"
	decrypt_vault_to_file "$tmp"

	if [ "$SPM_LANG" = "id" ]; then
		printf "Judul catatan: "
	else
		printf "Note title: "
	fi
	IFS= read -r title
	[ -n "$title" ] || die "Title cannot be empty."

	if [ "$SPM_LANG" = "id" ]; then
		printf "\nTulis isi catatan. Akhiri dengan Ctrl+D di baris baru.\n\n"
	else
		printf "\nType your note content. Finish with Ctrl+D on a new line.\n\n"
	fi

	local tmp_note
	tmp_note="$(make_tmp)"
	cat >"$tmp_note"

	local body_b64
	body_b64="$(base64 <"$tmp_note" | tr -d '\n')"
	local note_id created
	note_id="$(next_note_id_from_vault "$tmp")"
	created="$(now_iso)"

	printf 'NOTE\t%s\t%s\t%s\t%s\t-\n' "$note_id" "$(sanitize_field "$title")" "$body_b64" "$created" >>"$tmp"

	encrypt_file_to_vault "$tmp"
	secure_wipe "$tmp"
	secure_wipe "$tmp_note"

	if [ "$SPM_LANG" = "id" ]; then
		printf "\nCatatan aman ditambahkan dengan ID %s.\n" "$note_id"
	else
		printf "\nSecure note added with ID %s.\n" "$note_id"
	fi
}

cmd_notes_list() {
	[ -f "$VAULT_FILE" ] || die "Vault not found. Run '$0 init' first."

	local tmp
	tmp="$(make_tmp)"
	decrypt_vault_to_file "$tmp"

	if [ "$SPM_LANG" = "id" ]; then
		printf "%-5s  %-30s  %-20s\n" "ID" "Judul" "Dibuat"
	else
		printf "%-5s  %-30s  %-20s\n" "ID" "Title" "Created"
	fi
	printf '%.0s-' $(seq 1 70)
	printf '\n'

	# Print notes
	awk -F '\t' '
		$1=="NOTE" {
			printf "%-5s  %-30s  %-20s\n", $2, $3, $5;
		}
	' "$tmp"

	# Count notes (separate, simpler, and portable)
	local count
	count="$(awk -F '\t' '$1=="NOTE"{n++} END{print n+0}' "$tmp")"

	if [ "$count" -eq 0 ]; then
		if [ "$SPM_LANG" = "id" ]; then
			printf "\nTidak ada catatan.\n"
		else
			printf "\nNo notes.\n"
		fi
	fi

	secure_wipe "$tmp"
}

cmd_notes_view() {
	[ $# -ge 1 ] || die "Usage: $0 notes-view <id>"
	local target="$1"

	[ -f "$VAULT_FILE" ] || die "Vault not found. Run '$0 init' first."

	local tmp
	tmp="$(make_tmp)"
	decrypt_vault_to_file "$tmp"

	local line
	line="$(awk -F '\t' -v target="$target" '$1=="NOTE" && $2==target {print $0; exit}' "$tmp")" || true

	if [ -z "$line" ]; then
		secure_wipe "$tmp"
		if [ "$SPM_LANG" = "id" ]; then
			die "Tidak ada catatan dengan ID $target."
		else
			die "No note found with ID $target."
		fi
	fi

	local tag nid title body_b64 created dummy
	IFS=$'\t' read -r tag nid title body_b64 created dummy <<EOF
$line
EOF

	local tmp_note
	tmp_note="$(make_tmp)"
	if ! printf '%s' "$body_b64" | base64 -d >"$tmp_note" 2>/dev/null; then
		secure_wipe "$tmp_note"
		secure_wipe "$tmp"
		die "Failed to decode note body (base64)."
	fi

	if [ "$SPM_LANG" = "id" ]; then
		printf "ID:      %s\n" "$nid"
		printf "Judul:   %s\n" "$title"
		printf "Dibuat:  %s\n" "$created"
		printf "\nIsi catatan:\n\n"
	else
		printf "ID:      %s\n" "$nid"
		printf "Title:   %s\n" "$title"
		printf "Created: %s\n" "$created"
		printf "\nNote content:\n\n"
	fi

	cat "$tmp_note"

	secure_wipe "$tmp_note"
	secure_wipe "$tmp"
}

cmd_notes_delete() {
	[ $# -ge 1 ] || die "Usage: $0 notes-delete <id>"
	local target="$1"

	[ -f "$VAULT_FILE" ] || die "Vault not found. Run '$0 init' first."

	local tmp
	tmp="$(make_tmp)"
	decrypt_vault_to_file "$tmp"

	if ! awk -F '\t' -v target="$target" '$1=="NOTE" && $2==target {found=1} END{exit(found?0:1)}' "$tmp"; then
		secure_wipe "$tmp"
		if [ "$SPM_LANG" = "id" ]; then
			die "Tidak ada catatan dengan ID $target."
		else
			die "No note found with ID $target."
		fi
	fi

	local tmp2
	tmp2="$(make_tmp)"
	awk -F '\t' -v target="$target" '
		!($1=="NOTE" && $2==target) {print $0}
	' "$tmp" >"$tmp2"

	encrypt_file_to_vault "$tmp2"
	secure_wipe "$tmp"
	secure_wipe "$tmp2"

	if [ "$SPM_LANG" = "id" ]; then
		printf "Catatan dengan ID %s dihapus.\n" "$target"
	else
		printf "Note with ID %s deleted.\n" "$target"
	fi
}

# ----- Passphrase commands ---------------------------------------------------

cmd_passphrase_add() {
	[ -f "$VAULT_FILE" ] || die "Vault not found. Run '$0 init' first."

	local tmp
	tmp="$(make_tmp)"
	decrypt_vault_to_file "$tmp"

	if [ "$SPM_LANG" = "id" ]; then
		printf "Label passphrase: "
	else
		printf "Passphrase label: "
	fi
	IFS= read -r label
	[ -n "$label" ] || die "Label cannot be empty."

	if [ "$SPM_LANG" = "id" ]; then
		printf "Passphrase (kosongkan untuk auto-generate 32 karakter): "
	else
		printf "Passphrase (blank to auto-generate 32 chars): "
	fi
	stty -echo
	IFS= read -r secret
	stty echo
	printf '\n'

	if [ -z "$secret" ]; then
		if command -v openssl >/dev/null 2>&1; then
			secret="$(openssl rand -base64 48 | tr -d '\n' | head -c 32)"
		else
			secret="$(tr -dc 'A-Za-z0-9!@#$%^&*()_+-=' </dev/urandom | head -c 32)"
		fi
		if [ "$SPM_LANG" = "id" ]; then
			printf "Passphrase dibuat otomatis.\n"
		else
			printf "Passphrase auto-generated.\n"
		fi
	fi

	local pass_id created
	pass_id="$(next_passphrase_id_from_vault "$tmp")"
	created="$(now_iso)"
	local secret_b64
	secret_b64="$(printf '%s' "$secret" | base64 | tr -d '\n')"

	printf 'PASSPHRASE\t%s\t%s\t%s\t%s\t-\n' "$pass_id" "$(sanitize_field "$label")" "$secret_b64" "$created" >>"$tmp"

	encrypt_file_to_vault "$tmp"
	secure_wipe "$tmp"

	if [ "$SPM_LANG" = "id" ]; then
		printf "Passphrase ditambahkan dengan ID %s.\n" "$pass_id"
	else
		printf "Passphrase added with ID %s.\n" "$pass_id"
	fi
}

cmd_passphrase_list() {
	[ -f "$VAULT_FILE" ] || die "Vault not found. Run '$0 init' first."

	local tmp
	tmp="$(make_tmp)"
	decrypt_vault_to_file "$tmp"

	if [ "$SPM_LANG" = "id" ]; then
		printf "%-5s  %-30s  %-20s\n" "ID" "Label" "Dibuat"
	else
		printf "%-5s  %-30s  %-20s\n" "ID" "Label" "Created"
	fi
	printf '%.0s-' $(seq 1 70)
	printf '\n'

	awk -F '\t' '
		$1=="PASSPHRASE" {
			printf "%-5s  %-30s  %-20s\n", $2, $3, $5;
		}
	' "$tmp"

	local count
	count="$(awk -F '\t' '$1=="PASSPHRASE"{n++} END{print n+0}' "$tmp")"
	if [ "$count" -eq 0 ]; then
		if [ "$SPM_LANG" = "id" ]; then
			printf "\nTidak ada passphrase.\n"
		else
			printf "\nNo passphrases stored.\n"
		fi
	fi

	secure_wipe "$tmp"
}

cmd_passphrase_view() {
	[ $# -ge 1 ] || die "Usage: $0 passphrase-view <id>"
	local target="$1"

	[ -f "$VAULT_FILE" ] || die "Vault not found. Run '$0 init' first."

	# Require re-verification for sensitive viewing
	re_verify_master_password

	local tmp
	tmp="$(make_tmp)"
	decrypt_vault_to_file "$tmp"

	local line
	line="$(awk -F '\t' -v target="$target" '$1=="PASSPHRASE" && $2==target {print $0; exit}' "$tmp")" || true
	if [ -z "$line" ]; then
		secure_wipe "$tmp"
		if [ "$SPM_LANG" = "id" ]; then
			die "Tidak ada passphrase dengan ID $target."
		else
			die "No passphrase found with ID $target."
		fi
	fi

	local tag pid label secret_b64 created dummy
	IFS=$'\t' read -r tag pid label secret_b64 created dummy <<EOF
$line
EOF
	: "$tag" "$dummy"

	local tmp_secret
	tmp_secret="$(make_tmp)"
	if ! printf '%s' "$secret_b64" | base64 -d >"$tmp_secret" 2>/dev/null; then
		secure_wipe "$tmp_secret"
		secure_wipe "$tmp"
		die "Failed to decode passphrase (base64)."
	fi

	local secret_value
	secret_value="$(cat "$tmp_secret")"

	if [ "$SPM_LANG" = "id" ]; then
		printf "ID:        %s\n" "$pid"
		printf "Label:     %s\n" "$label"
		printf "Dibuat:    %s\n" "$created"
		printf "Passphrase:%s\n" " "
	else
		printf "ID:        %s\n" "$pid"
		printf "Label:     %s\n" "$label"
		printf "Created:   %s\n" "$created"
		printf "Passphrase:%s\n" " "
	fi

	printf "%s\n" "$secret_value"
	copy_password_with_autoclear "$secret_value"

	secure_wipe "$tmp_secret"
	secure_wipe "$tmp"
}

cmd_passphrase_delete() {
	[ $# -ge 1 ] || die "Usage: $0 passphrase-delete <id>"
	local target="$1"

	[ -f "$VAULT_FILE" ] || die "Vault not found. Run '$0 init' first."

	local tmp
	tmp="$(make_tmp)"
	decrypt_vault_to_file "$tmp"

	if ! awk -F '\t' -v target="$target" '$1=="PASSPHRASE" && $2==target {found=1} END{exit(found?0:1)}' "$tmp"; then
		secure_wipe "$tmp"
		if [ "$SPM_LANG" = "id" ]; then
			die "Tidak ada passphrase dengan ID $target."
		else
			die "No passphrase found with ID $target."
		fi
	fi

	local tmp2
	tmp2="$(make_tmp)"
	awk -F '\t' -v target="$target" '
		!($1=="PASSPHRASE" && $2==target) {print $0}
	' "$tmp" >"$tmp2"

	encrypt_file_to_vault "$tmp2"
	secure_wipe "$tmp"
	secure_wipe "$tmp2"

	if [ "$SPM_LANG" = "id" ]; then
		printf "Passphrase dengan ID %s dihapus.\n" "$target"
	else
		printf "Passphrase with ID %s deleted.\n" "$target"
	fi
}

# ----- Authenticator (TOTP) commands ----------------------------------------

_spm_totp_code() {
	local secret="$1"
	local period="$2"
	local algo="${3:-sha1}"
	python3 - "$secret" "$period" "$algo" <<'PY'
import base64, hashlib, hmac, struct, time, sys
secret = (sys.argv[1] if len(sys.argv) > 1 else "").replace(" ", "").upper()
if not secret:
    sys.exit(1)
period = int(sys.argv[2]) if len(sys.argv) > 2 and sys.argv[2].isdigit() and int(sys.argv[2]) > 0 else 30
algo = sys.argv[3].lower() if len(sys.argv) > 3 else "sha1"
if algo not in ("sha1", "sha256", "sha512"):
    algo = "sha1"
try:
    key = base64.b32decode(secret + "=" * ((8 - len(secret) % 8) % 8), casefold=True)
except Exception:
    sys.exit(1)
counter = int(time.time() // period)
msg = struct.pack(">Q", counter)
digest_mod = {"sha1": hashlib.sha1, "sha256": hashlib.sha256, "sha512": hashlib.sha512}[algo]
h = hmac.new(key, msg, digest_mod).digest()
offset = h[-1] & 0x0F
code_int = struct.unpack(">I", h[offset:offset+4])[0] & 0x7fffffff
code = str(code_int % 10**6).zfill(6)
print(code)
PY
}

cmd_authenticator_add() {
	[ -f "$VAULT_FILE" ] || die "Vault not found. Run '$0 init' first."

	local tmp
	tmp="$(make_tmp)"
	decrypt_vault_to_file "$tmp"

	if [ "$SPM_LANG" = "id" ]; then
		printf "Label authenticator: "
	else
		printf "Authenticator label: "
	fi
	IFS= read -r label
	[ -n "$label" ] || die "Label cannot be empty."

	if [ "$SPM_LANG" = "id" ]; then
		printf "Secret (Base32, contoh: JBSWY3DPEHPK3PXP): "
	else
		printf "Secret (Base32, e.g., JBSWY3DPEHPK3PXP): "
	fi
	stty -echo
	IFS= read -r secret
	stty echo
	printf '\n'
	secret="${secret//[[:space:]]/}"
	[ -n "$secret" ] || die "Secret cannot be empty."

	local period
	if [ "$SPM_LANG" = "id" ]; then
		printf "Interval refresh (detik, default 30): "
	else
		printf "Refresh interval (seconds, default 30): "
	fi
	read -r period || true
	if ! printf '%s' "$period" | grep -Eq '^[0-9]+$'; then
		period="30"
	fi
	[ "$period" -gt 0 ] 2>/dev/null || period="30"

	local algo
	if [ "$SPM_LANG" = "id" ]; then
		printf "Algoritma (sha1/sha256/sha512) [sha1]: "
	else
		printf "Algorithm (sha1/sha256/sha512) [sha1]: "
	fi
	read -r algo || true
	case "${algo,,}" in
		sha1|sha256|sha512) ;;
		*) algo="sha1" ;;
	esac

	# validate secret by generating code
	if ! _spm_totp_code "$secret" "$period" "$algo" >/dev/null 2>&1; then
		die "Invalid Base32 secret for TOTP."
	fi

	local auth_id created
	auth_id="$(next_authenticator_id_from_vault "$tmp")"
	created="$(now_iso)"
	local secret_b32
	secret_b32="$(printf '%s' "$secret" | tr -d '\n' | tr '[:lower:]' '[:upper:]')"

	printf 'AUTH\t%s\t%s\t%s\t%s\t%s\t%s\n' "$auth_id" "$(sanitize_field "$label")" "$secret_b32" "$period" "$created" "$algo" >>"$tmp"

	encrypt_file_to_vault "$tmp"
	secure_wipe "$tmp"

	if [ "$SPM_LANG" = "id" ]; then
		printf "Authenticator ditambahkan dengan ID %s.\n" "$auth_id"
	else
		printf "Authenticator added with ID %s.\n" "$auth_id"
	fi
}

cmd_authenticator_list() {
	[ -f "$VAULT_FILE" ] || die "Vault not found. Run '$0 init' first."

	local tmp
	tmp="$(make_tmp)"
	decrypt_vault_to_file "$tmp"

	if [ "$SPM_LANG" = "id" ]; then
		printf "%-5s  %-24s  %-8s  %-8s  %-20s\n" "ID" "Label" "Interval" "Algo" "Dibuat"
	else
		printf "%-5s  %-24s  %-8s  %-8s  %-20s\n" "ID" "Label" "Interval" "Algo" "Created"
	fi
	printf '%.0s-' $(seq 1 85)
	printf '\n'

	awk -F '\t' '
		$1=="AUTH" {
			period=($5? $5 : $4);
			created=($6? $6 : $5);
			algo=($7? $7 : "sha1");
			printf "%-5s  %-24s  %-8s  %-8s  %-20s\n", $2, $3, period, algo, created;
		}
	' "$tmp"

	local count
	count="$(awk -F '\t' '$1=="AUTH"{n++} END{print n+0}' "$tmp")"
	if [ "$count" -eq 0 ]; then
		if [ "$SPM_LANG" = "id" ]; then
			printf "\nTidak ada authenticator.\n"
		else
			printf "\nNo authenticators stored.\n"
		fi
	fi

	secure_wipe "$tmp"
}

cmd_authenticator_view() {
	[ $# -ge 1 ] || die "Usage: $0 authenticator-view <id>"
	local target="$1"

	[ -f "$VAULT_FILE" ] || die "Vault not found. Run '$0 init' first."

	re_verify_master_password

	local tmp
	tmp="$(make_tmp)"
	decrypt_vault_to_file "$tmp"

	local line
	line="$(awk -F '\t' -v target="$target" '$1=="AUTH" && $2==target {print $0; exit}' "$tmp")" || true
	if [ -z "$line" ]; then
		secure_wipe "$tmp"
		if [ "$SPM_LANG" = "id" ]; then
			die "Tidak ada authenticator dengan ID $target."
		else
			die "No authenticator found with ID $target."
		fi
	fi

	local tag aid label secret_b32 period created algo
	IFS=$'\t' read -r tag aid label secret_b32 period created algo <<EOF
$line
EOF

	local period_sec
	if printf '%s' "$period" | grep -Eq '^[0-9]+$'; then
		period_sec="$period"
	else
		period_sec=30
	fi
	[ "$period_sec" -gt 0 ] 2>/dev/null || period_sec=30
	[ -n "$algo" ] || algo="sha1"

	if [ "$SPM_LANG" = "id" ]; then
		printf "ID:       %s\n" "$aid"
		printf "Label:    %s\n" "$label"
		printf "Interval: %s detik\n" "$period_sec"
		printf "Dibuat:   %s\n" "$created"
		printf "Algoritma: %s\n" "$algo"
		printf "Secret:   %s\n" "$secret_b32"
		printf "Kode OTP (live, Ctrl+C untuk keluar):\n"
	else
		printf "ID:       %s\n" "$aid"
		printf "Label:    %s\n" "$label"
		printf "Interval: %s seconds\n" "$period_sec"
		printf "Created:  %s\n" "$created"
		printf "Algo:     %s\n" "$algo"
		printf "Secret:   %s\n" "$secret_b32"
		printf "OTP Code (live, Ctrl+C to stop):\n"
	fi

	trap 'printf "\n"; secure_wipe "$tmp"; exit 0' INT TERM

	while true; do
		local code
		code="$(_spm_totp_code "$secret_b32" "$period_sec" "$algo" 2>/dev/null || true)"
		local now rem
		now="$(date +%s)"
		rem=$((period_sec - (now % period_sec)))
		if [ "$rem" -le 0 ]; then
			rem="$period_sec"
		fi

		if [ "$SPM_LANG" = "id" ]; then
			printf "\rKode: %s  (refresh dalam %2ds)   " "${code:-"------"}" "$rem"
		else
			printf "\rCode: %s  (refresh in %2ds)   " "${code:-"------"}" "$rem"
		fi
		sleep 1
	done
}

cmd_authenticator_edit() {
	[ $# -ge 1 ] || die "Usage: $0 authenticator-edit <id>"
	local target="$1"
	[ -f "$VAULT_FILE" ] || die "Vault not found. Run '$0 init' first."

	local tmp
	tmp="$(make_tmp)"
	decrypt_vault_to_file "$tmp"

	local line
	line="$(awk -F '\t' -v target="$target" '$1=="AUTH" && $2==target {print $0; exit}' "$tmp")" || true
	if [ -z "$line" ]; then
		secure_wipe "$tmp"
		die "Authenticator not found."
	fi

	local tag aid label secret_b32 period created algo
	IFS=$'\t' read -r tag aid label secret_b32 period created algo <<EOF
$line
EOF
	: "$tag"
	[ -n "$algo" ] || algo="sha1"

	if [ "$SPM_LANG" = "id" ]; then
		printf "Label baru (kosong = tetap \"%s\"): " "$label"
	else
		printf "New label (blank keeps \"%s\"): " "$label"
	fi
	IFS= read -r new_label
	[ -n "$new_label" ] && label="$new_label"

	if [ "$SPM_LANG" = "id" ]; then
		printf "Secret baru Base32 (kosong = tetap): "
	else
		printf "New Base32 secret (blank keeps current): "
	fi
	stty -echo
	IFS= read -r new_secret
	stty echo
	printf '\n'
	new_secret="${new_secret//[[:space:]]/}"
	[ -n "$new_secret" ] && secret_b32="$new_secret"

	if [ "$SPM_LANG" = "id" ]; then
		printf "Interval baru (detik, kosong = %s): " "$period"
	else
		printf "New interval (seconds, blank = %s): " "$period"
	fi
	read -r new_period || true
	if printf '%s' "$new_period" | grep -Eq '^[0-9]+$'; then
		period="$new_period"
	fi
	[ "$period" -gt 0 ] 2>/dev/null || period="30"

	if [ "$SPM_LANG" = "id" ]; then
		printf "Algorithm (sha1/sha256/sha512, kosong = %s): " "$algo"
	else
		printf "Algorithm (sha1/sha256/sha512, blank = %s): " "$algo"
	fi
	read -r new_algo || true
	case "${new_algo,,}" in
		sha1|sha256|sha512) algo="$new_algo" ;;
		*) ;;
	esac

	if ! _spm_totp_code "$secret_b32" "$period" "$algo" >/dev/null 2>&1; then
		secure_wipe "$tmp"
		die "Invalid secret or interval."
	fi

	local tmp2
	tmp2="$(make_tmp)"
	awk -F '\t' -v target="$target" -v label="$label" -v secret="$secret_b32" -v period="$period" -v created="$created" -v algo="$algo" '
		$1=="AUTH" && $2==target {
			printf "AUTH\t%s\t%s\t%s\t%s\t%s\t%s\n", $2, label, secret, period, created, algo;
			next
		}
		{print $0}
	' "$tmp" >"$tmp2"

	encrypt_file_to_vault "$tmp2"
	secure_wipe "$tmp"
	secure_wipe "$tmp2"

	if [ "$SPM_LANG" = "id" ]; then
		printf "Authenticator ID %s diperbarui.\n" "$target"
	else
		printf "Authenticator ID %s updated.\n" "$target"
	fi
}

cmd_authenticator_delete() {
	[ $# -ge 1 ] || die "Usage: $0 authenticator-delete <id>"
	local target="$1"
	[ -f "$VAULT_FILE" ] || die "Vault not found. Run '$0 init' first."

	local tmp
	tmp="$(make_tmp)"
	decrypt_vault_to_file "$tmp"

	if ! awk -F '\t' -v target="$target" '$1=="AUTH" && $2==target {found=1} END{exit(found?0:1)}' "$tmp"; then
		secure_wipe "$tmp"
		die "Authenticator not found."
	fi

	local tmp2
	tmp2="$(make_tmp)"
	awk -F '\t' -v target="$target" '
		!($1=="AUTH" && $2==target) {print $0}
	' "$tmp" >"$tmp2"

	encrypt_file_to_vault "$tmp2"
	secure_wipe "$tmp"
	secure_wipe "$tmp2"

	if [ "$SPM_LANG" = "id" ]; then
		printf "Authenticator ID %s dihapus.\n" "$target"
	else
		printf "Authenticator ID %s deleted.\n" "$target"
	fi
}

# ----- Backup codes commands -------------------------------------------------

cmd_backup_codes_add() {
	[ -f "$VAULT_FILE" ] || die "Vault not found. Run '$0 init' first."
	local tmp
	tmp="$(make_tmp)"
	decrypt_vault_to_file "$tmp"

	if [ "$SPM_LANG" = "id" ]; then
		printf "Label untuk kode backup (contoh: Google 2FA, GitHub Recovery): "
	else
		printf "Label for backup codes (e.g., Google 2FA, GitHub Recovery): "
	fi
	IFS= read -r label
	[ -n "$label" ] || die "Label cannot be empty."

	if [ "$SPM_LANG" = "id" ]; then
		printf "\nMasukkan kode backup, satu per baris. Akhiri dengan Ctrl+D di baris baru.\n\n"
	else
		printf "\nEnter backup codes, one per line. Finish with Ctrl+D on a new line.\n\n"
	fi

	local tmp_codes
	tmp_codes="$(make_tmp)"
	cat >"$tmp_codes"

	local codes_b64
	codes_b64="$(base64 <"$tmp_codes" | tr -d '\n')"
	local bc_id created
	bc_id="$(next_backup_code_id_from_vault "$tmp")"
	created="$(now_iso)"

	printf 'BACKUP_CODE\t%s\t%s\t%s\t%s\t-\n' "$bc_id" "$(sanitize_field "$label")" "$codes_b64" "$created" >>"$tmp"

	encrypt_file_to_vault "$tmp"
	secure_wipe "$tmp"
	secure_wipe "$tmp_codes"

	if [ "$SPM_LANG" = "id" ]; then
		printf "\nKode backup ditambahkan dengan ID %s.\n" "$bc_id"
	else
		printf "\nBackup codes added with ID %s.\n" "$bc_id"
	fi
}

cmd_backup_codes_list() {
	[ -f "$VAULT_FILE" ] || die "Vault not found. Run '$0 init' first."

	local tmp
	tmp="$(make_tmp)"
	decrypt_vault_to_file "$tmp"

	if [ "$SPM_LANG" = "id" ]; then
		printf "%-5s  %-30s  %-20s\n" "ID" "Label" "Dibuat"
	else
		printf "%-5s  %-30s  %-20s\n" "ID" "Label" "Created"
	fi
	printf '%.0s-' $(seq 1 70)
	printf '\n'

	awk -F '\t' '
		$1=="BACKUP_CODE" {
			printf "%-5s  %-30s  %-20s\n", $2, $3, $5;
		}
	' "$tmp"

	local count
	count="$(awk -F '\t' '$1=="BACKUP_CODE"{n++} END{print n+0}' "$tmp")"

	if [ "$count" -eq 0 ]; then
		if [ "$SPM_LANG" = "id" ]; then
			printf "\nTidak ada kode backup.\n"
		else
			printf "\nNo backup codes.\n"
		fi
	fi

	secure_wipe "$tmp"
}

cmd_backup_codes_view() {
	[ $# -ge 1 ] || die "Usage: $0 backup-codes-view <id>"
	local target="$1"

	[ -f "$VAULT_FILE" ] || die "Vault not found. Run '$0 init' first."

	# Re-verify master password before viewing sensitive backup codes
	re_verify_master_password

	local tmp
	tmp="$(make_tmp)"
	decrypt_vault_to_file "$tmp"

	local line
	line="$(awk -F '\t' -v target="$target" '$1=="BACKUP_CODE" && $2==target {print $0; exit}' "$tmp")" || true

	if [ -z "$line" ]; then
		secure_wipe "$tmp"
		if [ "$SPM_LANG" = "id" ]; then
			die "Tidak ada kode backup dengan ID $target."
		else
			die "No backup code found with ID $target."
		fi
	fi

	local bc_id label codes_b64 created
	IFS=$'\t' read -r _ bc_id label codes_b64 created _ <<EOF
$line
EOF

	local tmp_codes
	tmp_codes="$(make_tmp)"
	if ! printf '%s' "$codes_b64" | base64 -d >"$tmp_codes" 2>/dev/null; then
		secure_wipe "$tmp_codes"
		secure_wipe "$tmp"
		die "Failed to decode backup codes (base64)."
	fi

	if [ "$SPM_LANG" = "id" ]; then
		printf "ID:      %s\n" "$bc_id"
		printf "Label:   %s\n" "$label"
		printf "Dibuat:  %s\n" "$created"
		printf "\nIsi kode backup:\n\n"
	else
		printf "ID:      %s\n" "$bc_id"
		printf "Label:   %s\n" "$label"
		printf "Created: %s\n" "$created"
		printf "\nBackup codes content:\n\n"
	fi

	cat "$tmp_codes"

	secure_wipe "$tmp_codes"
	secure_wipe "$tmp"
}

cmd_backup_codes_delete() {
	[ $# -ge 1 ] || die "Usage: $0 backup-codes-delete <id>"
	local target="$1"

	[ -f "$VAULT_FILE" ] || die "Vault not found. Run '$0 init' first."

	local tmp
	tmp="$(make_tmp)"
	decrypt_vault_to_file "$tmp"

	if ! awk -F '\t' -v target="$target" '$1=="BACKUP_CODE" && $2==target {found=1} END{exit(found?0:1)}' "$tmp"; then
		secure_wipe "$tmp"
		if [ "$SPM_LANG" = "id" ]; then
			die "Tidak ada kode backup dengan ID $target."
		else
			die "No backup code found with ID $target."
		fi
	fi

	local tmp2
	tmp2="$(make_tmp)"
	awk -F '\t' -v target="$target" '
		!($1=="BACKUP_CODE" && $2==target) {print $0}
	' "$tmp" >"$tmp2"

	encrypt_file_to_vault "$tmp2"
	secure_wipe "$tmp"
	secure_wipe "$tmp2"

	if [ "$SPM_LANG" = "id" ]; then
		printf "Kode backup dengan ID %s dihapus.\n" "$target"
	else
		printf "Backup code with ID %s deleted.\n" "$target"
	fi
}


# ----- Portable & save bundles -----------------------------------------------





cmd_portable() {
	[ -f "$VAULT_FILE" ] || die "Vault not found at '$VAULT_FILE'. Nothing to export."

	local bundle_name="${1:-"spm_portable_$(date +%Y%m%d_%H%M%S)"}"
	validate_bundle_name "$bundle_name"
	local workdir="./$bundle_name"
	local has_recovery="no"
	local has_priv="no"

	if [ -e "$workdir" ]; then
		die "Target directory '$workdir' already exists. Choose another name."
	fi
	if [ -e "${bundle_name}.zip" ] || [ -e "${bundle_name}.tar.gz" ]; then
		die "Target archive for '$bundle_name' already exists. Choose another name."
	fi

	mkdir -p "$workdir" || die "Failed to create directory '$workdir'."

	# Copy script
	if [ -f "$SCRIPT_SRC" ]; then
		cp "$SCRIPT_SRC" "$workdir/spm.sh" || die "Failed to copy script to bundle."
	else
		die "Cannot resolve script source '$SCRIPT_SRC'."
	fi
	chmod +x "$workdir/spm.sh" 2>/dev/null || true

	# Copy vault
	cp "$VAULT_FILE" "$workdir/spm_vault.gpg" || die "Failed to copy vault to bundle."

	# Copy recovery file if exists
	if [ -f "$RECOVERY_FILE" ]; then
		cp "$RECOVERY_FILE" "$workdir/spm_vault.gpg.recovery" || die "Failed to copy recovery file to bundle."
		has_recovery="yes"
	fi

	# Keep the recovery private key separate by default. Putting it beside the
	# encrypted recovery blob makes possession of one archive equivalent to
	# possession of the master password.
	if [ "${SPM_BUNDLE_INCLUDE_RECOVERY_KEY:-0}" = "1" ] && [ -f "$RECOVERY_PRIV_DEFAULT" ]; then
		cp "$RECOVERY_PRIV_DEFAULT" "$workdir/spm_recovery_private.pem" || die "Failed to copy private key to bundle."
		has_priv="yes"
	fi

	local created_on
	created_on="$(now_iso)"

	# Bundle-local README (EN + ID)
	cat >"$workdir/README.txt" <<EOF
Sans Password Manager (SPM) - Portable Bundle
=============================================

Created: $created_on
Bundle:  $bundle_name

[EN]

This archive is a portable bundle of Sans Password Manager (SPM).

Included files:
  - spm.sh                : main SPM script (Bash)
  - spm_vault.gpg         : encrypted password vault
  - spm_vault.gpg.recovery (optional)
                          : recovery file used with your RSA private key
  - spm_recovery_private.pem (explicit opt-in only)
                          : included only with SPM_BUNDLE_INCLUDE_RECOVERY_KEY=1
  - README.txt            : this instructions file

Usage:
  1. Ensure dependencies are available on this machine:
       - bash, gpg, openssl, curl, zip (or tar), and optional clipboard helpers
  2. Make the script executable if needed:
       chmod +x ./spm.sh
  3. Run:
       ./spm.sh
  4. SPM will:
       - check requirements,
       - ask for language (EN / ID),
       - ask for your master password to open the vault.

Security notes:
  - The recovery private key is excluded by default. Store it separately.
  - SPM_BUNDLE_INCLUDE_RECOVERY_KEY=1 creates a self-contained recovery archive; possession of that archive bypasses the master password.
  - With the private key + this bundle’s recovery file, you can use
    the "forgot password" feature to reset your master password.
  - Anyone who gets both your private key AND this bundle may be able
    to recover your vault depending on your settings. Protect them.

To move to another device:
  - Copy the ZIP / tar.gz file to the target device.
  - Extract it into a folder.
  - Run ./spm.sh from within that folder.

------------------------------------------------------------

[ID]

Arsip ini adalah bundle portabel dari Sans Password Manager (SPM).

File yang disertakan:
  - spm.sh                : script utama SPM (Bash)
  - spm_vault.gpg         : vault kata sandi terenkripsi
  - spm_vault.gpg.recovery (opsional)
                          : file pemulihan yang digunakan bersama private key RSA
  - spm_recovery_private.pem (hanya jika diaktifkan eksplisit)
                          : disertakan hanya dengan SPM_BUNDLE_INCLUDE_RECOVERY_KEY=1
  - README.txt            : file petunjuk ini

Cara pakai:
  1. Pastikan dependensi tersedia di perangkat ini:
       - bash, gpg, openssl, curl, zip (atau tar),
         dan helper clipboard (opsional)
  2. Jadikan script bisa dieksekusi (jika perlu):
       chmod +x ./spm.sh
  3. Jalankan:
       ./spm.sh
  4. SPM akan:
       - cek requirement,
       - menanyakan bahasa (EN / ID),
       - menanyakan kata sandi utama (master password) untuk membuka vault.

Catatan keamanan:
  - Private key pemulihan tidak disertakan secara default. Simpan secara terpisah.
  - SPM_BUNDLE_INCLUDE_RECOVERY_KEY=1 membuat arsip pemulihan lengkap; siapa pun yang memiliki arsip itu dapat melewati kata sandi utama.
  - Dengan private key + file pemulihan di bundle ini, kamu bisa
    menggunakan fitur "lupa password" untuk reset master password.
  - Jika orang lain mendapatkan bundle ini DAN private key-mu,
    ada kemungkinan vault bisa dipulihkan. Lindungi keduanya.

Untuk dipindahkan ke perangkat lain:
  - Salin file ZIP / tar.gz ke perangkat tujuan.
  - Ekstrak ke sebuah folder.
  - Jalankan ./spm.sh dari dalam folder tersebut.

EOF

	# Create archive
	if command -v zip >/dev/null 2>&1; then
		zip -rq "${bundle_name}.zip" "$bundle_name" || die "Failed to create zip archive."
		if [ "$SPM_LANG" = "id" ]; then
			printf "Bundle portable dibuat: %s\n" "${bundle_name}.zip"
		else
			printf "Portable bundle created: %s\n" "${bundle_name}.zip"
		fi
	else
		tar -czf "${bundle_name}.tar.gz" "$bundle_name" || die "Failed to create tar.gz archive."
		if [ "$SPM_LANG" = "id" ]; then
			printf "Peringatan: 'zip' tidak ditemukan. Dibuat tar.gz: %s\n" "${bundle_name}.tar.gz"
		else
			printf "Warning: 'zip' not found. Created tar.gz instead: %s\n" "${bundle_name}.tar.gz"
		fi
	fi

	# Print contents summary
	printf "Contents:\n"
	printf "  - %s/spm.sh\n" "$bundle_name"
	printf "  - %s/spm_vault.gpg\n" "$bundle_name"
	if [ "$has_recovery" = "yes" ]; then
		printf "  - %s/spm_vault.gpg.recovery\n" "$bundle_name"
	fi
	if [ "$has_priv" = "yes" ]; then
		printf "  - %s/spm_recovery_private.pem\n" "$bundle_name"
	fi
	printf "  - %s/README.txt\n" "$bundle_name"
}

# ----- Save (backup + wipe local data) ---------------------------------------

cmd_save() {
	[ -f "$VAULT_FILE" ] || die "Vault not found at '$VAULT_FILE'. Nothing to save."

	# If user provides a name: use that. Else: auto timestamp.
	local input_name="${1:-""}"
	local bundle_name
	if [ -n "$input_name" ]; then
		bundle_name="$input_name"
	else
		bundle_name="spm_save_$(date +%Y%m%d_%H%M%S)"
	fi
	validate_bundle_name "$bundle_name"

	local workdir="./$bundle_name"
	local has_recovery="no"
	local has_priv="no"
	local archive_path=""

	if [ -e "$workdir" ]; then
		die "Target directory '$workdir' already exists. Choose another name."
	fi
	if [ -e "${bundle_name}.zip" ] || [ -e "${bundle_name}.tar.gz" ]; then
		die "Target archive for '$bundle_name' already exists. Choose another name."
	fi

	mkdir -p "$workdir" || die "Failed to create directory '$workdir'."

	# Copy script into bundle
	if [ -f "$SCRIPT_SRC" ]; then
		cp "$SCRIPT_SRC" "$workdir/spm.sh" || die "Failed to copy script to bundle."
	else
		die "Cannot resolve script source '$SCRIPT_SRC'."
	fi
	chmod +x "$workdir/spm.sh" 2>/dev/null || true

	# Copy vault
	cp "$VAULT_FILE" "$workdir/spm_vault.gpg" || die "Failed to copy vault."

	# Copy recovery file if exists
	if [ -f "$RECOVERY_FILE" ]; then
		cp "$RECOVERY_FILE" "$workdir/spm_vault.gpg.recovery" || die "Failed to copy recovery file."
		has_recovery="yes"
	fi

	# Exclude the recovery key unless the user explicitly asks for a single
	# self-contained (and therefore master-password-bypassing) archive.
	if [ "${SPM_BUNDLE_INCLUDE_RECOVERY_KEY:-0}" = "1" ] && [ -f "$RECOVERY_PRIV_DEFAULT" ]; then
		cp "$RECOVERY_PRIV_DEFAULT" "$workdir/spm_recovery_private.pem" || die "Failed to copy private key."
		has_priv="yes"
	fi

	local created_on
	created_on="$(now_iso)"

	# Bilingual README for backup bundle
	cat >"$workdir/README.txt" <<EOF
Sans Password Manager (SPM) - Backup Save Bundle
================================================

Created: $created_on
Bundle:  $bundle_name

This bundle is a secure backup of your SPM vault. After saving, SPM wipes
the local vault from this device.

------------------------------------------------------------
[EN]

Included files:
  - spm.sh                 : executable SPM script
  - spm_vault.gpg          : encrypted vault
  - spm_vault.gpg.recovery : (optional) recovery file
  - spm_recovery_private.pem : explicit opt-in with SPM_BUNDLE_INCLUDE_RECOVERY_KEY=1
  - README.txt             : instructions

How to restore:
  1. Move this archive to the target device.
  2. Extract it into a folder.
  3. Run:
       ./spm.sh
  4. Enter your master password to access your vault.

Security notes:
  - Keep this backup offline (USB, encrypted disk, cloud with 2FA).
  - The recovery private key is excluded by default and should be stored separately.
  - With SPM_BUNDLE_INCLUDE_RECOVERY_KEY=1, the archive can bypass the master password; protect it accordingly.
  - Anyone with both this bundle and your private key could reset the vault password.

------------------------------------------------------------
[ID]

File yang disertakan:
  - spm.sh                   : script SPM
  - spm_vault.gpg            : vault terenkripsi
  - spm_vault.gpg.recovery   : (opsional) file pemulihan
  - spm_recovery_private.pem : hanya dengan SPM_BUNDLE_INCLUDE_RECOVERY_KEY=1
  - README.txt               : petunjuk

Cara mengembalikan:
  1. Pindahkan arsip ini ke perangkat tujuan.
  2. Ekstrak ke sebuah folder.
  3. Jalankan:
       ./spm.sh
  4. Masukkan master password.

Catatan keamanan:
  - Simpan backup di tempat aman (USB, disk terenkripsi, cloud dengan 2FA).
  - Private key pemulihan tidak disertakan secara default dan harus disimpan terpisah.
  - Dengan SPM_BUNDLE_INCLUDE_RECOVERY_KEY=1, arsip dapat melewati kata sandi utama; lindungi dengan ketat.
  - Jika orang lain mendapatkan bundle ini + private key, mereka bisa mereset master password.

EOF

	# Create archive (zip preferred, tar.gz fallback)
	if command -v zip >/dev/null 2>&1; then
		archive_path="${bundle_name}.zip"
		zip -rq "$archive_path" "$bundle_name" || die "Failed to create zip."
		if [ "$SPM_LANG" = "id" ]; then
			printf "Bundle penyimpanan dibuat: %s\n" "$archive_path"
		else
			printf "Save bundle created: %s\n" "$archive_path"
		fi
	else
		archive_path="${bundle_name}.tar.gz"
		tar -czf "$archive_path" "$bundle_name" || die "Failed to create tar.gz."
		if [ "$SPM_LANG" = "id" ]; then
			printf "Zip tidak ditemukan. Dibuat tar.gz: %s\n" "$archive_path"
		else
			printf "Zip not found. Created tar.gz instead: %s\n" "$archive_path"
		fi
	fi

	# A successful archiver exit alone is not enough to justify deleting the
	# local vault. Read the archived member back and require its digest to match.
	local source_vault_sha archived_vault_sha
	source_vault_sha="$(sha256sum "$VAULT_FILE" | awk '{print $1}')"
	if [ "${archive_path##*.}" = "zip" ]; then
		archived_vault_sha="$(unzip -p "$archive_path" "$bundle_name/spm_vault.gpg" 2>/dev/null | sha256sum | awk '{print $1}')"
	else
		archived_vault_sha="$(tar -xOf "$archive_path" "$bundle_name/spm_vault.gpg" 2>/dev/null | sha256sum | awk '{print $1}')"
	fi
	if [ -z "$source_vault_sha" ] || [ "$source_vault_sha" != "$archived_vault_sha" ]; then
		die "Archive verification failed; the local vault was not removed."
	fi

	# Remove the folder, leave ONLY the archive on disk
	rm -rf "$workdir"

	# Secure wipe of local vault + recovery file
	secure_wipe "$VAULT_FILE"
	rm -f "$VAULT_FILE"

	if [ -f "$RECOVERY_FILE" ]; then
		secure_wipe "$RECOVERY_FILE"
		rm -f "$RECOVERY_FILE"
	fi

	if [ "$SPM_LANG" = "id" ]; then
		printf "Vault lokal telah dihapus dari perangkat ini.\n"
	else
		printf "Local vault has been securely wiped from this device.\n"
	fi

	# Summary log
	printf "Archive contents (logical):\n"
	printf "  - spm.sh\n"
	printf "  - spm_vault.gpg\n"
	if [ "$has_recovery" = "yes" ]; then
		printf "  - spm_vault.gpg.recovery\n"
	fi
	if [ "$has_priv" = "yes" ]; then
		printf "  - spm_recovery_private.pem\n"
	fi
	printf "  - README.txt\n"
	printf "Final archive: %s\n" "$archive_path"
}

# ----- Restore helper for portable/save bundles ------------------------------

cmd_restore() {
	local bundle_vault="./spm_vault.gpg"
	local bundle_recovery="./spm_vault.gpg.recovery"
	local dest_vault="$HOME/.spm_vault.gpg"
	local dest_recovery="${dest_vault}.recovery"
	local verify_tmp=""

	if [ "$VAULT_FILE" != "$bundle_vault" ] || [ ! -f "$bundle_vault" ]; then
		if [ "$SPM_LANG" = "id" ]; then
			printf "Perintah restore harus dijalankan dari folder bundle (berisi spm_vault.gpg).\n"
		else
			printf "The restore command must be run inside a portable/save bundle (with spm_vault.gpg next to the script).\n"
		fi
		return 1
	fi

	if [ -f "$dest_vault" ]; then
		if [ "$SPM_LANG" = "id" ]; then
			printf "Vault sudah ada di %s. Timpa? (yes/NO): " "$dest_vault"
		else
			printf "Vault already exists at %s. Overwrite? (yes/NO): " "$dest_vault"
		fi
		local ans
		read -r ans || ans="no"
		case "$ans" in
			yes|y|YES|Y) ;;
			*) printf "Restore dibatalkan.\n"; return 1 ;;
		esac
	fi

	mkdir -p "$(dirname "$dest_vault")" || die "Failed to create destination directory."

	# Lock the DESTINATION. main() already holds a lock, but during restore
	# VAULT_FILE is the bundle, so that lock protects the file being read and
	# not the one being replaced -- a dashboard writing the real vault was free
	# to interleave with the rename that overwrote it.
	acquire_restore_lock "$dest_vault"

	if [ -f "$dest_vault" ]; then
		# Prove the bundle opens before replacing a vault that already does.
		# `sync pull` refuses to install a remote it cannot decrypt; restore
		# installed whatever the bundle held and only found out afterwards, by
		# which point the vault it replaced was gone.
		#
		# Asked only when there is something to lose. Restoring onto a machine
		# with no vault risks nothing, and demanding a password there would
		# break staging a bundle for someone else to open later.
		ensure_master_password_loaded
		verify_tmp="$(make_tmp)"
		if ! decrypt_vault_container "$bundle_vault" "$verify_tmp" "$MASTER_PW"; then
			secure_wipe "$verify_tmp"
			if [ "$SPM_LANG" = "id" ]; then
				die "Vault bundle tidak terbuka dengan kata sandi itu, jadi vault yang ada dibiarkan utuh."
			else
				die "The bundle vault did not open with that master password, so the vault already at $dest_vault was left untouched."
			fi
		fi
		secure_wipe "$verify_tmp"
	fi

	# Archived and copied to .bak before the rename, the way every other write
	# in SPM is. This was the one write that could not be undone.
	core install-file "$bundle_vault" "$dest_vault" >/dev/null \
		|| die "Failed to install the restored vault."

	if [ -f "$bundle_recovery" ]; then
		if [ -f "$dest_recovery" ]; then
			if [ "$SPM_LANG" = "id" ]; then
				printf "File pemulihan sudah ada di %s. Timpa? (yes/NO): " "$dest_recovery"
			else
				printf "Recovery file already exists at %s. Overwrite? (yes/NO): " "$dest_recovery"
			fi
			local ans2
			read -r ans2 || ans2="no"
			case "$ans2" in
				yes|y|YES|Y) ;;
				*) bundle_recovery="" ;;
			esac
		fi
		if [ -n "$bundle_recovery" ] && [ -f "./spm_vault.gpg.recovery" ]; then
			# Reported, not fatal. The vault is already installed and opens
			# under its own master password; dying here would suggest the
			# restore failed when what is actually stale is the recovery file.
			if ! core install-file "./spm_vault.gpg.recovery" "$dest_recovery" --no-archive >/dev/null; then
				printf 'warning: the vault was restored but its recovery file was not; %s still names the previous vault\n' \
					"$dest_recovery" >&2
				bundle_recovery=""
			fi
		fi
	fi

	# The bundle is consumed last. Removing the vault from it first left a
	# bundle holding a recovery file and no vault whenever anything after that
	# point failed.
	rm -f "$bundle_vault"
	if [ -n "$bundle_recovery" ] && [ -f "./spm_vault.gpg.recovery" ]; then
		rm -f "./spm_vault.gpg.recovery"
	fi

	VAULT_FILE="$dest_vault"
	RECOVERY_FILE="$dest_recovery"

	if [ "$SPM_LANG" = "id" ]; then
		printf "Vault dipindahkan ke %s.\n" "$dest_vault"
		if [ -f "$dest_recovery" ]; then
			printf "File pemulihan dipindahkan ke %s.\n" "$dest_recovery"
		fi
		printf "Sesi ini sekarang menggunakan vault di lokasi default; kamu bisa menjalankan SPM seperti biasa dari sana.\n"
	else
		printf "Vault moved to %s.\n" "$dest_vault"
		if [ -f "$dest_recovery" ]; then
			printf "Recovery file moved to %s.\n" "$dest_recovery"
		fi
		printf "This session now points to the default vault; feel free to launch SPM normally from that location.\n"
	fi
}

# ----- Update / Forgot / Doctor ----------------------------------------------

# ----- Auto-update preference ------------------------------------------------
#
# Off by default and never enabled implicitly. The privacy policy promises that
# network activity happens "only for features or deployment choices initiated
# by the user", so the automatic release check has to be something the user
# switches on rather than something they discover running.

autoupdate_get() {
	local key="$1" default="${2:-}" val=""
	if [ -f "$SPM_AUTOUPDATE_FILE" ]; then
		val="$(sed -n "s/^${key}=//p" "$SPM_AUTOUPDATE_FILE" 2>/dev/null | tail -n1)"
	fi
	if [ -n "$val" ]; then printf '%s' "$val"; else printf '%s' "$default"; fi
}

autoupdate_put() {
	local key="$1" val="$2" tmp
	mkdir -p "$SPM_CONFIG_DIR" 2>/dev/null || return 1
	chmod 700 "$SPM_CONFIG_DIR" 2>/dev/null || true
	tmp="$(mktemp "$SPM_CONFIG_DIR/.auto-update.XXXXXX" 2>/dev/null)" || return 1
	if [ -f "$SPM_AUTOUPDATE_FILE" ]; then
		grep -v "^${key}=" "$SPM_AUTOUPDATE_FILE" > "$tmp" 2>/dev/null || true
	fi
	printf '%s=%s\n' "$key" "$val" >> "$tmp"
	mv -f "$tmp" "$SPM_AUTOUPDATE_FILE" || { rm -f "$tmp"; return 1; }
	chmod 600 "$SPM_AUTOUPDATE_FILE" 2>/dev/null || true
}

autoupdate_mode() {
	case "$(autoupdate_get MODE off)" in
		notify) printf 'notify' ;;
		auto) printf 'auto' ;;
		*) printf 'off' ;;
	esac
}

# -1, 0 or 1 for $1 against $2, comparing dotted numeric components.
#
# This used to be `sort -V`, which is a GNU extension: BSD sort, and so macOS,
# has no -V. Where it is missing the option is not ignored -- sort fails and
# the comparison reads an empty string -- and where a lexical sort is
# substituted instead it orders 2.10.10 before 2.10.9, which is precisely
# backwards and precisely what these callers exist to get right. awk is POSIX
# and this script already depends on it everywhere else.
version_compare() {
	awk -v a="$1" -v b="$2" '
	BEGIN {
		na = split(a, x, "."); nb = split(b, y, ".")
		n = (na > nb) ? na : nb
		for (i = 1; i <= n; i++) {
			p = (i <= na) ? x[i] + 0 : 0
			q = (i <= nb) ? y[i] + 0 : 0
			if (p > q) { print 1; exit }
			if (p < q) { print -1; exit }
		}
		print 0
	}'
}

# True when $1 is strictly newer than $2. Plain string equality was enough for
# "is this the same release", but not for "is there a newer one".
version_is_newer() {
	[ "$1" != "$2" ] || return 1
	[ "$(version_compare "$1" "$2")" = "1" ]
}

autoupdate_latest_tag() {
	command -v curl >/dev/null 2>&1 || return 1
	local json
	json="$(curl -fsSL --max-time "${SPM_UPDATE_TIMEOUT:-6}" "$REPO_API_URL" 2>/dev/null)" || return 1
	printf '%s\n' "$json" | grep -m1 '"tag_name"' |
		sed -E 's/.*"tag_name": *"v?([^"]+)".*/\1/'
}

# Called once at startup. Silent and non-fatal in every failure mode: being
# offline, rate-limited, or unable to parse the response must never stop
# someone reaching their vault.
autoupdate_startup_check() {
	local mode; mode="$(autoupdate_mode)"
	[ "$mode" = "off" ] && return 0
	# Only ever speak up on a real terminal; scripted use stays untouched.
	[ -t 0 ] && [ -t 1 ] || return 0

	local now last interval
	now="$(date +%s 2>/dev/null)" || return 0
	last="$(autoupdate_get LAST_CHECK 0)"
	interval="$(autoupdate_get INTERVAL 86400)"
	case "$last" in ''|*[!0-9]*) last=0 ;; esac
	case "$interval" in ''|*[!0-9]*) interval=86400 ;; esac
	[ "$((now - last))" -ge "$interval" ] || return 0

	local latest
	latest="$(autoupdate_latest_tag)" || return 0
	[ -n "$latest" ] || return 0
	autoupdate_put LAST_CHECK "$now" || true
	autoupdate_put LAST_SEEN "$latest" || true
	version_is_newer "$latest" "$VERSION" || return 0

	clear 2>/dev/null || true
	print_banner
	if [ "$SPM_LANG" = "id" ]; then
		printf "Versi baru tersedia: %s (terpasang: %s)\n\n" "$latest" "$VERSION"
	else
		printf "A newer release is available: %s (installed: %s)\n\n" "$latest" "$VERSION"
	fi

	if [ "$mode" = "auto" ]; then
		SPM_UPDATE_ASSUME_YES=1 cmd_update || true
	else
		if [ "$SPM_LANG" = "id" ]; then
			printf "Perbarui sekarang? (yes/NO): "
		else
			printf "Update now? (yes/NO): "
		fi
		local reply; read -r reply || reply="no"
		case "$reply" in
			yes|y|Y|YES) SPM_UPDATE_ASSUME_YES=1 cmd_update || true ;;
			*) return 0 ;;
		esac
	fi
	pause_menu
}

cmd_autoupdate() {
	local action="${1:-status}"
	case "$action" in
		off|notify|auto)
			autoupdate_put MODE "$action" || die "Could not write $SPM_AUTOUPDATE_FILE."
			printf 'Auto-update mode: %s\n' "$action"
			;;
		status)
			printf 'Auto-update mode : %s\n' "$(autoupdate_mode)"
			printf 'Check interval   : %s seconds\n' "$(autoupdate_get INTERVAL 86400)"
			printf 'Last check       : %s\n' "$(autoupdate_get LAST_CHECK never)"
			printf 'Last seen release: %s\n' "$(autoupdate_get LAST_SEEN unknown)"
			printf 'Config file      : %s\n' "$SPM_AUTOUPDATE_FILE"
			;;
		*)
			printf 'Usage: spm auto-update [status|off|notify|auto]\n' >&2
			return 2
			;;
	esac
}

cmd_update() {
	require_cmd curl
	require_cmd sha256sum
	local unzip_cmd=""
	if command -v unzip >/dev/null 2>&1; then
		unzip_cmd="unzip -q"
	elif command -v bsdtar >/dev/null 2>&1; then
		unzip_cmd="bsdtar -xf"
	fi

	if [ "$SPM_LANG" = "id" ]; then
		printf "Memeriksa update...\n"
		printf "Versi saat ini: %s\n" "$VERSION"
		printf "Repo          : %s/%s\n" "$REPO_OWNER" "$REPO_NAME"
	else
		printf "Checking for updates...\n"
		printf "Current version: %s\n" "$VERSION"
		printf "Repo           : %s/%s\n" "$REPO_OWNER" "$REPO_NAME"
	fi

	local json
	if ! json="$(curl -fsSL "$REPO_API_URL" 2>/dev/null)"; then
		if [ "$SPM_LANG" = "id" ]; then
			printf "Gagal mengakses GitHub releases API.\n"
		else
			printf "Failed to query GitHub releases API.\n"
		fi
		return 1
	fi

	local latest_tag html_url
	# The leading "v" has to come off here too: without it the comparison below
	# never matched and every run offered to reinstall the running version.
	latest_tag="$(printf '%s\n' "$json" | grep -m1 '"tag_name"' | sed -E 's/.*"tag_name": *"v?([^"]+)".*/\1/')" || true
	html_url="$(printf '%s\n' "$json" | grep -m1 '"html_url"' | sed -E 's/.*"html_url": *"([^"]+)".*/\1/')" || true

	if [ -z "$latest_tag" ]; then
		printf "Could not parse latest tag_name from GitHub response.\n"
		return 1
	fi

	if [ "$SPM_LANG" = "id" ]; then
		printf "Versi terbaru  : %s\n" "$latest_tag"
		[ -n "$html_url" ] && printf "Halaman rilis : %s\n" "$html_url"
	else
		printf "Latest version : %s\n" "$latest_tag"
		[ -n "$html_url" ] && printf "Release page   : %s\n" "$html_url"
	fi

	# Find first ZIP asset from the release payload
	local asset_url
	asset_url="$(printf '%s\n' "$json" | grep -E '"browser_download_url"' | grep -E '\.zip"' | head -n1 | sed -E 's/.*"browser_download_url": *"([^"]+)".*/\1/')" || true

	if [ -z "$asset_url" ]; then
		if [ "$SPM_LANG" = "id" ]; then
			printf "Tidak menemukan asset ZIP di rilis. Update manual diperlukan.\n"
		else
			printf "Could not find ZIP asset in release. Manual update required.\n"
		fi
		return 1
	fi

	local asset_name sha_url
	asset_name="${asset_url##*/}"
	sha_url="$(printf '%s\n' "$json" | grep -E '"browser_download_url"' | grep -F "${asset_name}.sha256\"" | head -n1 | sed -E 's/.*"browser_download_url": *"([^"]+)".*/\1/')" || true
	if [ -z "$sha_url" ]; then
		# Compatibility with the first checksum-enabled development builds,
		# which used this misleading filename for the ZIP digest.
		sha_url="$(printf '%s\n' "$json" | grep -E '"browser_download_url"' | grep -E 'spm\.sh\.sha256"' | head -n1 | sed -E 's/.*"browser_download_url": *"([^"]+)".*/\1/')" || true
	fi

	if [ -z "$sha_url" ]; then
		if [ "$SPM_LANG" = "id" ]; then
			printf "File checksum tidak ditemukan di rilis. Update manual diperlukan.\n"
		else
			printf "Checksum file not found in release. Manual update required.\n"
		fi
		return 1
	fi

	if [ "$latest_tag" = "$VERSION" ]; then
		if [ "$SPM_LANG" = "id" ]; then
			printf "\nSudah memakai versi terbaru. Reinstall? (yes/NO): "
		else
			printf "\nAlready on latest version. Reinstall anyway? (yes/NO): "
		fi
	else
		if [ "$SPM_LANG" = "id" ]; then
			printf "\nAda versi baru tersedia. Instal otomatis sekarang? (yes/NO): "
		else
			printf "\nNew version available. Auto-install now? (yes/NO): "
		fi
	fi

	local conf
	if [ "${SPM_UPDATE_ASSUME_YES:-0}" = "1" ]; then
		conf="yes"
		printf 'yes (auto-update is enabled)\n'
	else
		read -r conf || conf="no"
	fi
	if [ "$conf" != "yes" ] && [ "$conf" != "y" ]; then
		return 0
	fi

	if [ -z "$unzip_cmd" ]; then
		if [ "$SPM_LANG" = "id" ]; then
			printf "Perlu 'unzip' atau 'bsdtar' untuk mengekstrak ZIP. Instal dulu.\n"
		else
			printf "Need 'unzip' or 'bsdtar' to extract ZIP. Please install it first.\n"
		fi
		return 1
	fi

	local tmpdir
	# No predictable fallback here: "mkdir -p" succeeds on a directory somebody
	# else already owns, and the release would then be unpacked from it. Refusing
	# to self-update is the safe outcome.
	if ! tmpdir="$(mktemp -d "${TMPDIR:-/tmp}/spm_update.XXXXXX" 2>/dev/null)"; then
		printf 'Could not create a private temporary directory; update aborted.\n' >&2
		return 1
	fi
	local zip_path="$tmpdir/spm_latest.zip"
	local sha_path="$tmpdir/archive.sha256"

	if [ "$SPM_LANG" = "id" ]; then
		printf "Mengunduh: %s\n" "$asset_url"
	else
		printf "Downloading: %s\n" "$asset_url"
	fi
	if ! curl -fL "$asset_url" -o "$zip_path"; then
		if [ "$SPM_LANG" = "id" ]; then
			printf "Download gagal.\n"
		else
			printf "Download failed.\n"
		fi
		rm -rf "$tmpdir"
		return 1
	fi

	if [ "$SPM_LANG" = "id" ]; then
		printf "Mengunduh checksum: %s\n" "$sha_url"
	else
		printf "Downloading checksum: %s\n" "$sha_url"
	fi
	if ! curl -fL "$sha_url" -o "$sha_path"; then
		if [ "$SPM_LANG" = "id" ]; then
			printf "Download checksum gagal.\n"
		else
			printf "Download checksum failed.\n"
		fi
		rm -rf "$tmpdir"
		return 1
	fi

	local expected_sha
	expected_sha=$(cut -d' ' -f1 < "$sha_path")
	local actual_sha
	actual_sha=$(sha256sum "$zip_path" | cut -d' ' -f1)

	if [ "$expected_sha" != "$actual_sha" ]; then
		if [ "$SPM_LANG" = "id" ]; then
			printf "Verifikasi checksum GAGAL. File update mungkin rusak atau telah diubah.\n"
		else
			printf "Checksum verification FAILED. The update file may be corrupted or tampered with.\n"
		fi
		rm -rf "$tmpdir"
		return 1
	fi

	if [ "$SPM_LANG" = "id" ]; then
		printf "Verifikasi checksum berhasil.\n"
	else
		printf "Checksum verification successful.\n"
	fi

	local extract_dir="$tmpdir/extract"
	mkdir -p "$extract_dir"
	if [ "$unzip_cmd" = "unzip -q" ]; then
		if ! unzip -q "$zip_path" -d "$extract_dir"; then
			if [ "$SPM_LANG" = "id" ]; then
				printf "Gagal mengekstrak ZIP.\n"
			else
				printf "Failed to extract ZIP.\n"
			fi
			rm -rf "$tmpdir"
			return 1
		fi
	else
		if ! bsdtar -xf "$zip_path" -C "$extract_dir"; then
			if [ "$SPM_LANG" = "id" ]; then
				printf "Gagal mengekstrak ZIP.\n"
			else
				printf "Failed to extract ZIP.\n"
			fi
			rm -rf "$tmpdir"
			return 1
		fi
	fi

	local new_spm
	new_spm="$(find "$extract_dir" -name 'spm.sh' -type f | head -n1)"
	if [ -z "$new_spm" ]; then
		if [ "$SPM_LANG" = "id" ]; then
			printf "spm.sh tidak ditemukan di arsip.\n"
		else
			printf "spm.sh not found in archive.\n"
		fi
		rm -rf "$tmpdir"
		return 1
	fi
	if ! bash -n "$new_spm"; then
		printf "Downloaded spm.sh failed its syntax check; installation aborted.\n"
		rm -rf "$tmpdir"
		return 1
	fi

	local target="/usr/local/bin/spm"
	if [ "$SPM_LANG" = "id" ]; then
		printf "Menginstal ke %s (mungkin butuh sudo)...\n" "$target"
	else
		printf "Installing to %s (sudo may be required)...\n" "$target"
	fi

	# Never write over $target in place. Bash reads a script lazily as it runs,
	# so replacing the bytes underneath a live instance can make it execute
	# garbage -- and auto-update makes that the common case rather than a rare
	# one. Staging a sibling and renaming swaps the path atomically; anything
	# already running stays on the old inode until it exits.
	local staged="${target}.new.$$" sudo_cmd=""
	if [ ! -w "$(dirname "$target")" ] && command -v sudo >/dev/null 2>&1; then
		sudo_cmd="sudo"
	fi
	if ! $sudo_cmd cp "$new_spm" "$staged" ||
		! $sudo_cmd chmod 0755 "$staged" ||
		! $sudo_cmd mv -f "$staged" "$target"; then
		$sudo_cmd rm -f "$staged" 2>/dev/null || true
		if [ "$SPM_LANG" = "id" ]; then
			printf "Gagal memasang ke %s.\n" "$target"
		else
			printf "Failed to install to %s.\n" "$target"
		fi
		rm -rf "$tmpdir"
		return 1
	fi

	rm -rf "$tmpdir"

	if [ "$SPM_LANG" = "id" ]; then
		printf "Update selesai. Jalankan 'spm' untuk versi terbaru.\n"
	else
		printf "Update complete. Run 'spm' for the latest version.\n"
	fi
}

# ----- split recovery --------------------------------------------------------
# The recovery file and its private key must survive together, and stay secret
# together. Shares replace that pair with a threshold: any `t` of `n`
# reconstruct the vault key, any `t - 1` reveal nothing. Minting is CLI-only
# and deliberately so -- the shares ARE the vault at threshold, and printing
# them through a browser would put them in a page, a scrollback and possibly a
# proxy log on their way to the person who is supposed to write them down.

cmd_shares() {
	local action="${1:-}"
	[ "$#" -gt 0 ] && shift
	case "$action" in
		split) cmd_shares_split "$@" ;;
		combine|recover) cmd_shares_combine "$@" ;;
		status) cmd_shares_status "$@" ;;
		""|-h|--help)
			printf 'Usage: %s shares <command>\n\n' "$0"
			printf '  split [--threshold N] [--shares N]   mint a new set (default 3 of 5)\n'
			printf '  combine                              rebuild the vault key and reset the master password\n'
			printf '  status                               what set this vault records, if any\n'
			;;
		*) die "Unknown shares command: $action" ;;
	esac
}

cmd_shares_split() {
	local threshold=3 count=5
	while [ "$#" -gt 0 ]; do
		case "$1" in
			--threshold)
				[ "$#" -ge 2 ] || die "Missing value for --threshold."
				threshold="$2"; shift 2 ;;
			--shares)
				[ "$#" -ge 2 ] || die "Missing value for --shares."
				count="$2"; shift 2 ;;
			*) die "Unknown option: $1" ;;
		esac
	done
	case "$threshold$count" in
		*[!0-9]*) die "Threshold and share count must be whole numbers." ;;
	esac
	[ "$threshold" -ge 2 ] || die "A threshold below 2 is not a split."
	[ "$count" -ge "$threshold" ] || \
		die "$count shares cannot have a threshold of $threshold."
	[ "$count" -le 255 ] || die "At most 255 shares."
	[ -f "$VAULT_FILE" ] || die "Vault not found. Run '$0 init' first."

	ensure_master_password_loaded

	local existing
	existing="$(printf '%s' "$MASTER_PW" | core shares-status "$VAULT_FILE" 2>/dev/null)" || existing=""
	if [ -n "$existing" ]; then
		printf 'This vault already records a share set: %s\n' \
			"$(printf '%s' "$existing" | cut -f1)"
		printf 'Minting a new set does not revoke the old one. Any %s of the old\n' \
			"$(printf '%s' "$existing" | cut -f2)"
		printf 'shares still reconstruct this vault key, because the key does not change.\n'
		printf 'Destroy the old shares yourself. Continue? [y/N]: '
		local reply
		read -r reply || true
		case "$reply" in
			y|Y|yes|YES) ;;
			*) die "Cancelled. Nothing was changed." ;;
		esac
	fi

	local out
	out="$(printf '%s' "$MASTER_PW" | core shares-split "$VAULT_FILE" "$threshold" "$count")" \
		|| die "Failed to split the vault key. The vault was not changed."

	printf '\n'
	printf 'Split recovery: %s of %s shares\n' "$threshold" "$count"
	printf 'Set %s\n\n' "$(printf '%s\n' "$out" | sed -n '1p')"
	printf '%s\n' "$out" | sed -n '2,$p'
	printf '\n'
	printf 'These are shown once and are not stored anywhere. Write them down or\n'
	printf 'save them now, then keep them apart -- any %s together open this vault\n' "$threshold"
	printf 'without the master password, and any fewer than %s reveal nothing at all.\n' \
		"$threshold"
	printf 'They stay valid after a master-password change.\n'
}

cmd_shares_status() {
	[ -f "$VAULT_FILE" ] || die "Vault not found. Run '$0 init' first."
	ensure_master_password_loaded
	local out
	out="$(printf '%s' "$MASTER_PW" | core shares-status "$VAULT_FILE")" \
		|| die "Failed to read the vault."
	if [ -z "$out" ]; then
		printf 'This vault records no share set. Run "%s shares split" to mint one.\n' "$0"
		return
	fi
	printf 'Set       : %s\n' "$(printf '%s' "$out" | cut -f1)"
	printf 'Threshold : %s of %s\n' "$(printf '%s' "$out" | cut -f2)" \
		"$(printf '%s' "$out" | cut -f3)"
	printf 'Minted    : %s\n' "$(printf '%s' "$out" | cut -f4)"
	printf '\nThe vault records that this set exists. It does not hold any share,\n'
	printf 'so it cannot tell you whether you still have enough of them.\n'
}

cmd_shares_combine() {
	[ -f "$VAULT_FILE" ] || die "Vault not found at '$VAULT_FILE'. Nothing to recover."

	printf '>>> SPLIT RECOVERY <<<\n\n'
	printf 'Enter one share per line. Blank line when done.\n\n'

	local collected line
	collected="$(make_tmp)"
	while :; do
		printf 'share: '
		read -r line || break
		[ -n "$line" ] || break
		printf '%s\n' "$line" >> "$collected"
	done

	[ -s "$collected" ] || { secure_wipe "$collected"; die "No shares were given."; }

	# The core proves the reconstruction by opening the vault with it, so a
	# wrong or mixed set fails here rather than after a master password has
	# been set against a key that opens nothing.
	local recovered
	if ! recovered="$(core shares-combine "$VAULT_FILE" < "$collected" 2>&1)"; then
		secure_wipe "$collected"
		die "$recovered"
	fi
	secure_wipe "$collected"

	VAULT_KEY="$recovered"
	printf '\nThe shares reconstructed this vault key and it opens the vault.\n'
	printf 'Now set a NEW master password.\n\n'
	prompt_master_password
	rewrap_vault_key "$MASTER_PW"
	printf '\nMaster password has been RESET.\n'
	printf 'Your shares remain valid: a password change does not change the vault key.\n'
}

cmd_forgot() {
	[ -f "$VAULT_FILE" ] || die "Vault not found at '$VAULT_FILE'. Nothing to recover."
	[ -f "$RECOVERY_FILE" ] || die "Recovery file '$RECOVERY_FILE' not found. Forgot-mode unavailable."
	require_cmd openssl

	if [ "$SPM_LANG" = "id" ]; then
		printf ">>> LUPA KATA SANDI UTAMA (MODE PEMULIHAN) <<<\n\n"
		printf "Kamu butuh PRIVATE KEY RSA yang dibuat saat 'init'.\n"
		printf "Lokasi default private key (jika belum dipindah): %s\n\n" "$RECOVERY_PRIV_DEFAULT"
		printf "Masukkan path private key (kosong = default): "
	else
		printf ">>> FORGOT MASTER PASSWORD (RECOVERY MODE) <<<\n\n"
		printf "You will need your RSA PRIVATE KEY that was generated on 'init'.\n"
		printf "Default private key path (if not moved): %s\n\n" "$RECOVERY_PRIV_DEFAULT"
		printf "Enter private key path (blank = default): "
	fi
	read -r pk_path || true
	if [ -z "$pk_path" ]; then
		pk_path="$RECOVERY_PRIV_DEFAULT"
	fi

	[ -f "$pk_path" ] || die "Private key file '$pk_path' not found."

	local recovered_secret
	if ! recovered_secret="$(openssl rsautl -decrypt -inkey "$pk_path" -in "$RECOVERY_FILE" 2>/dev/null)"; then
		die "Failed to decrypt recovery file with the provided private key."
	fi

	# What the recovery file holds depends on when it was last written:
	# format 3 stores the vault key, the formats before it stored the master
	# password, and a vault caught mid-migration is described by neither. Try
	# every reading rather than assume -- the master-password route is also
	# what makes the migration crash window recoverable.
	local tmp recovery_stale=0
	tmp="$(make_tmp)"
	VAULT_KEY=""
	# The core decides what the recovered secret actually is: format 3 stores
	# the vault key, the formats before it stored the master password, and a
	# vault caught mid-migration is described by neither. It reports back
	# whether the recovery file is stale and therefore needs repairing below.
	local recover_out
	recover_out="$(printf '%s' "$recovered_secret" | core recover "$VAULT_FILE" "$tmp")" \
		|| { secure_wipe "$tmp"; die "The recovery file does not open this vault. Recovery aborted."; }
	VAULT_KEY="$(printf '%s\n' "$recover_out" | sed -n '1p')"
	recovery_stale="$(printf '%s\n' "$recover_out" | sed -n '2p')"
	[ "$recovery_stale" = "1" ] || recovery_stale=0
	if [ -z "$VAULT_KEY" ]; then
		# A legacy vault: the recovered secret is its master password.
		MASTER_PW="$recovered_secret"
	fi

	if [ "$SPM_LANG" = "id" ]; then
		printf "\nVault berhasil didekripsi menggunakan kata sandi utama lama.\n"
		printf "Sekarang set kata sandi utama BARU.\n\n"
	else
		printf "\nVault successfully decrypted using recovered master password.\n"
		printf "Now set a NEW master password for this vault.\n\n"
	fi

	# Same two-step as change-master: migrate a legacy vault under the password
	# the recovery file already names, then rewrap to the new one.
	if [ -z "${VAULT_KEY:-}" ]; then
		encrypt_file_to_vault "$tmp"
		recovery_stale=0
	fi
	prompt_master_password
	rewrap_vault_key "$MASTER_PW"
	# Finish the migration this vault was caught in the middle of. Without
	# this the vault would open under the new password while its recovery file
	# still named the old one -- recoverable once, by luck, and never again.
	if [ "$recovery_stale" -eq 1 ]; then
		write_recovery_file "$tmp"
	fi
	secure_wipe "$tmp"

	if [ "$SPM_LANG" = "id" ]; then
		printf "\nKata sandi utama berhasil DI-RESET.\n"
		printf "File pemulihan tetap berlaku: %s\n" "$RECOVERY_FILE"
		printf "Simpan baik-baik private key dan file recovery.\n"
	else
		printf "\nMaster password has been RESET.\n"
		# The recovery file wraps the vault key, which a password reset does
		# not change. Saying it was "updated" would invite the user to re-copy
		# a file that is byte-identical to the one they already keep offline.
		printf "Recovery file remains valid at: %s\n" "$RECOVERY_FILE"
		printf "Keep your private key and this recovery file safe.\n"
	fi
}

# Report vault records that contain a character Python's splitlines() treats as
# a line break. Such a record was written as one line but is read back as two,
# so neither half has enough fields and the entry disappears from the SPM Dashboard.
# 2.10.12 stopped new ones being created; this finds any that already exist.
# Strictly read-only: it reports and never edits the vault.
doctor_scan_broken_records() {
	# One implementation, in the core. This used to carry its own copy of the
	# break table and the record describer, which is exactly the arrangement
	# the trusted-core split exists to prevent -- the JSON report needs the
	# same scan, and two copies of it would drift the way the old dashboard
	# and CLI copies did.
	core scan-records "$1"
}
# Which of the recovery states this vault is in, as a single token. The human
# doctor prints these as sentences further down; the JSON report needs the same
# determination without the prose, and neither should decide it twice.
doctor_recovery_state() {
	[ -f "$RECOVERY_FILE" ] || { printf 'no-recovery-file'; return 0; }
	[ -f "$RECOVERY_PRIV_DEFAULT" ] || { printf 'no-private-key'; return 0; }
	local secret
	if secret="$(openssl rsautl -decrypt -inkey "$RECOVERY_PRIV_DEFAULT" \
			-in "$RECOVERY_FILE" 2>/dev/null)"; then
		if is_vault_container "$VAULT_FILE"; then
			if [ -n "${VAULT_KEY:-}" ] && [ "$secret" = "$VAULT_KEY" ]; then
				printf 'match-current'
			else
				printf 'match-stale'
			fi
		else
			printf 'match-legacy'
		fi
	else
		printf 'mismatch'
	fi
	secret=""
}

# `doctor --json`. Everything a script needs, nothing a human needs: no
# progress lines, no banner, and stdout carries the document and nothing else
# so it can be piped straight into jq. Exit status mirrors the report, so a
# caller can gate on it without parsing.
cmd_doctor_json() {
	[ -f "$VAULT_FILE" ] || die "Vault not found. Run '$0 init' first."
	local tmp state status
	tmp="$(make_tmp)"
	decrypt_vault_to_file "$tmp"
	state="$(doctor_recovery_state)"
	status=0
	# shellcheck disable=SC2046
	core doctor-report "$tmp" "$VAULT_FILE" "$state" $(sensitive_files) || status=$?
	secure_wipe "$tmp"
	return "$status"
}

cmd_events() {
	local as_json=0 limit=50
	while [ "$#" -gt 0 ]; do
		case "$1" in
			--json) as_json=1; shift ;;
			--all) limit=0; shift ;;
			--limit)
				[ "$#" -ge 2 ] || die "Missing value for --limit."
				limit="$2"; shift 2 ;;
			*) die "Unknown option for events: $1" ;;
		esac
	done
	printf '%s' "$limit" | grep -Eq '^[0-9]+$' || die "--limit takes a number."
	if [ "$as_json" -eq 1 ]; then
		core events "$VAULT_FILE" "$limit"
		return
	fi
	local path
	path="$(core events-path "$VAULT_FILE")"
	if [ ! -f "$path" ]; then
		printf 'No security events recorded yet.\n'
		printf 'They will appear at %s\n' "$path"
		return
	fi
	printf '%-22s %-8s %-8s %s\n' 'WHEN (UTC)' 'EVENT' 'OUTCOME' 'DETAIL'
	core events "$VAULT_FILE" "$limit" | python3 -c '
import json, sys
for event in json.load(sys.stdin)["events"]:
    detail = ", ".join("%s=%s" % pair for pair in sorted(event["detail"].items()))
    print("%-22s %-8s %-8s %s" % (event["when"], event["kind"],
                                  event["outcome"], detail))
'
	printf '\nLog: %s\n' "$path"
}

cmd_doctor() {
	if [ "${1:-}" = "--json" ]; then
		cmd_doctor_json
		return $?
	fi
	if [ "$SPM_LANG" = "id" ]; then
		printf ">>> HEALTH / DOCTOR CHECK <<<\n\n"
	else
		printf ">>> HEALTH / DOCTOR CHECK <<<\n\n"
	fi

	if [ ! -f "$VAULT_FILE" ]; then
		if [ "$SPM_LANG" = "id" ]; then
			printf "[✖] Vault tidak ditemukan di: %s\n" "$VAULT_FILE"
		else
			printf "[✖] Vault not found at: %s\n" "$VAULT_FILE"
		fi
		return 1
	fi

	if [ "$SPM_LANG" = "id" ]; then
		printf "[ ] Dekripsi vault...\n"
	else
		printf "[ ] Decrypting vault...\n"
	fi

	local tmp
	tmp="$(make_tmp)"
	decrypt_vault_to_file "$tmp"

	if [ "$SPM_LANG" = "id" ]; then
		printf "\r[✔] Dekripsi vault berhasil.\n"
	else
		printf "\r[✔] Vault decrypted successfully.\n"
	fi

	# Check password rows & duplicates
	local pw_count
	pw_count="$(awk -F '\t' '
		$1 ~ /^[0-9]+$/ { c++; if (length($4)==0) ep++; ids[$1]++ }
		END {
			for (i in ids) if (ids[i]>1) {dup=1}
			if (dup) print c+0 "|" ep+0 "|dup";
			else print c+0 "|" ep+0 "|ok";
		}
	' "$tmp")"

	local pw_total empty_pw status_dup
	pw_total="${pw_count%%|*}"
	local rest="${pw_count#*|}"
	empty_pw="${rest%%|*}"
	status_dup="${rest##*|}"

	# The marker has to be chosen after the result is known: this is a verdict
	# line, not a progress line, so it must not keep the empty "[ ]" that the
	# in-progress steps use.
	local dup_mark
	if [ "$status_dup" = "dup" ]; then
		dup_mark="[!]"
	else
		dup_mark="[✔]"
	fi

	if [ "$SPM_LANG" = "id" ]; then
		printf "[✔] Jumlah entry password : %s\n" "$pw_total"
		printf "%s Duplikasi ID          : " "$dup_mark"
	else
		printf "[✔] Password entries count: %s\n" "$pw_total"
		printf "%s Duplicate IDs         : " "$dup_mark"
	fi

	if [ "$status_dup" = "dup" ]; then
		if [ "$SPM_LANG" = "id" ]; then
			printf "ADA\n"
		else
			printf "FOUND\n"
		fi
	else
		if [ "$SPM_LANG" = "id" ]; then
			printf "tidak ada\n"
		else
			printf "none\n"
		fi
	fi

	if [ "$empty_pw" != "0" ]; then
		if [ "$SPM_LANG" = "id" ]; then
			printf "[!] Peringatan: %s entry dengan password kosong.\n" "$empty_pw"
		else
			printf "[!] Warning: %s entries with EMPTY password field.\n" "$empty_pw"
		fi
	else
		if [ "$SPM_LANG" = "id" ]; then
			printf "[✔] Tidak ada entry dengan password kosong.\n"
		else
			printf "[✔] No entries with empty password.\n"
		fi
	fi

	# Check notes rows
	local note_count
	note_count="$(awk -F '\t' '$1=="NOTE"{n++} END{print n+0}' "$tmp")"
	if [ "$SPM_LANG" = "id" ]; then
		printf "[✔] Jumlah catatan aman    : %s\n" "$note_count"
	else
		printf "[✔] Secure notes count     : %s\n" "$note_count"
	fi

	local pass_count
	pass_count="$(awk -F '\t' '$1=="PASSPHRASE"{n++} END{print n+0}' "$tmp")"
	if [ "$SPM_LANG" = "id" ]; then
		printf "[✔] Jumlah passphrase      : %s\n" "$pass_count"
	else
		printf "[✔] Passphrases count      : %s\n" "$pass_count"
	fi

	local bc_count
	bc_count="$(awk -F '\t' '$1=="BACKUP_CODE"{n++} END{print n+0}' "$tmp")"
	if [ "$SPM_LANG" = "id" ]; then
		printf "[✔] Jumlah kode backup     : %s\n" "$bc_count"
	else
		printf "[✔] Backup codes count     : %s\n" "$bc_count"
	fi

	local auth_count
	auth_count="$(awk -F '\t' '$1=="AUTH"{n++} END{print n+0}' "$tmp")"
	if [ "$SPM_LANG" = "id" ]; then
		printf "[✔] Jumlah authenticator   : %s\n" "$auth_count"
	else
		printf "[✔] Authenticators count   : %s\n" "$auth_count"
	fi

	# Records split by a stray line-break character (see 2.10.12).
	local scan_out scan_summary broken_count orphan_count
	if scan_out="$(doctor_scan_broken_records "$tmp" 2>/dev/null)"; then
		scan_summary="$(printf '%s\n' "$scan_out" | awk -F '\t' '$1=="SUMMARY"{print $2"|"$3}')"
		broken_count="${scan_summary%%|*}"
		orphan_count="${scan_summary##*|}"
		if [ "${broken_count:-0}" = "0" ] && [ "${orphan_count:-0}" = "0" ]; then
			if [ "$SPM_LANG" = "id" ]; then
				printf "[✔] Tidak ada record yang terpotong.\n"
			else
				printf "[✔] No records split by a line-break character.\n"
			fi
		else
			if [ "$SPM_LANG" = "id" ]; then
				printf "[!] %s record berisi karakter pemisah baris, %s pecahan tersisa:\n" \
					"$broken_count" "$orphan_count"
			else
				printf "[!] %s record(s) contain a line-break character; %s leftover fragment(s):\n" \
					"$broken_count" "$orphan_count"
			fi
			printf '%s\n' "$scan_out" | awk -F '\t' '
				$1=="BROKEN" { printf "      line %-5s %-13s id=%-5s %-34s %s\n", $2, $3, $4, $5, $6 }
				$1=="ORPHAN" { printf "      line %-5s %-13s %s\n", $2, "FRAGMENT", $3 }
			'
			if [ "$SPM_LANG" = "id" ]; then
				printf "    Entry ini tidak terlihat di SPM Dashboard. Vault TIDAK diubah.\n"
				printf "    Perbaiki dengan menyimpan ulang tiap entry lewat CLI (spm edit <id>).\n"
			else
				printf "    These entries are invisible in the SPM Dashboard. The vault was NOT changed.\n"
				printf "    Repair by re-saving each one from the CLI (spm edit <id>), which\n"
				printf "    rewrites the field through the 2.10.12 sanitiser.\n"
			fi
		fi
	else
		if [ "$SPM_LANG" = "id" ]; then
			printf "[!] Pemindaian record terpotong gagal dijalankan.\n"
		else
			printf "[!] Split-record scan could not be run.\n"
		fi
	fi

	# Report the vault format version, and whether the next write upgrades it.
	# Stated rather than acted on: doctor is a diagnostic and must never be the
	# thing that rewrites a vault.
	local fmt
	fmt="$(vault_format_version "$tmp")"
	local current_fmt
	current_fmt="$(core current-version 2>/dev/null || printf '%s' "$fmt")"
	if [ "$fmt" -ge "$current_fmt" ]; then
		if [ "$SPM_LANG" = "id" ]; then
			printf "[✔] Format vault versi %s (terbaru).\n" "$fmt"
		else
			printf "[✔] Vault format version %s (current).\n" "$fmt"
		fi
	else
		if [ "$SPM_LANG" = "id" ]; then
			printf "[!] Format vault versi %s; versi %s tersedia.\n" "$fmt" "$current_fmt"
			printf "    Perubahan berikutnya akan memutakhirkan vault otomatis.\n"
			printf "    Kunci diturunkan memakai default GnuPG lama (digest SHA1).\n"
		else
			printf "[!] Vault format version %s; version %s is available.\n" "$fmt" "$current_fmt"
			printf "    The next change upgrades this vault in place; no migration step.\n"
			printf "    Its key was derived with GnuPG's older default digest (SHA1).\n"
		fi
	fi

	# Report what actually seals the file, which is not the same question as
	# which format the records are in -- a vault upgraded to format 4 by a
	# release before 4.0.0 is still gpg-sealed until its next write.
	local seal_info seal_backend seal_kdf seal_n seal_r seal_p
	seal_info="$(core seal-info "$VAULT_FILE" 2>/dev/null || true)"
	seal_backend="$(printf '%s' "$seal_info" | cut -f1)"
	seal_kdf="$(printf '%s' "$seal_info" | cut -f2)"
	seal_n="$(printf '%s' "$seal_info" | cut -f3)"
	seal_r="$(printf '%s' "$seal_info" | cut -f4)"
	seal_p="$(printf '%s' "$seal_info" | cut -f5)"
	case "$seal_backend" in
	openssl)
		if [ "$SPM_LANG" = "id" ]; then
			printf "[✔] Vault disegel dengan AES-256-CTR + HMAC-SHA256.\n"
			printf "    Derivasi kunci %s n=%s r=%s p=%s.\n" \
				"$seal_kdf" "$seal_n" "$seal_r" "$seal_p"
		else
			printf "[✔] Vault sealed with AES-256-CTR and HMAC-SHA256.\n"
			printf "    Key derivation %s n=%s r=%s p=%s.\n" \
				"$seal_kdf" "$seal_n" "$seal_r" "$seal_p"
		fi
		;;
	gpg|legacy)
		if [ "$SPM_LANG" = "id" ]; then
			printf "[!] Vault masih disegel GnuPG dan belum terautentikasi.\n"
			printf "    Perubahan berikutnya memutakhirkannya; kunci vault tidak berubah.\n"
		else
			printf "[!] Vault is still gpg-sealed, and therefore unauthenticated.\n"
			printf "    The next change upgrades it in place; the vault key does not change.\n"
		fi
		;;
	esac

	# Check recovery meta public key
	local pub_b64
	pub_b64="$(get_recovery_pub_b64_from_vault "$tmp")"
	if [ -z "$pub_b64" ]; then
		if [ "$SPM_LANG" = "id" ]; then
			printf "[✖] Baris META_RECOVERY_PUBKEY tidak ditemukan di vault.\n"
		else
			printf "[✖] META_RECOVERY_PUBKEY row not found in vault.\n"
		fi
	else
		local tmp_pub
		tmp_pub="$(make_tmp)"
		if printf '%s' "$pub_b64" | base64 -d >"$tmp_pub" 2>/dev/null; then
			if openssl rsa -pubin -in "$tmp_pub" -text -noout >/dev/null 2>&1; then
				if [ "$SPM_LANG" = "id" ]; then
					printf "[✔] Public key pemulihan valid dan bisa dibaca.\n"
				else
					printf "[✔] Recovery public key is valid and readable.\n"
				fi
			else
				if [ "$SPM_LANG" = "id" ]; then
					printf "[✖] Public key pemulihan ada, tapi tidak valid.\n"
				else
					printf "[✖] Recovery public key present but not valid.\n"
				fi
			fi
		else
			if [ "$SPM_LANG" = "id" ]; then
				printf "[✖] Gagal decode base64 public key pemulihan.\n"
			else
				printf "[✖] Failed to base64-decode recovery public key.\n"
			fi
		fi
		secure_wipe "$tmp_pub"
	fi

	# Check recovery file + private key
	if [ -f "$RECOVERY_FILE" ]; then
		if [ "$SPM_LANG" = "id" ]; then
			printf "[✔] File recovery ditemukan: %s\n" "$RECOVERY_FILE"
		else
			printf "[✔] Recovery file found    : %s\n" "$RECOVERY_FILE"
		fi

		if [ -f "$RECOVERY_PRIV_DEFAULT" ]; then
			if [ "$SPM_LANG" = "id" ]; then
				printf "[ ] Menguji pasangan PRIVATE KEY + recovery file...\n"
			else
				printf "[ ] Testing PRIVATE KEY + recovery file pair...\n"
			fi
			local recovered_secret=""
			if recovered_secret="$(openssl rsautl -decrypt -inkey "$RECOVERY_PRIV_DEFAULT" -in "$RECOVERY_FILE" 2>/dev/null)"; then
				if [ "$SPM_LANG" = "id" ]; then
					printf "[✔] Private key dan file recovery cocok.\n"
				else
					printf "[✔] Private key and recovery file match.\n"
				fi
				# Holding a decryptable recovery file is not the same as
				# holding a USEFUL one. Since 3.0.0 it must contain the vault
				# key; one still holding a master password recovers a vault
				# only until the next password change, and nothing else in the
				# tool can tell the user which of the two they have.
				if is_vault_container "$VAULT_FILE"; then
					if [ -n "${VAULT_KEY:-}" ] && [ "$recovered_secret" = "$VAULT_KEY" ]; then
						if [ "$SPM_LANG" = "id" ]; then
							printf "[✔] File recovery berisi kunci vault saat ini.\n"
						else
							printf "[✔] Recovery file holds the current vault key.\n"
						fi
					else
						if [ "$SPM_LANG" = "id" ]; then
							printf "[✖] File recovery tidak berisi kunci vault ini; jalankan '%s change-master' untuk memperbaruinya.\n" "$0"
						else
							printf "[✖] Recovery file does not hold this vault's key; run '%s change-master' to refresh it.\n" "$0"
						fi
					fi
				fi
				recovered_secret=""
			else
				if [ "$SPM_LANG" = "id" ]; then
					printf "[✖] Private key tidak cocok dengan file recovery.\n"
				else
					printf "[✖] Private key does NOT match the recovery file.\n"
				fi
			fi
		else
			if [ "$SPM_LANG" = "id" ]; then
				printf "[✖] PRIVATE KEY default tidak ditemukan di: %s\n" "$RECOVERY_PRIV_DEFAULT"
			else
				printf "[✖] Default PRIVATE KEY not found at: %s\n" "$RECOVERY_PRIV_DEFAULT"
			fi
		fi
	else
		if [ "$SPM_LANG" = "id" ]; then
			printf "[✖] File recovery tidak ditemukan di: %s\n" "$RECOVERY_FILE"
		else
			printf "[✖] Recovery file not found at: %s\n" "$RECOVERY_FILE"
		fi
	fi

	# Check on-disk permissions of the sensitive files. A vault last written by
	# a web session before 2.9.1 kept the umask default (usually 0644) instead
	# of 0600, and that stays wrong until someone fixes it by hand.
	if [ "$SPM_LANG" = "id" ]; then
		printf "\n[ ] Memeriksa izin file sensitif...\n"
	else
		printf "\n[ ] Checking sensitive file permissions...\n"
	fi

	local perm_bad=0
	local perm_fix=""
	local pf pmode
	# Here-string, not a pipe: a piped 'while' runs in a subshell and would
	# discard perm_bad/perm_fix.
	while IFS= read -r pf; do
		[ -n "$pf" ] || continue
		pmode="$(file_mode "$pf")"
		if [ -z "$pmode" ]; then
			if [ "$SPM_LANG" = "id" ]; then
				printf "[!] Tidak bisa membaca izin: %s\n" "$pf"
			else
				printf "[!] Could not read permissions: %s\n" "$pf"
			fi
			continue
		fi
		if mode_is_exposed "$pmode"; then
			perm_bad=$((perm_bad + 1))
			perm_fix="${perm_fix}$(printf '%q' "$pf") "
			if [ "$SPM_LANG" = "id" ]; then
				printf "[✖] %s terbuka untuk pengguna lain (mode %s, seharusnya 600).\n" "$pf" "$pmode"
			else
				printf "[✖] %s is readable by other users (mode %s, expected 600).\n" "$pf" "$pmode"
			fi
		else
			if [ "$SPM_LANG" = "id" ]; then
				printf "[✔] Izin aman (%s): %s\n" "$pmode" "$pf"
			else
				printf "[✔] Permissions OK (%s): %s\n" "$pmode" "$pf"
			fi
		fi
	done <<<"$(sensitive_files)"

	if [ "$perm_bad" -gt 0 ]; then
		if [ "$SPM_LANG" = "id" ]; then
			printf "[!] Perbaiki dengan: chmod 600 %s\n" "${perm_fix% }"
		else
			printf "[!] Fix with: chmod 600 %s\n" "${perm_fix% }"
		fi
	fi

	secure_wipe "$tmp"

	if [ "$SPM_LANG" = "id" ]; then
		printf "\n[DOCTOR] Pemeriksaan selesai.\n"
	else
		printf "\n[DOCTOR] Health check finished.\n"
	fi
}

# Previous passwords for one record, oldest first.
#
# Named password-history rather than folded into history-list because that
# command restores whole vault generations: overloading it would put a
# destructive operation one ambiguous argument away from a read-only one.
cmd_password_history() {
	local id="${1:-}"
	[ -n "$id" ] || die "Usage: $0 password-history <record id>"
	printf '%s' "$id" | grep -Eq '^[0-9]+$' || die "Numeric record ID required."
	[ -f "$VAULT_FILE" ] || die "Vault not found. Run '$0 init' first."

	local tmp
	tmp="$(make_tmp)"
	decrypt_vault_to_file "$tmp"

	local label
	label="$(awk -F '\t' -v want="$id" '$1==want {print $2; exit}' "$tmp")"
	if [ -z "$label" ]; then
		secure_wipe "$tmp"
		die "No entry with ID $id."
	fi

	local rows
	rows="$(core password-history "$tmp" "$id" 2>/dev/null || true)"
	if [ -z "$rows" ]; then
		if [ "$SPM_LANG" = "id" ]; then
			printf 'Belum ada kata sandi sebelumnya untuk %s (ID %s).\n' "$label" "$id"
		else
			printf 'No previous passwords recorded for %s (ID %s).\n' "$label" "$id"
		fi
		secure_wipe "$tmp"
		return 0
	fi

	if [ "$SPM_LANG" = "id" ]; then
		printf 'Kata sandi sebelumnya untuk %s (ID %s), terlama dulu:\n\n' "$label" "$id"
	else
		printf 'Previous passwords for %s (ID %s), oldest first:\n\n' "$label" "$id"
	fi
	printf '%s\n' "$rows" | awk -F '\t' '{ printf "  %d. %s  %s\n", NR, $1, $2 }'
	printf '\n'
	if [ "$SPM_LANG" = "id" ]; then
		printf 'Kata sandi saat ini tidak ditampilkan di sini; gunakan "%s get %s".\n' "$0" "$id"
	else
		printf 'The current password is not shown here; use "%s get %s".\n' "$0" "$id"
	fi
	secure_wipe "$tmp"
}

cmd_export() {
	[ -f "$VAULT_FILE" ] || die "Vault not found. Run '$0 init' first."
	require_cmd python3

	local format="${1:-csv}"
	format="$(printf '%s' "$format" | tr '[:upper:]' '[:lower:]')"
	local outfile="${2:-}"
	case "$format" in
		csv|json|tsv|ndjson|jsonl|md|markdown|html|txt|yaml|yml|xml|sql|ini|psv|rst|toml|org|scsv|csv-noheader|jsonc) ;;
		*) die "Unsupported format '$format'. Use: csv, json, tsv, ndjson/jsonl, md, html, txt, yaml/yml, xml, sql, ini, psv, rst, toml, org, scsv, csv-noheader, or jsonc." ;;
	esac

	if [ -z "$outfile" ]; then
		outfile="spm_export_$(date +%Y%m%d_%H%M%S).${format}"
	else
		case "$outfile" in
			*."$format") ;;  # already has correct extension
			*.csv|*.json|*.tsv|*.ndjson|*.jsonl|*.md|*.markdown|*.html|*.htm|*.txt|*.yaml|*.yml|*.xml|*.sql|*.ini|*.psv|*.rst|*.toml|*.org) ;;
			md|markdown) outfile="export.md" ;;
			html|htm) outfile="export.html" ;;
			txt) outfile="export.txt" ;;
			yaml|yml) outfile="export.yaml" ;;
			xml) outfile="export.xml" ;;
			sql) outfile="export.sql" ;;
			ini) outfile="export.ini" ;;
			psv) outfile="export.psv" ;;
			scsv) outfile="export.scsv" ;;
			toml) outfile="export.toml" ;;
			org) outfile="export.org" ;;
			"csv-noheader") outfile="export.csv" ;;
			jsonc) outfile="export.json" ;;
			rst) outfile="export.rst" ;;
			*) outfile="${outfile}.${format}" ;;
		esac
	fi

	local tmp
	tmp="$(make_tmp)"
	decrypt_vault_to_file "$tmp"

if ! python3 - "$format" "$tmp" "$outfile" "$(core_script_path)" <<'PY'
import sys, json, base64, csv, html, datetime, importlib.util
fmt, vault_path, out_path, core_path = sys.argv[1:]

# The folder and custom fields cross an export as their own columns, and the
# encoding of that column is the core's business, not this script's.
_spec = importlib.util.spec_from_file_location("spm_core_export", core_path)
core = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(core)

def decode_b64(val):
    try:
        return base64.b64decode(val.encode("utf-8")).decode("utf-8", errors="replace")
    except Exception:
        return ""

rows = []
with open(vault_path, "r", encoding="utf-8", errors="ignore") as f:
    for line in f:
        line = line.rstrip("\n")
        if not line or line.startswith("#"):
            continue
        parts = line.split("\t")
        tag = parts[0]
        if tag.isdigit():  # password
            rows.append({
                "type": "password",
                "id": parts[0],
                "label": parts[1] if len(parts) > 1 else "",
                "username": parts[2] if len(parts) > 2 else "",
                "secret": parts[3] if len(parts) > 3 else "",
                "notes": parts[4] if len(parts) > 4 else "",
                "created": parts[5] if len(parts) > 5 else "",
                "extra": "",
                "url": parts[6] if len(parts) > 6 else "",
                **core.attrs_export_columns(parts[7] if len(parts) > 7 else "")
            })
        elif tag == "NOTE":
            rows.append({
                "type": "note",
                "id": parts[1] if len(parts) > 1 else "",
                "label": parts[2] if len(parts) > 2 else "",
                "username": "",
                "secret": decode_b64(parts[3]) if len(parts) > 3 else "",
                "notes": "",
                "created": parts[4] if len(parts) > 4 else "",
                "extra": "",
                "url": ""
            })
        elif tag == "PASSPHRASE":
            rows.append({
                "type": "passphrase",
                "id": parts[1] if len(parts) > 1 else "",
                "label": parts[2] if len(parts) > 2 else "",
                "username": "",
                "secret": decode_b64(parts[3]) if len(parts) > 3 else "",
                "notes": "",
                "created": parts[4] if len(parts) > 4 else "",
                "extra": "",
                "url": ""
            })
        elif tag == "BACKUP_CODE":
            rows.append({
                "type": "backup_code",
                "id": parts[1] if len(parts) > 1 else "",
                "label": parts[2] if len(parts) > 2 else "",
                "username": "",
                "secret": decode_b64(parts[3]) if len(parts) > 3 else "",
                "notes": "",
                "created": parts[4] if len(parts) > 4 else "",
                "extra": "",
                "url": ""
            })
        elif tag == "AUTH":
            rows.append({
                "type": "authenticator",
                "id": parts[1] if len(parts) > 1 else "",
                "label": parts[2] if len(parts) > 2 else "",
                "username": "",
                "secret": parts[3] if len(parts) > 3 else "",
                "notes": "",
                "created": parts[5] if len(parts) > 5 else "",
                "extra": "period=%s;algo=%s" % (
                    parts[4] if len(parts) > 4 else "",
                    parts[6] if len(parts) > 6 else "sha1"
                ),
                "url": ""
            })

fieldnames = list(core.EXPORT_FIELDNAMES)

if fmt == "json":
    with open(out_path, "w", encoding="utf-8") as f:
        json.dump(rows, f, ensure_ascii=False, indent=2)
elif fmt in ("ndjson", "jsonl"):
    with open(out_path, "w", encoding="utf-8") as f:
        for row in rows:
            f.write(json.dumps(row, ensure_ascii=False) + "\n")
elif fmt == "tsv":
    with open(out_path, "w", encoding="utf-8", newline="") as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames, delimiter="\t")
        writer.writeheader()
        writer.writerows(rows)
elif fmt in ("md", "markdown"):
    with open(out_path, "w", encoding="utf-8") as f:
        f.write("| " + " | ".join(fieldnames) + " |\n")
        f.write("|" + "|".join([" --- "]*len(fieldnames)) + "|\n")
        for r in rows:
            cells = [json.dumps(str(r.get(k,"") or ""), ensure_ascii=False).replace("|", "\\u007c") for k in fieldnames]
            f.write("| " + " | ".join(cells) + " |\n")
elif fmt == "html":
    with open(out_path, "w", encoding="utf-8") as f:
        f.write("<table border='1' cellpadding='4' cellspacing='0'>\n")
        f.write("<tr>" + "".join(f"<th>{html.escape(k)}</th>" for k in fieldnames) + "</tr>\n")
        for r in rows:
            f.write("<tr>" + "".join(f"<td>{html.escape((r.get(k,'') or ''))}</td>" for k in fieldnames) + "</tr>\n")
        f.write("</table>\n")
elif fmt == "toml":
    with open(out_path, "w", encoding="utf-8") as f:
        for r in rows:
            f.write("[[item]]\n")
            for k in fieldnames:
                val = (r.get(k, "") or "").replace("\\", "\\\\").replace("\n", "\\n").replace('"', '\\"')
                f.write(f'{k} = "{val}"\n')
            f.write("\n")
elif fmt == "org":
    header = "| " + " | ".join(fieldnames) + " |\n"
    sep = "|" + "+".join("-" * (len(k)+2) for k in fieldnames) + "|\n"
    with open(out_path, "w", encoding="utf-8") as f:
        f.write(header)
        f.write(sep)
        for r in rows:
            cells = [json.dumps(str(r.get(k,"") or ""), ensure_ascii=False).replace("|", "\\u007c") for k in fieldnames]
            f.write("| " + " | ".join(cells) + " |\n")
elif fmt == "scsv":
    with open(out_path, "w", encoding="utf-8", newline="") as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames, delimiter=";")
        writer.writeheader()
        writer.writerows(rows)
elif fmt == "csv-noheader":
    with open(out_path, "w", encoding="utf-8", newline="") as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames, delimiter=",")
        writer.writerows(rows)
elif fmt == "jsonc":
    with open(out_path, "w", encoding="utf-8") as f:
        json.dump(rows, f, ensure_ascii=False)
elif fmt in ("yaml", "yml"):
    with open(out_path, "w", encoding="utf-8") as f:
        for r in rows:
            f.write("-\n")
            for k in fieldnames:
                val = r.get(k, "") or ""
                f.write(f"  {k}: {json.dumps(val, ensure_ascii=False)}\n")
elif fmt == "xml":
    with open(out_path, "w", encoding="utf-8") as f:
        f.write("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<data>\n")
        for r in rows:
            f.write("  <item>\n")
            for k in fieldnames:
                val = html.escape(r.get(k, "") or "")
                f.write(f"    <{k}>{val}</{k}>\n")
            f.write("  </item>\n")
        f.write("</data>\n")
elif fmt == "sql":
    with open(out_path, "w", encoding="utf-8") as f:
        # Built from fieldnames rather than written out, because the two drifted:
        # the column list stopped at `extra` while the row already carried `url`,
        # so every INSERT this produced said "9 values for 8 columns" and sqlite
        # refused the whole file. SPM's own reader parses the tuple positionally
        # and never noticed -- the round trip agreed with itself while emitting
        # SQL no other tool would load.
        f.write("CREATE TABLE spm_export(%s);\n"
                % ",".join("%s TEXT" % name for name in fieldnames))
        for r in rows:
            vals = [r.get(k, "") or "" for k in fieldnames]
            safe = [v.replace("'", "''") for v in vals]
            f.write("INSERT INTO spm_export(%s) VALUES ('%s');\n"
                    % (",".join(fieldnames), "','".join(safe)))
elif fmt == "ini":
    with open(out_path, "w", encoding="utf-8") as f:
        for r in rows:
            sect = f"{r.get('type','unknown')}_{r.get('id','')}"
            f.write(f"[{sect}]\n")
            for k in fieldnames:
                val = json.dumps(str(r.get(k,'') or ''), ensure_ascii=False)
                f.write(f"{k}={val}\n")
            f.write("\n")
elif fmt == "psv":
    with open(out_path, "w", encoding="utf-8", newline="") as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames, delimiter="|")
        writer.writeheader()
        writer.writerows(rows)
elif fmt == "rst":
    encoded_rows = [{k: json.dumps(str(r.get(k,"") or ""), ensure_ascii=False).replace("|", "\\u007c") for k in fieldnames} for r in rows]
    widths = {k: max(len(k), max(len(r[k]) for r in encoded_rows) if encoded_rows else 0) for k in fieldnames}
    def sep(char="+"):
        return char + char.join("-" * (widths[k]+2) for k in fieldnames) + char + "\n"
    def row(vals):
        return "|" + "|".join(" " + v.ljust(widths[k]) + " " for k,v in vals) + "|\n"
    with open(out_path, "w", encoding="utf-8") as f:
        f.write(sep())
        f.write(row([(k,k) for k in fieldnames]))
        f.write(sep("+"))
        for r in encoded_rows:
            f.write(row([(k, r[k]) for k in fieldnames]))
            f.write(sep())
else:  # csv or txt fallback
    delim = "," if fmt == "csv" else ","
    with open(out_path, "w", encoding="utf-8", newline="") as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames, delimiter=delim)
        writer.writeheader()
        writer.writerows(rows)
PY
then
		secure_wipe "$tmp"
		die "Export failed."
	fi

	secure_wipe "$tmp"
	chmod 600 "$outfile" 2>/dev/null || true

	if [ "$SPM_LANG" = "id" ]; then
		printf "Export selesai: %s (%s)\n" "$outfile" "$format"
	else
		printf "Export complete: %s (%s)\n" "$outfile" "$format"
	fi
}

cmd_import() {
	[ -f "$VAULT_FILE" ] || die "Vault not found. Run '$0 init' first."
	require_cmd python3

	local format="${1:-csv}"
	format="$(printf '%s' "$format" | tr '[:upper:]' '[:lower:]')"
	local infile="${2:-}"
	[ -n "$infile" ] || die "Usage: $0 import <format> <file>"
	[ -f "$infile" ] || die "Input file '$infile' not found."

	case "$format" in
		csv|json|tsv|ndjson|jsonl|md|markdown|html|txt|yaml|yml|xml|sql|ini|psv|rst|toml|org|scsv|csv-noheader|jsonc) ;;
		*) die "Unsupported format '$format' for import." ;;
	esac

	local tmp
	tmp="$(make_tmp)"
	decrypt_vault_to_file "$tmp"

	if ! python3 - "$format" "$infile" "$tmp" "$(core_script_path)" <<'PY'
import sys, json, csv, base64, configparser, io, re, importlib.util
import xml.etree.ElementTree as ET
from html.parser import HTMLParser
fmt, src_path, vault_path, core_path = sys.argv[1:]

# Same encoder the dashboard uses, so a folder column means the same thing
# whichever surface reads the file.
_spec = importlib.util.spec_from_file_location("spm_core_import", core_path)
core = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(core)

def load_vault_lines(path):
    with open(path, "r", encoding="utf-8") as f:
        return [ln.rstrip("\n") for ln in f]

lines = load_vault_lines(vault_path)

# Every character str.splitlines() treats as a line break. Stripping only
# \t \r \n left eight more that pass through and split a record on read, so the
# entry silently vanished from the vault. Keep this in step with _VAULT_BREAKS
# in the web server.
_VAULT_BREAKS = "\t\r\n\v\f\x1c\x1d\x1e\x85\u2028\u2029"

def _read_text(path):
    # errors="ignore" silently dropped every non-UTF-8 byte, so a cp1252 export
    # imported as success with characters missing from the stored secrets.
    # Fail closed and say exactly how to convert instead.
    with open(path, "rb") as fh:
        raw = fh.read()
    try:
        return raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        line = raw.count(b"\n", 0, exc.start) + 1
        raise SystemExit(
            "Import aborted: %s is not valid UTF-8 (byte 0x%02x at line %d).\n"
            "Nothing was written to the vault. Convert it first, for example:\n"
            "  iconv -f WINDOWS-1252 -t UTF-8 %s > converted.csv"
            % (path, raw[exc.start], line, path)
        )

def _vf(value):
    # Vault records are TAB-delimited and line-based, so a field holding a raw
    # separator splits the record. Quoted multi-line notes are ordinary in CSV
    # exports from other managers, and used to land as extra broken rows.
    text = str(value or "")
    for ch in _VAULT_BREAKS:
        text = text.replace(ch, " ")
    return text


def next_id(tag):
    max_id = 0
    for ln in lines:
        if not ln:
            continue
        parts = ln.split("\t")
        if tag == "PASS" and parts[0].isdigit():
            max_id = max(max_id, int(parts[0]))
        elif parts[0] == tag and len(parts) > 1 and parts[1].isdigit():
            max_id = max(max_id, int(parts[1]))
    return max_id + 1

def _vurl(value):
    # Same allowlist as the CLI's sanitize_url and SPM Dashboard's form validation.
    # An import is the least trusted way a value enters the vault, so a foreign
    # CSV carrying "javascript:..." in its url column is dropped rather than
    # stored -- the field is rendered as a link and will feed the extension.
    text = _vf(value).strip()
    if not text:
        return ""
    return text if re.match(r"(?i)^https?://[^\s/]+", text) else ""

def add_password(r):
    pid = str(next_id("PASS"))
    lines.append("\t".join([
        pid,
        _vf(r.get("label","")),
        _vf(r.get("username","")),
        _vf(r.get("secret","")),
        _vf(r.get("notes","")),
        _vf(r.get("created","")),
        _vurl(r.get("url","")),
        core.attrs_from_export_row(r)
    ]))

def add_note(r):
    nid = str(next_id("NOTE"))
    body_b64 = base64.b64encode((r.get("secret","") or "").encode("utf-8")).decode("ascii")
    lines.append("\t".join([
        "NOTE",
        nid,
        _vf(r.get("label","")),
        body_b64,
        _vf(r.get("created","")),
        "-"
    ]))

def add_passphrase(r):
    pid = str(next_id("PASSPHRASE"))
    secret_b64 = base64.b64encode((r.get("secret","") or "").encode("utf-8")).decode("ascii")
    lines.append("\t".join([
        "PASSPHRASE",
        pid,
        _vf(r.get("label","")),
        secret_b64,
        _vf(r.get("created","")),
        "-"
    ]))

def add_backup(r):
    bid = str(next_id("BACKUP_CODE"))
    codes_b64 = base64.b64encode((r.get("secret","") or "").encode("utf-8")).decode("ascii")
    lines.append("\t".join([
        "BACKUP_CODE",
        bid,
        _vf(r.get("label","")),
        codes_b64,
        _vf(r.get("created","")),
        "-"
    ]))

def add_auth(r):
    aid = str(next_id("AUTH"))
    def parse_extra(val):
        out = {}
        for part in str(val or "").split(";"):
            if "=" in part:
                k,v = part.split("=",1)
                out[k.strip().lower()] = v.strip()
        return out
    extra_map = parse_extra(r.get("extra",""))
    algo = (extra_map.get("algo") or r.get("algorithm","") or "sha1").lower()
    if algo not in ("sha1","sha256","sha512"):
        algo = "sha1"
    period = extra_map.get("period") or r.get("extra","").replace("period=","") or "30"
    lines.append("\t".join([
        "AUTH",
        aid,
        _vf(r.get("label","")),
        _vf(r.get("secret","")),
        _vf(period),
        _vf(r.get("created","")),
        algo
    ]))

def parse_structured():
    return json.loads(_read_text(src_path))

def parse_rows():
    if fmt in ("json","jsonc"):
        return parse_structured()
    if fmt in ("ndjson","jsonl"):
        out = []
        for line in _read_text(src_path).splitlines():
            if True:
                line=line.strip()
                if not line: continue
                out.append(json.loads(line))
        return out
    delim = "," if fmt in ("csv","csv-noheader","jsonc") else ";" if fmt=="scsv" else "\t" if fmt=="tsv" else "|"
    rows=[]
    with io.StringIO(_read_text(src_path), newline="") as f:
        reader = csv.DictReader(f, delimiter=delim) if fmt!="csv-noheader" else csv.reader(f, delimiter=delim)
        if fmt=="csv-noheader":
            # Mapped against the core's column order rather than a copy of it.
            # The copy that used to live here stopped at `url`, so a headerless
            # export lost its folder and custom fields on the way back in.
            for row in reader:
                rows.append(core.export_row_from_values(row))
        else:
            rows = list(reader)
    return rows

def parse_advanced_rows():
    content = _read_text(src_path)
    if fmt in ("txt",):
        return list(csv.DictReader(io.StringIO(content), delimiter=","))
    if fmt in ("md", "markdown", "org", "rst"):
        return parse_plain_table()
    if fmt == "html":
        class TableParser(HTMLParser):
            def __init__(self):
                super().__init__(); self.rows=[]; self.row=[]; self.cell=[]; self.in_cell=False
            def handle_starttag(self, tag, attrs):
                if tag.lower() in ("td", "th"): self.in_cell=True; self.cell=[]
            def handle_data(self, data):
                if self.in_cell: self.cell.append(data)
            def handle_endtag(self, tag):
                tag=tag.lower()
                if tag in ("td", "th") and self.in_cell:
                    self.row.append("".join(self.cell)); self.in_cell=False
                elif tag == "tr" and self.row:
                    self.rows.append(self.row); self.row=[]
        parser=TableParser(); parser.feed(content)
        if not parser.rows: return []
        headers=parser.rows[0]
        return [dict(zip(headers, row)) for row in parser.rows[1:]]
    if fmt in ("yaml", "yml"):
        rows=[]; current=None
        for line in content.splitlines():
            if line.strip() == "-":
                if current is not None: rows.append(current)
                current={}
            elif current is not None and ":" in line:
                key, value=line.strip().split(":", 1)
                value=value.strip()
                try: value=json.loads(value)
                except json.JSONDecodeError: value=value.strip('"')
                current[key]=value
        if current is not None: rows.append(current)
        return rows
    if fmt == "xml":
        root=ET.fromstring(content)
        return [{child.tag: (child.text or "") for child in item} for item in root.findall("item")]
    if fmt == "sql":
        # The column names come from the statement rather than from a list
        # kept here. A hardcoded list is what let the exporter grow a column
        # the reader silently mapped onto the wrong name -- and what made SPM
        # the only tool that could read its own SQL.
        rows=[]
        default=list(core.EXPORT_FIELDNAMES)
        for names, values in re.findall(
                r"INSERT\s+INTO\s+spm_export\s*\(([^)]*)\)\s*VALUES\s*\((.*?)\)\s*;",
                content, re.I | re.S):
            fields=[n.strip().strip('"`[]') for n in names.split(",") if n.strip()] or default
            parsed=next(csv.reader([values], delimiter=",", quotechar="'", doublequote=True, skipinitialspace=True))
            rows.append(dict(zip(fields, parsed)))
        return rows
    if fmt == "ini":
        cfg=configparser.ConfigParser(interpolation=None); cfg.optionxform=str; cfg.read_string(content)
        return [{k: (json.loads(v) if v.startswith('"') and v.endswith('"') else v) for k,v in cfg.items(section)} for section in cfg.sections()]
    if fmt == "toml":
        try:
            import tomllib
            return tomllib.loads(content).get("item", [])
        except ModuleNotFoundError:
            # Python 3.10 and older have no tomllib. SPM's own TOML export is a
            # deliberately small [[item]] + quoted-string subset, so parse that
            # subset without adding a network-installed dependency.
            rows=[]; current=None
            for raw in content.splitlines():
                line=raw.strip()
                if not line or line.startswith("#"): continue
                if line == "[[item]]":
                    if current is not None: rows.append(current)
                    current={}; continue
                if current is None or "=" not in line: continue
                key,value=line.split("=",1); key=key.strip(); value=value.strip()
                if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_-]*", key):
                    raise ValueError("Invalid TOML key")
                current[key]=json.loads(value)
            if current is not None: rows.append(current)
            return rows
    return []

def parse_plain_table():
    rows = []
    headers = None
    with open(src_path,"r",encoding="utf-8",errors="ignore") as f:
        for ln in f:
            ln=ln.strip()
            if not ln or ln.startswith("#") or ln.startswith("| ---") or ln.startswith("+"): continue
            if "|" in ln:
                parts=[p.strip() for p in ln.strip("|").split("|")]
            else:
                parts=[p.strip() for p in ln.split()]
            if len(parts) < 2:
                continue
            if parts[0].lower() == "type":
                headers = [p.lower() for p in parts]
                continue
            parts = [json.loads(p) if p.startswith('"') and p.endswith('"') else p for p in parts]
            if headers:
                rows.append(dict(zip(headers, parts)))
            else:
                rows.append({
                    "type": parts[0],
                    "label": parts[1] if len(parts)>1 else "",
                    "username": parts[2] if len(parts)>2 else "",
                    "secret": parts[3] if len(parts)>3 else "",
                    "notes": parts[4] if len(parts)>4 else "",
                    "created": parts[5] if len(parts)>5 else "",
                    "extra": parts[6] if len(parts)>6 else "",
                    "url": parts[7] if len(parts)>7 else "",
                })
    return rows

def load_rows():
    if fmt in ("json","jsonc","ndjson","jsonl","csv","csv-noheader","tsv","scsv","psv"):
        return parse_rows()
    return parse_advanced_rows()

rows = load_rows()
if not rows:
    raise ValueError("No records detected in import.")

added = 0
skipped = {}
for row in rows:
    t = (row.get("type","") or "").lower()
    if t in ("password","pass"):
        add_password(row)
        added += 1
    elif t in ("note","notes"):
        add_note(row)
        added += 1
    elif t in ("passphrase","phrase","secret"):
        add_passphrase(row)
        added += 1
    elif t in ("backup_code","backup","codes","backupcode"):
        add_backup(row)
        added += 1
    elif t in ("authenticator","auth"):
        add_auth(row)
        added += 1
    else:
        # Rows used to be dropped in silence, so a partial import looked
        # identical to a complete one. Name the types that were not understood.
        skipped[t or "(blank)"] = skipped.get(t or "(blank)", 0) + 1

if added == 0:
    raise ValueError("No supported records found in import.")

sys.stderr.write("Imported %d of %d record(s).\n" % (added, len(rows)))
if skipped:
    detail = ", ".join("%s x%d" % (k, v) for k, v in sorted(skipped.items()))
    sys.stderr.write("Skipped %d record(s) with unrecognised type: %s\n"
                     % (sum(skipped.values()), detail))

with open(vault_path, "w", encoding="utf-8") as f:
    for ln in lines:
        f.write(ln + "\n")
PY
	then
		secure_wipe "$tmp"
		die "Import failed."
	fi

	encrypt_file_to_vault "$tmp"
	secure_wipe "$tmp"

	if [ "$SPM_LANG" = "id" ]; then
		printf "Import selesai dari %s (%s)\n" "$infile" "$format"
	else
		printf "Import complete from %s (%s)\n" "$infile" "$format"
	fi
}

# ----- Local-first advanced capabilities (2.10) ------------------------------

cmd_security_dashboard() {
	[ -f "$VAULT_FILE" ] || die "Vault not found."
	local tmp report breaches="" days="${SPM_ROTATION_DAYS:-365}" status=0
	case "$days" in ''|*[!0-9]*) days=365 ;; esac
	[ "$days" -gt 0 ] 2>/dev/null || days=365
	while [ "$#" -gt 0 ]; do
		case "$1" in
			--breaches) breaches="--breaches" ;;
			*) die "Unknown option for security: $1" ;;
		esac
		shift
	done
	tmp="$(make_tmp)"; decrypt_vault_to_file "$tmp"
	report="$(make_tmp)"
	# shellcheck disable=SC2086
	core security-report "$tmp" "$days" $breaches > "$report" || status=$?
	secure_wipe "$tmp"
	[ "$status" -eq 0 ] || { secure_wipe "$report"; die "Security review failed."; }
	python3 - "$report" <<'PY'
import json, sys
audit = json.load(open(sys.argv[1], encoding="utf-8"))
print("Security dashboard")
print("==================")
print("Score: %d/100" % audit["score"])
print("Passwords: %d" % audit["passwords"])
print("Weak IDs:", ", ".join(audit["weak"]) or "none")
print("Reused groups:", "; ".join(",".join(group) for group in audit["reused"]) or "none")
print("Older than %d days:" % audit["rotation_days"], ", ".join(audit["old"]) or "none")
print("Incomplete IDs:", ", ".join(audit["incomplete"]) or "none")
print("Malformed protected records:", ", ".join("authenticator:" + rid for rid in audit["malformed"]) or "none")
if audit["breach_status"] == "checked":
    findings = ", ".join("%s (%s sightings)" % (item["id"], item["count"])
                         for item in audit["breached"])
    print("Known breach IDs:", findings or "none")
elif audit["breach_status"] == "unavailable":
    print("Known breach IDs: check unavailable; no clean result assumed")
else:
    print("Known breach IDs: not checked (use --breaches for the opt-in online check)")
print("Passwords and full hashes are never sent, printed, or persisted.")
PY
	secure_wipe "$report"
}

cmd_history_list() {
	local dir
	dir="$(history_dir)"
	[ -d "$dir" ] || { printf 'No encrypted history snapshots.\n'; return 0; }
	find "$dir" -maxdepth 1 -type f -name '*.gpg' -print 2>/dev/null \
		| while IFS= read -r snapshot; do basename "$snapshot"; done | sort -r
}

cmd_history_restore() {
	local name="${1:-}" dir source answer verify_tmp
	[ -n "$name" ] || die "Usage: $0 history-restore <snapshot-name>"
	case "$name" in */*|*\\*|.|..) die "Invalid snapshot name." ;; esac
	dir="$(history_dir)"; source="$dir/$name"
	[ -f "$source" ] || die "History snapshot not found."
	printf "Restore encrypted snapshot %s? (yes/NO): " "$name"; read -r answer || answer=no
	case "$answer" in yes|y|YES|Y) ;; *) return 1 ;; esac
	ensure_master_password_loaded; verify_tmp="$(make_tmp)"
	# No key variable: a snapshot carries its own vault key, and letting that
	# key escape into the next write would seal the live vault under it.
	decrypt_vault_container "$source" "$verify_tmp" "$MASTER_PW" \
		|| { secure_wipe "$verify_tmp"; die "History snapshot failed authentication or uses a different master password."; }
	secure_wipe "$verify_tmp"
	core install-file "$source" "$VAULT_FILE" >/dev/null \
		|| die "Failed to restore history snapshot."
	printf 'History snapshot restored.\n'
}

cmd_backup_now() {
	[ -f "$VAULT_FILE" ] || die "Vault not found."
	local target="${1:-$SPM_DATA_DIR/backups}" name digest
	mkdir -p "$target" || die "Failed to create backup directory."
	chmod 700 "$target" 2>/dev/null || true
	name="spm-$(vault_scope_id)-$(date -u +%Y%m%dT%H%M%SZ)-$$.gpg"
	cp "$VAULT_FILE" "$target/$name" || die "Backup failed."
	chmod 600 "$target/$name" 2>/dev/null || true
	digest="$(sha256sum "$VAULT_FILE" | awk '{print $1}')"
	[ "$digest" = "$(sha256sum "$target/$name" | awk '{print $1}')" ] || die "Backup verification failed."
	printf '%s\n' "$target/$name"
}

cmd_backup_auto() {
	local action="${1:-status}" cfg target hours retention
	cfg="$(auto_backup_config)"; mkdir -p "$SPM_CONFIG_DIR"; chmod 700 "$SPM_CONFIG_DIR" 2>/dev/null || true
	case "$action" in
		enable)
			target="${2:-$SPM_DATA_DIR/backups}"; hours="${3:-24}"; retention="${4:-14}"
			printf '%s' "$hours$retention" | grep -Eq '^[0-9]+$' || die "Hours and retention must be positive integers."
			if [ "$hours" -le 0 ] || [ "$retention" -le 0 ]; then die "Hours and retention must be positive."; fi
			mkdir -p "$target" || die "Cannot create automatic-backup directory."
			printf 'enabled\n%s\n%s\n%s\n0\n' "$(canon_path "$target")" "$hours" "$retention" > "$cfg"
			chmod 600 "$cfg"; maybe_auto_backup; printf 'Automatic encrypted backups enabled.\n' ;;
		disable) printf 'disabled\n' > "$cfg"; chmod 600 "$cfg"; printf 'Automatic backups disabled.\n' ;;
		status) [ -f "$cfg" ] && sed -n '1,4p' "$cfg" || printf 'disabled\n' ;;
		*) die "Usage: $0 backup-auto enable [directory] [hours] [retention] | disable | status" ;;
	esac
}

validate_profile_name() {
	printf '%s' "$1" | grep -Eq '^[A-Za-z0-9][A-Za-z0-9._-]{0,31}$' || die "Invalid profile name."
}

cmd_vault_profile() {
	local action="${1:-list}" name path tmp
	mkdir -p "$SPM_CONFIG_DIR"; chmod 700 "$SPM_CONFIG_DIR" 2>/dev/null || true
	[ -f "$SPM_PROFILE_FILE" ] || : > "$SPM_PROFILE_FILE"; chmod 600 "$SPM_PROFILE_FILE"
	case "$action" in
		list) awk -F '\t' '{printf "%-20s %s\n",$1,$2}' "$SPM_PROFILE_FILE" ;;
		add)
			name="${2:-}"; path="${3:-}"; validate_profile_name "$name"; [ -n "$path" ] || die "Vault path required."
			if printf '%s' "$path" | LC_ALL=C grep -q '[[:cntrl:]]'; then die "Vault paths cannot contain control characters."; fi
			path="$(canon_path "$path")"; awk -F '\t' -v n="$name" '$1==n{found=1} END{exit found?0:1}' "$SPM_PROFILE_FILE" && die "Profile already exists."
			printf '%s\t%s\n' "$name" "$path" >> "$SPM_PROFILE_FILE"; printf 'Profile added.\n' ;;
		use)
			name="${2:-}"; validate_profile_name "$name"; profile_vault_path "$name" >/dev/null || die "Unknown profile."
			printf '%s\n' "$name" > "$SPM_DEFAULT_PROFILE_FILE"; chmod 600 "$SPM_DEFAULT_PROFILE_FILE"; printf 'Default profile set; restart SPM to apply.\n' ;;
		remove)
			name="${2:-}"; validate_profile_name "$name"; tmp="$(make_tmp)"; awk -F '\t' -v n="$name" '$1!=n' "$SPM_PROFILE_FILE" > "$tmp"; mv "$tmp" "$SPM_PROFILE_FILE"; chmod 600 "$SPM_PROFILE_FILE"
			if [ -f "$SPM_DEFAULT_PROFILE_FILE" ] && [ "$(sed -n '1p' "$SPM_DEFAULT_PROFILE_FILE")" = "$name" ]; then rm -f "$SPM_DEFAULT_PROFILE_FILE"; fi
			printf 'Profile removed; vault data was not deleted.\n' ;;
		*) die "Usage: $0 vault-profile list|add <name> <path>|use <name>|remove <name>" ;;
	esac
}

next_tag_id() {
	local tag="$1" file="$2"
	awk -F '\t' -v tag="$tag" '$1==tag && $2~/^[0-9]+$/ && $2>m{m=$2} END{print m+1}' "$file"
}

cmd_attachment_add() {
	local file="${1:-}" label="${2:-}" size tmp id encoded filename mime digest created
	[ -f "$file" ] || die "Attachment file not found."
	size="$(wc -c < "$file" | tr -d ' ')"; [ "$size" -le 1048576 ] || die "Attachment exceeds the 1 MiB limit."
	[ -n "$label" ] || label="$(basename "$file")"; label="$(sanitize_field "$label")"
	filename="$(printf '%s' "$(basename "$file")" | base64 | tr -d '\n')"
	mime="$(file -b --mime-type "$file" 2>/dev/null || printf 'application/octet-stream')"; mime="$(sanitize_field "$mime")"
	encoded="$(base64 < "$file" | tr -d '\n')"; digest="$(sha256sum "$file" | awk '{print $1}')"; created="$(now_iso)"
	tmp="$(make_tmp)"; decrypt_vault_to_file "$tmp"; id="$(next_tag_id ATTACHMENT "$tmp")"
	printf 'ATTACHMENT\t%s\t%s\t%s\t%s\t%s\t%s\t%s\n' "$id" "$label" "$filename" "$mime" "$encoded" "$digest" "$created" >> "$tmp"
	encrypt_file_to_vault "$tmp"; secure_wipe "$tmp"; printf 'Attachment added with ID %s.\n' "$id"
}

cmd_attachment_list() {
	local tmp; tmp="$(make_tmp)"; decrypt_vault_to_file "$tmp"
	awk -F '\t' '$1=="ATTACHMENT"{printf "%s\t%s\t%s\t%s\n",$2,$3,$5,$8}' "$tmp"; secure_wipe "$tmp"
}

cmd_attachment_extract() {
	local id="${1:-}" out="${2:-}" tmp payload filename digest actual
	printf '%s' "$id" | grep -Eq '^[0-9]+$' || die "Numeric attachment ID required."
	tmp="$(make_tmp)"; decrypt_vault_to_file "$tmp"
	payload="$(awk -F '\t' -v id="$id" '$1=="ATTACHMENT"&&$2==id{print $6;exit}' "$tmp")"
	filename="$(awk -F '\t' -v id="$id" '$1=="ATTACHMENT"&&$2==id{print $4;exit}' "$tmp" | base64 -d 2>/dev/null || true)"
	digest="$(awk -F '\t' -v id="$id" '$1=="ATTACHMENT"&&$2==id{print $7;exit}' "$tmp")"; secure_wipe "$tmp"
	[ -n "$payload" ] || die "Attachment not found."; [ -n "$out" ] || out="./$filename"; [ ! -e "$out" ] || die "Destination already exists."
	printf '%s' "$payload" | base64 -d > "$out" || { rm -f "$out"; die "Attachment decode failed."; }
	actual="$(sha256sum "$out" | awk '{print $1}')"; [ "$actual" = "$digest" ] || { secure_wipe "$out"; die "Attachment integrity check failed."; }
	chmod 600 "$out" 2>/dev/null || true; printf '%s\n' "$out"
}

cmd_tag_delete() {
	local tag="$1" id="$2" label="$3" tmp next found=0
	printf '%s' "$id" | grep -Eq '^[0-9]+$' || die "Numeric ID required."
	tmp="$(make_tmp)"; next="$(make_tmp)"; decrypt_vault_to_file "$tmp"
	while IFS= read -r line || [ -n "$line" ]; do
		if [ "${line%%$'\t'*}" = "$tag" ] && [ "$(printf '%s' "$line" | cut -f2)" = "$id" ]; then found=1; else printf '%s\n' "$line" >> "$next"; fi
	done < "$tmp"
	[ "$found" = 1 ] || { secure_wipe "$tmp"; secure_wipe "$next"; die "$label not found."; }
	encrypt_file_to_vault "$next"; secure_wipe "$tmp"; secure_wipe "$next"; printf '%s deleted.\n' "$label"
}

cmd_passkey_add() {
	local rp="${1:-}" account="${2:-}" credential="${3:-}" notes="${4:-}" tmp id created encoded
	if [ -z "$rp" ] || [ -z "$account" ] || [ -z "$credential" ]; then die "Usage: $0 passkey-add <rp-id> <account> <credential-id> [notes]"; fi
	rp="$(sanitize_field "$rp")"; account="$(sanitize_field "$account")"; credential="$(sanitize_field "$credential")"; encoded="$(printf '%s' "$notes" | base64 | tr -d '\n')"; created="$(now_iso)"
	tmp="$(make_tmp)"; decrypt_vault_to_file "$tmp"; id="$(next_tag_id PASSKEY "$tmp")"
	printf 'PASSKEY\t%s\t%s\t%s\t%s\t%s\t%s\n' "$id" "$rp" "$account" "$credential" "$encoded" "$created" >> "$tmp"
	encrypt_file_to_vault "$tmp"; secure_wipe "$tmp"; printf 'Passkey metadata added with ID %s; private key remains in the platform authenticator.\n' "$id"
}

cmd_passkey_list() {
	local tmp; tmp="$(make_tmp)"; decrypt_vault_to_file "$tmp"; awk -F '\t' '$1=="PASSKEY"{printf "%s\t%s\t%s\t%s\n",$2,$3,$4,$7}' "$tmp"; secure_wipe "$tmp"
}

# SPM Dashboard biometric unlock credentials. A separate row type from PASSKEY on
# purpose: a PASSKEY row describes a passkey held somewhere else, while these
# open this vault. The public key column is deliberately not printed -- it is
# long, it is never useful to read by eye, and the list is for deciding what to
# revoke. Registration is browser-only, so there is no matching add command.
cmd_webauthn_list() {
	local tmp; tmp="$(make_tmp)"; decrypt_vault_to_file "$tmp"
	awk -F '\t' '$1=="WEBAUTHN"{printf "%s\t%s\t%s\t%s\n",$2,$6,$5,$7}' "$tmp"
	secure_wipe "$tmp"
}

# ----- sync transports -------------------------------------------------------
# A transport answers three questions and nothing else: can I reach this target,
# put the remote object in this file, make this file the remote object.
#
# Everything that decides anything -- conflict detection, digest verification,
# archiving before replacement, refusing a remote that will not decrypt -- lives
# above this line, in cmd_sync, and is therefore identical for every transport.
# A transport added later cannot skip a safety check because it is never asked
# to perform one.
#
# Digests are always computed here, locally, over a fetched copy. No transport
# is asked to hash for us: a remote-side digest is a claim, not a measurement.
#
# Adding a transport means one branch in each of the three functions below, and
# a line in sync_transport_names.

# rsync's own -e: a non-default port, an identity file, a jump host.
# SPM_SYNC_RSYNC_SHELL is passed as a single argument, because that is what -e
# takes -- "ssh -p 2222" is one option value, not two words.
sync_rsync() {
	if [ -n "${SPM_SYNC_RSYNC_SHELL:-}" ]; then
		rsync -e "$SPM_SYNC_RSYNC_SHELL" "$@"
	else
		rsync "$@"
	fi
}


sync_transport_names() {
	printf 'dir rsync rclone'
}

sync_known_transport() {
	case " $(sync_transport_names) " in
		*" $1 "*) return 0 ;;
		*) return 1 ;;
	esac
}

# Does the target exist and can we talk to it? Called before any decision, so
# that an unreachable remote fails here rather than being mistaken further down
# for a remote that is merely empty.
sync_transport_probe() {
	local transport="$1" target="$2"
	case "$transport" in
		dir)
			mkdir -p "$target" 2>/dev/null || die "Cannot create sync target '$target'."
			[ -d "$target" ] || die "Sync target '$target' is not a directory."
			;;
		rsync)
			require_cmd rsync
			case "$target" in
				*:*) ;;
				*) die "An rsync target looks like [user@]host:/path." ;;
			esac
			# A listing proves the path is reachable and readable. Without it a
			# host that is merely down would present as an empty remote.
			sync_rsync --list-only "$target/" >/dev/null 2>&1 \
				|| die "Cannot reach rsync target '$target'."
			;;
		rclone)
			require_cmd rclone
			case "$target" in
				*:*) ;;
				*) die "An rclone target looks like remote:path." ;;
			esac
			rclone lsf "$target" >/dev/null 2>&1 \
				|| die "Cannot reach rclone target '$target'. Is the remote configured?"
			;;
		*) die "Unknown sync transport: $transport" ;;
	esac
}

# Fetch the remote object into "$3". 0 fetched, 1 definitely absent. Anything
# else is fatal and must not be reported as absence -- see the comment above.
sync_transport_fetch() {
	local transport="$1" remote="$2" dest="$3"
	case "$transport" in
		dir)
			[ -f "$remote" ] || return 1
			cp "$remote" "$dest" || die "Cannot read the remote vault."
			;;
		rsync)
			sync_rsync --list-only "$remote" >/dev/null 2>&1 || return 1
			sync_rsync -q "$remote" "$dest" \
				|| die "Cannot read the remote vault."
			;;
		rclone)
			rclone lsf "$remote" >/dev/null 2>&1 || return 1
			rclone copyto "$remote" "$dest" >/dev/null 2>&1 \
				|| die "Cannot read the remote vault."
			;;
		*) die "Unknown sync transport: $transport" ;;
	esac
	chmod 600 "$dest" 2>/dev/null || true
	return 0
}

# Publish "$3" as the remote object. Staged under a temporary name and moved
# into place where the transport can do so, so a reader never sees a half-
# written vault.
sync_transport_publish() {
	local transport="$1" remote="$2" src="$3" staged
	case "$transport" in
		dir)
			staged="$(mktemp "$(dirname "$remote")/.spm-sync.XXXXXX")" \
				|| die "Cannot stage sync push."
			cp "$src" "$staged" || { rm -f "$staged"; die "Cannot stage sync push."; }
			chmod 600 "$staged"
			mv -f "$staged" "$remote" || { rm -f "$staged"; die "Cannot install sync push."; }
			;;
		rsync)
			# rsync writes to a temporary name on the receiving side and
			# renames it into place, so a reader never sees a partial vault
			# and no staging of our own is needed.
			# -p rather than --chmod=F600. rsync 2.6.9, which Apple still
			# ships, has --chmod but rejects the F and D class prefixes that
			# make it mean "files only" -- so the flag was accepted and the
			# value was not. Preserving the mode of a copy whose mode we set
			# ourselves needs nothing newer than -p.
			staged="$(make_tmp)"
			cp "$src" "$staged" || die "Cannot stage the sync push."
			chmod 600 "$staged"
			sync_rsync -q -p "$staged" "$remote" \
				|| die "Cannot write to the rsync target."
			;;
		rclone)
			rclone copyto "$src" "$remote" >/dev/null 2>&1 \
				|| die "Cannot write to the rclone target."
			;;
		*) die "Unknown sync transport: $transport" ;;
	esac
}

sync_paths() {
	local transport="$1" target="$2" channel="$3" target_id
	printf '%s' "$channel" | grep -Eq '^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$' || die "Invalid sync channel."
	# The transport is part of the identity: the same path reached two ways is
	# still one remote, but "myremote:spm" over rclone and a directory of that
	# name are not, and must not share a base digest.
	target_id="$(printf '%s\t%s\t%s' "$transport" "$target" "$channel" | sha256sum | awk '{print substr($1,1,16)}')"
	mkdir -p "$SPM_CONFIG_DIR"; chmod 700 "$SPM_CONFIG_DIR" 2>/dev/null || true
	SYNC_REMOTE="$target/spm-$channel.gpg"; SYNC_STATE="$SPM_CONFIG_DIR/sync-$target_id.base-sha256"
}

write_sync_state() {
	local digest="$1" staged_state
	staged_state="$(mktemp "$SPM_CONFIG_DIR/.spm-sync-state.XXXXXX")" || die "Cannot stage sync state."
	printf '%s\n' "$digest" > "$staged_state"; chmod 600 "$staged_state"
	mv -f "$staged_state" "$SYNC_STATE" || { rm -f "$staged_state"; die "Cannot install sync state."; }
}

sync_usage() {
	printf 'Usage: %s sync status|push|pull <target> [channel] [--transport %s]\n' \
		"$0" "$(sync_transport_names | tr ' ' '|')"
}

cmd_sync() {
	local action="" target="" channel="default" transport="dir"
	local positional=0 local_sha remote_sha base_sha tmp fetched rc

	while [ "$#" -gt 0 ]; do
		case "$1" in
			--transport)
				[ "$#" -ge 2 ] || { sync_usage >&2; die "Missing value for --transport."; }
				transport="$2"; shift 2 ;;
			--transport=*) transport="${1#--transport=}"; shift ;;
			-h|--help) sync_usage; return ;;
			-*) sync_usage >&2; die "Unknown option: $1" ;;
			*)
				case "$positional" in
					0) action="$1" ;;
					1) target="$1" ;;
					2) channel="$1" ;;
					*) sync_usage >&2; die "Unexpected argument: $1" ;;
				esac
				positional=$((positional + 1)); shift ;;
		esac
	done

	[ -n "$action" ] || { sync_usage >&2; return 1; }
	sync_known_transport "$transport" \
		|| { sync_usage >&2; die "Unknown sync transport: $transport"; }
	case "$action" in
		status|push|pull) ;;
		*) sync_usage >&2; die "Unknown sync action: $action" ;;
	esac
	[ -n "$target" ] || { sync_usage >&2; die "A sync target is required."; }

	# `dir` is the only transport whose target is a local path, and the only one
	# that can be canonicalised or created.
	if [ "$transport" = "dir" ]; then
		mkdir -p "$target" || die "Cannot create sync target."
		target="$(canon_path "$target")"
	fi
	# Before any decision. An unreachable target must fail here; further down it
	# would be indistinguishable from a remote that is merely empty, which is
	# exactly the state in which pushing over it feels safe.
	sync_transport_probe "$transport" "$target"
	sync_paths "$transport" "$target" "$channel"

	local_sha=""; remote_sha=""; base_sha=""
	[ -f "$VAULT_FILE" ] && local_sha="$(sha256sum "$VAULT_FILE" | awk '{print $1}')"
	[ -f "$SYNC_STATE" ] && base_sha="$(sed -n '1p' "$SYNC_STATE")"

	# The remote digest is measured here, over a copy we fetched, for every
	# transport alike. Nothing remote is asked what it holds.
	fetched="$(make_tmp)"
	set +o errexit
	sync_transport_fetch "$transport" "$SYNC_REMOTE" "$fetched"
	rc=$?
	set -o errexit
	if [ "$rc" -eq 0 ]; then
		remote_sha="$(sha256sum "$fetched" | awk '{print $1}')"
	else
		secure_wipe "$fetched"; fetched=""
	fi

	case "$action" in
		status)
			printf 'transport=%s\ntarget=%s\nchannel=%s\nlocal=%s\nremote=%s\nbase=%s\n' \
				"$transport" "$target" "$channel" \
				"${local_sha:-missing}" "${remote_sha:-missing}" "${base_sha:-none}"
			;;
		push)
			[ -n "$local_sha" ] || die "Local vault missing."
			if [ -n "$remote_sha" ] && [ -z "$base_sha" ] && [ "$local_sha" != "$remote_sha" ] && [ "${SPM_SYNC_FORCE_INITIAL:-0}" != 1 ]; then
				die "Initial sync conflict: remote differs; pull or set SPM_SYNC_FORCE_INITIAL=1 after verification."
			fi
			if [ -n "$remote_sha" ] && [ -n "$base_sha" ] && [ "$remote_sha" != "$base_sha" ] && [ "$local_sha" != "$base_sha" ]; then
				die "Sync conflict: local and remote both changed."
			fi
			sync_transport_publish "$transport" "$SYNC_REMOTE" "$VAULT_FILE"
			# Read it back rather than trust the write. A transport that
			# truncated or transcoded the file is caught here, before the base
			# digest records a state that never existed.
			staged="$(make_tmp)"
			sync_transport_fetch "$transport" "$SYNC_REMOTE" "$staged" \
				|| { secure_wipe "$staged"; die "The pushed vault could not be read back."; }
			if [ "$(sha256sum "$staged" | awk '{print $1}')" != "$local_sha" ]; then
				secure_wipe "$staged"; die "The pushed vault does not match what was sent."
			fi
			secure_wipe "$staged"
			write_sync_state "$local_sha"
			printf 'Encrypted vault pushed over %s.\n' "$transport"
			;;
		pull)
			[ -n "$remote_sha" ] || die "Remote vault missing."
			if [ -n "$local_sha" ] && [ -z "$base_sha" ] && [ "$local_sha" != "$remote_sha" ] && [ "${SPM_SYNC_FORCE_INITIAL:-0}" != 1 ]; then
				die "Initial sync conflict: local differs; set SPM_SYNC_FORCE_INITIAL=1 only after verification."
			fi
			if [ -n "$local_sha" ] && [ -n "$base_sha" ] && [ "$local_sha" != "$base_sha" ] && [ "$remote_sha" != "$base_sha" ]; then
				die "Sync conflict: local and remote both changed."
			fi
			tmp="$(make_tmp)"; ensure_master_password_loaded
			# Prove the fetched vault opens before the local one is touched.
			# A remote that cannot be decrypted is not a vault this user can
			# use, whatever the transport thinks it delivered.
			decrypt_vault_container "$fetched" "$tmp" "$MASTER_PW" \
				|| { secure_wipe "$tmp"; die "Remote vault cannot be decrypted with this master password."; }
			secure_wipe "$tmp"
			# One install path for every command that replaces the vault
			# file: archived, copied to .bak, digest-checked while the
			# destination is still intact, fsynced, then renamed.
			core install-file "$fetched" "$VAULT_FILE" --sha256 "$remote_sha" \
				>/dev/null || die "Staged sync pull failed verification."
			write_sync_state "$remote_sha"
			printf 'Encrypted vault pulled over %s.\n' "$transport"
			;;
	esac
	[ -n "$fetched" ] && secure_wipe "$fetched"
	return 0
}

cmd_emergency_create() {
	local id="${1:-}" public_key="${2:-}" activation="${3:-}" output="${4:-}" tmp payload key_file kit_dir
	printf '%s' "$id" | grep -Eq '^[0-9]+$' || die "Numeric password ID required."
	[ -f "$public_key" ] || die "Recipient RSA public key not found."
	[ -n "$activation" ] || die "Activation date required (YYYY-MM-DD)."
	python3 - "$activation" <<'PY' >/dev/null || die "Invalid activation date."
import datetime,sys
datetime.date.fromisoformat(sys.argv[1])
PY
	[ -n "$output" ] || output="emergency-$id-$activation.tar.gz"; [ ! -e "$output" ] || die "Emergency archive already exists."
	tmp="$(make_tmp)"; payload="$(make_tmp)"; key_file="$(make_tmp)"; kit_dir="$(mktemp -d "${TMPDIR:-/tmp}/spm-emergency.XXXXXX")"; chmod 700 "$kit_dir"
	decrypt_vault_to_file "$tmp"
	python3 - "$tmp" "$id" > "$payload" <<'PY'
import json,sys
for line in open(sys.argv[1],encoding="utf-8"):
 p=line.rstrip("\n").split("\t")
 if p and p[0]==sys.argv[2] and len(p)>=6:
  print(json.dumps({"type":"password","label":p[1],"username":p[2],"secret":p[3],"notes":p[4],"created":p[5],"url":p[6] if len(p)>6 else ""},ensure_ascii=False));break
else: raise SystemExit("record not found")
PY
	openssl rand -hex 32 > "$key_file"
	openssl enc -aes-256-cbc -salt -pbkdf2 -iter 200000 -pass file:"$key_file" -in "$payload" -out "$kit_dir/payload.enc"
	openssl pkeyutl -encrypt -pubin -inkey "$public_key" -pkeyopt rsa_padding_mode:oaep -pkeyopt rsa_oaep_md:sha256 -in "$key_file" -out "$kit_dir/key.enc"
	printf 'SPM emergency kit\nactivation=%s\ncreated=%s\nnotice=Activation is advisory; offline recipients can decrypt early.\nfiles=key.enc,payload.enc,payload.hmac\n' "$activation" "$(now_iso)" > "$kit_dir/manifest.txt"
	python3 - "$key_file" "$kit_dir/manifest.txt" "$kit_dir/payload.enc" "$kit_dir/payload.hmac" <<'PY'
import hashlib,hmac,sys
key=bytes.fromhex(open(sys.argv[1],encoding="ascii").read().strip())
data=open(sys.argv[2],"rb").read()+open(sys.argv[3],"rb").read()
open(sys.argv[4],"w",encoding="ascii").write(hmac.new(key,data,hashlib.sha256).hexdigest()+"\n")
PY
	chmod 600 "$kit_dir"/*; tar -czf "$output" -C "$kit_dir" manifest.txt key.enc payload.enc payload.hmac
	chmod 600 "$output" 2>/dev/null || true; secure_wipe "$tmp"; secure_wipe "$payload"; secure_wipe "$key_file"; secure_wipe "$kit_dir/key.enc"; secure_wipe "$kit_dir/payload.enc"; secure_wipe "$kit_dir/payload.hmac"; secure_wipe "$kit_dir/manifest.txt"; rmdir "$kit_dir"
	printf '%s\n' "$output"
}

cmd_emergency_open() {
	local archive="${1:-}" private_key="${2:-}" output="${3:-./spm-emergency-record.json}" manifest activation activation_epoch now key_file plain_key payload_file hmac_file manifest_file
	if [ ! -f "$archive" ] || [ ! -f "$private_key" ]; then
		die "Usage: $0 emergency-open <archive> <private.pem> [output.json]"
	fi
	[ ! -e "$output" ] || die "Output file already exists."
	manifest="$(tar -xOf "$archive" manifest.txt 2>/dev/null)" || die "Invalid emergency archive."
	activation="$(printf '%s\n' "$manifest" | awk -F= '$1=="activation"{print $2;exit}')"
	activation_epoch="$(python3 - "$activation" <<'PY'
import datetime,sys
print(int(datetime.datetime.combine(datetime.date.fromisoformat(sys.argv[1]),datetime.time(),tzinfo=datetime.timezone.utc).timestamp()))
PY
)" || die "Invalid emergency activation date."
	now="$(date +%s)"; [ "$now" -ge "$activation_epoch" ] || die "Emergency kit is scheduled for $activation."
	key_file="$(make_tmp)"; plain_key="$(make_tmp)"; payload_file="$(make_tmp)"; hmac_file="$(make_tmp)"; manifest_file="$(make_tmp)"
	printf '%s\n' "$manifest" > "$manifest_file"
	tar -xOf "$archive" key.enc > "$key_file" 2>/dev/null || die "Emergency key payload missing."
	tar -xOf "$archive" payload.enc > "$payload_file" 2>/dev/null || die "Emergency record payload missing."
	tar -xOf "$archive" payload.hmac > "$hmac_file" 2>/dev/null || die "Emergency integrity tag missing."
	openssl pkeyutl -decrypt -inkey "$private_key" -pkeyopt rsa_padding_mode:oaep -pkeyopt rsa_oaep_md:sha256 -in "$key_file" -out "$plain_key" || die "Emergency private key does not match."
	python3 - "$plain_key" "$manifest_file" "$payload_file" "$hmac_file" <<'PY'
import hashlib,hmac,sys
key=bytes.fromhex(open(sys.argv[1],encoding="ascii").read().strip())
data=open(sys.argv[2],"rb").read()+open(sys.argv[3],"rb").read()
expected=open(sys.argv[4],encoding="ascii").read().strip()
if not hmac.compare_digest(hmac.new(key,data,hashlib.sha256).hexdigest(),expected):
 raise SystemExit("emergency kit authentication failed")
PY
	openssl enc -d -aes-256-cbc -pbkdf2 -iter 200000 -pass file:"$plain_key" -in "$payload_file" -out "$output" || { secure_wipe "$output"; die "Emergency payload decryption failed."; }
	chmod 600 "$output" 2>/dev/null || true; secure_wipe "$key_file"; secure_wipe "$plain_key"; secure_wipe "$payload_file"; secure_wipe "$hmac_file"; secure_wipe "$manifest_file"; printf '%s\n' "$output"
}

cmd_bridge_get() {
	local id="${1:-}" host="${2:-}" scheme="${3:-}" tmp
	printf '%s' "$id" | grep -Eq '^[0-9]+$' || die "Numeric record ID required."
	[ -n "$host" ] || die "Browser hostname required."
	IFS= read -r MASTER_PW || die "Master password required on stdin."
	tmp="$(make_tmp)"; decrypt_vault_to_file "$tmp"
	local status=0
	# The matching lives in the trusted core. It used to live here, inline,
	# and again in cmd_bridge_list -- two copies of the rule that decides
	# whether a web page may see a credential.
	python3 "$(core_script_path)" bridge-get "$tmp" "$id" "$host" "$scheme" || status=$?
	secure_wipe "$tmp"; MASTER_PW=""
	# Report the helper's status rather than the cleanup's. As a command,
	# `spm bridge-get` already exited non-zero on a refusal because errexit
	# aborted here; called as a shell function inside an `if`, errexit is
	# suppressed and the old ending returned the status of MASTER_PW="",
	# i.e. success, for a record bound to a different hostname. Capturing it
	# explicitly makes both callers agree and keeps the wipe unconditional.
	return "$status"
}

cmd_bridge_list() {
	local host="${1:-}" scheme="${2:-}" tmp
	[ -n "$host" ] || die "Browser hostname required."
	IFS= read -r MASTER_PW || die "Master password required on stdin."
	tmp="$(make_tmp)"; decrypt_vault_to_file "$tmp"
	local status=0
	python3 "$(core_script_path)" bridge-list "$tmp" "$host" "$scheme" || status=$?
	secure_wipe "$tmp"; MASTER_PW=""
	return "$status"
}

cmd_help() {
	print_banner

	if [ "$SPM_LANG" = "id" ]; then
		cat <<EOF
[ID] Panduan Singkat
