        "unlock.empty_sub": "\u0633\u062c\u0651\u0644 \u062c\u0647\u0627\u0632\u064b\u0627 \u0641\u064a \u0627\u0644\u0623\u0633\u0641\u0644\u060c \u0623\u0648 \u0648\u0627\u0635\u0644 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629",
        "unlock.field.label": "\u0627\u0633\u0645 \u0647\u0630\u0627 \u0627\u0644\u062c\u0647\u0627\u0632",
        "unlock.register": "\u062a\u0633\u062c\u064a\u0644 \u0647\u0630\u0627 \u0627\u0644\u062c\u0647\u0627\u0632",
        "unlock.note": "\u062a\u0628\u0642\u0649 \u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629 \u0645\u0637\u0644\u0648\u0628\u0629 \u0639\u0646\u062f \u0623\u0648\u0644 \u062a\u0633\u062c\u064a\u0644 \u062f\u062e\u0648\u0644\u060c \u0648\u0639\u0646\u062f\u0645\u0627 \u062a\u0628\u0644\u063a \u0627\u0644\u062c\u0644\u0633\u0629 \u0623\u0642\u0635\u0649 \u0639\u0645\u0631 \u0644\u0647\u0627\u060c \u0648\u0643\u0644\u0645\u0627 \u0628\u0642\u064a\u062a \u062c\u0644\u0633\u0629 \u0645\u0642\u0641\u0644\u0629 \u062f\u0648\u0646 \u0627\u0633\u062a\u0626\u0646\u0627\u0641 \u0645\u062f\u0629 \u0637\u0648\u064a\u0644\u0629.",
        "unlock.title": "\u0627\u0644\u062e\u0632\u0646\u0629 \u0645\u0642\u0641\u0644\u0629",
