        "entry.field.folder": "\ud3f4\ub354",
        "entry.hint.folder": "\uc120\ud0dd \uc0ac\ud56d. \uc0c8 \uc774\ub984\uc744 \uc785\ub825\ud558\uba74 \ud3f4\ub354\uac00 \ub9cc\ub4e4\uc5b4\uc9d1\ub2c8\ub2e4.",
        "entry.field.custom": "\uc0ac\uc6a9\uc790 \uc9c0\uc815 \ud544\ub4dc",
