        "entry.field.custom_value": "\uac12",
        "entry.field.custom_add": "\ud544\ub4dc \ucd94\uac00",
        "entry.hint.custom": "\uc774 \ud56d\ubaa9\uc5d0 \ud544\uc694\ud558\uc9c0\ub9cc \uc804\uc6a9 \uc785\ub825\ub780\uc774 \uc5c6\ub294 \ubaa8\ub4e0 \ub0b4\uc6a9. \uae08\uace0\uc5d0 \uc800\uc7a5\ub418\uba70 \ube44\ubc00\ubc88\ud638\uc640 \ub611\uac19\uc774 \uc554\ud638\ud654\ub429\ub2c8\ub2e4.",
        "view.label.folder": "\ud3f4\ub354",
        "search.folder": "\ud3f4\ub354",
        "page.events.desc": "\uc774 \uae08\uace0\uc5d0\uc11c \uc77c\uc5b4\ub09c \uc791\uc5c5\uc785\ub2c8\ub2e4. \uae08\uace0 \ubc14\uae65\uc5d0 \uae30\ub85d\ub418\uba70 \ud56d\ubaa9 \uc774\ub984, \uc0ac\uc6a9\uc790 \uc774\ub984, \ube44\ubc00 \uac12\uc740 \ub2f4\uae30\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.",
        "events.when": "\uc2dc\uac01 (UTC)",
