        "unlock.empty_sub": "\uc544\ub798\uc5d0\uc11c \ub4f1\ub85d\ud558\uac70\ub098, \uacc4\uc18d \ub9c8\uc2a4\ud130 \ube44\ubc00\ubc88\ud638\ub97c \uc0ac\uc6a9\ud558\uc138\uc694",
