# Derived from the catalogues rather than repeated beside them, so adding
# locales/<code>.json is genuinely all a translator has to do.
SUPPORTED_WEB_LANGS = set(WEB_LOCALES)
DEFAULT_WEB_LANG = "en"


def lang_direction(code):
    """`rtl` for Arabic and its neighbours, `ltr` for everything else."""
    return WEB_LOCALES.get(code, WEB_LOCALES["en"])["dir"]


def lang_options_markup(active):
    """The picker, built from the catalogues rather than repeated per page.

    A language names itself in its own script -- a reader who needs Arabic
    cannot be expected to find it listed as "Arabic". Unreviewed translations
    are marked here rather than only in the docs, because the picker is where
    somebody chooses to rely on one.
    """
    parts = []
    for code in sorted(WEB_LOCALES, key=lambda c: (c != "en", c)):
        meta = WEB_LOCALES[code]
        label = meta["name"]
        if meta["review"] == "unreviewed":
            label += " (\u03b2)"
        parts.append(
            '<option value="%s" dir="%s"%s>%s</option>' % (
                html.escape(code), html.escape(meta["dir"]),
                " selected" if code == active else "",
                html.escape(label)))
    return "".join(parts)


def catalogue_payload(active):
    """The active language, plus English because it is the fallback.

    Shipping every catalogue to every page was affordable at three languages
    and is not at twelve. The rest arrive from /locale when somebody actually
    switches.
    """
    payload = {"en": WEB_CATALOGUES["en"]}
    if active in WEB_CATALOGUES:
        payload[active] = WEB_CATALOGUES[active]
    return payload


def catalogue_json(payload):
    """JSON safe to drop inside a <script> element.

    `<` cannot appear outside a JSON string, so escaping it closes `</script>`
    without touching the structure. U+2028 and U+2029 are line terminators to a
    JavaScript parser but ordinary characters to JSON, and would otherwise end
    the statement mid-string.
    """
    return (jsonlib.dumps(payload, ensure_ascii=False)
            .replace("<", "\\u003c")
            .replace("\u2028", "\\u2028")
            .replace("\u2029", "\\u2029"))


def sanitize_lang(value):
    value = (value or "").strip().lower()
    if value in SUPPORTED_WEB_LANGS:
        return value
    return DEFAULT_WEB_LANG

# str.splitlines() breaks on eleven characters; collapsing only \t \r \n let the
# other eight split a record when it was read back, dropping the entry.
_VAULT_BREAKS = "\t\r\n\v\f\x1c\x1d\x1e\x85\u2028\u2029"

def _vf(value):
    # Vault records are TAB-delimited and line-based, so any character that
    # splitlines() honours has to be collapsed before the record is written.
    text = str(value or "")
    for ch in _VAULT_BREAKS:
        text = text.replace(ch, " ")
    return text


_URL_RE = re.compile(r"^https?://[^\s/]+", re.IGNORECASE)


def _vurl(value):
    """Sanitise a URL field; None means "present but unusable".

    The scheme is an allowlist, not a denylist. This value is rendered as an
    href on the entry page and will be handed to the browser extension as a
    match target, so "javascript:" or "data:" here is code execution and an
    exfiltration path rather than merely a bad link. Empty is always valid --
    the field is optional. None is distinct from "" so the form can say why it
    rejected the input instead of silently blanking it.
    """
    text = _vf(value).strip()
    if not text:
        return ""
    return text if _URL_RE.match(text) else None

def fetch_latest_version():
    now = time.time()
    if now - LATEST_CACHE.get("ts", 0) < 300 and LATEST_CACHE.get("value"):
        return LATEST_CACHE["value"]
    try:
        req = urllib.request.Request(
            "https://api.github.com/repos/sansyourways/Sans_Password_Manager/releases/latest",
            headers={"Accept": "application/vnd.github+json", "User-Agent": "SPM"},
        )
        with urllib.request.urlopen(req, timeout=2.5) as resp:
            data = resp.read().decode("utf-8", "ignore")
        m = re.search(r'"tag_name"\\s*:\\s*"v?([^"]+)"', data)
        if m:
            LATEST_CACHE["value"] = m.group(1)
            LATEST_CACHE["ts"] = now
            return LATEST_CACHE["value"]
    except Exception:
        pass
    return ""

