I18N_SCRIPT = """
<script>
(function() {
  const DICT = __SPM_DICT__;
  const FALLBACK = "en";
  /* Every language SPM can serve, not merely the ones this page was sent.
     A page carries its own language and English; the rest arrive from /locale
     the first time somebody switches to them. */
  const SUPPORTED = __SPM_LANG_CODES__;
  const DIRECTIONS = __SPM_LANG_DIRS__;
  const REVIEWS = __SPM_LANG_REVIEWS__;
  function normalize(lang) {
    lang = (lang || "").toLowerCase();
    if (SUPPORTED.includes(lang)) return lang;
    return FALLBACK;
  }
  function lookup(key, lang) {
    const dict = DICT[normalize(lang)] || {};
    if (Object.prototype.hasOwnProperty.call(dict, key)) return dict[key];
    const fb = DICT[FALLBACK] || {};
    if (Object.prototype.hasOwnProperty.call(fb, key)) return fb[key];
    return null;
  }
  let current = normalize(window.SPM_LANG);
  function applyTranslations(lang) {
    current = normalize(lang);
    if (document.documentElement) {
      document.documentElement.setAttribute("lang", current);
      /* Arabic does not merely need different words: the sidebar, the table
         columns and every caret have to change side. Setting dir here means a
         switch mirrors the page immediately, without a reload. */
      document.documentElement.setAttribute("dir", DIRECTIONS[current] || "ltr");
    }
    if (document.body) document.body.setAttribute("data-lang", current);
    document.querySelectorAll("[data-i18n]").forEach((node) => {
      const key = node.getAttribute("data-i18n");
      const text = lookup(key, current);
      if (text !== null && text !== undefined) node.textContent = text;
    });
    document.querySelectorAll("[data-i18n-placeholder]").forEach((node) => {
      const key = node.getAttribute("data-i18n-placeholder");
      const text = lookup(key, current);
      if (text !== null && text !== undefined) node.setAttribute("placeholder", text);
    });
    /* Collapsed to a rail, a nav item's only remaining label is its tooltip.
       Leaving that untranslated would make the icon-only sidebar English-only. */
    document.querySelectorAll("[data-i18n-title]").forEach((node) => {
      const key = node.getAttribute("data-i18n-title");
      const text = lookup(key, current);
      if (text !== null && text !== undefined) node.setAttribute("title", text);
    });
    const picker = document.getElementById("lang-picker");
    if (picker) picker.value = current;
    const notice = document.getElementById("lang-notice");
    if (notice) notice.hidden = REVIEWS[current] !== "unreviewed";
  }
  function persist(lang) {
    try {
      fetch("/lang", {
        method: "POST",
        headers: {
          "Content-Type": "application/x-www-form-urlencoded",
          "X-Requested-With": "fetch"
        },
        body: "lang=" + encodeURIComponent(lang),
        credentials: "same-origin"
      }).catch(() => {});
    } catch (e) {}
  }
  function setLang(lang) {
    const normalized = normalize(lang);
    if (DICT[normalized]) {
      applyTranslations(normalized);
      persist(normalized);
      return;
    }
    /* Not shipped with this page. Fetch it, and only then repaint -- applying
       first would blank every translated element for the length of the round
       trip. If the fetch fails the page stays in the language it is already
       in, which is the one honest outcome. */
    fetch("/locale?lang=" + encodeURIComponent(normalized), {
      credentials: "same-origin",
      headers: {"X-Requested-With": "fetch"}
    }).then((response) => {
      if (!response.ok) throw new Error("locale " + response.status);
      return response.json();
    }).then((catalogue) => {
      DICT[normalized] = catalogue;
      applyTranslations(normalized);
      persist(normalized);
    }).catch(() => {
      const picker = document.getElementById("lang-picker");
      if (picker) picker.value = current;
    });
  }
  document.addEventListener("DOMContentLoaded", () => {
    applyTranslations(current);
    const picker = document.getElementById("lang-picker");
    if (picker) {
      picker.value = current;
      picker.addEventListener("change", () => setLang(picker.value));
    }
  });
  window.SPM_I18N = {
    dict: DICT,
    t: function(key, fallback) {
      const text = lookup(key, current);
      if (text !== null && text !== undefined) return text;
      return fallback !== undefined ? fallback : key;
    },
    setLang: setLang,
    getLang: function() { return current; },
    apply: applyTranslations
  };
})();

// Inline handlers were removed so the CSP no longer needs 'unsafe-inline'.
// One delegated listener covers every control, including markup added later.
(function () {
  document.addEventListener("click", function (ev) {
    // WebKit can report an SVG <use> (and older builds occasionally a text
    // node) as the tap target. Those targets do not reliably implement
    // Element.closest(), so walk to an Element before delegating actions.
    var target = ev.target;
    if (target && target.nodeType !== 1) target = target.parentElement;
    const el = target && target.closest ? target.closest("[data-act]") : null;
    if (!el) return;
    const act = el.getAttribute("data-act");
    const id = el.getAttribute("data-target");
    const node = id ? document.getElementById(id) : null;
    if (act === "reveal") { if (window.SPM_reveal) SPM_reveal(id, el); }
    /* Password boxes toggle their own type. Handled here rather than in the
       view-page reveal script because the login form is the one page that
       does not load that script, and it is the box people most want to see. */
    if (act === "reveal-input") {
      var field = document.getElementById(el.getAttribute("data-target"));
      if (field) {
        var show = field.type === "password";
        field.type = show ? "text" : "password";
        el.setAttribute("aria-pressed", show ? "true" : "false");
        el.setAttribute("aria-label", show
          ? ((window.SPM_I18N && SPM_I18N.t) ? SPM_I18N.t("btn.hide", "Hide") : "Hide")
          : ((window.SPM_I18N && SPM_I18N.t) ? SPM_I18N.t("btn.show", "Show") : "Show"));
        var use = el.querySelector("use");
        if (use) use.setAttribute("href", show ? "#i-hide" : "#i-view");
        /* Keep the caret where it was: flipping type moves it to the end in
           some browsers, which is maddening mid-password. */
        try {
          var at = field.selectionStart;
          field.focus();
          if (at !== null) field.setSelectionRange(at, at);
        } catch (e) { field.focus(); }
        /* Showing a password is activity, and it should not be the moment the
           idle lock decides nothing has happened. */
        if (show && window.SPM_AutoLock) window.SPM_AutoLock.restart();
      }
    }
    else if (act === "copy-val") { if (node && window.SPM_copy) SPM_copy(node.dataset.val); }
    else if (act === "copy-text") { if (node && window.SPM_copy) SPM_copy(node.textContent); }
    else if (act === "regen") { if (window.SPM_regen) SPM_regen(); }
    else if (act === "copy-pw") { if (window.SPM_copyPw) SPM_copyPw(); }
    else return;
    ev.preventDefault();
  });
  document.addEventListener("submit", function (ev) {
    const form = ev.target.closest("form[data-confirm-key]");
    if (!form) return;
    const key = form.getAttribute("data-confirm-key");
    const fallback = form.getAttribute("data-confirm-text") || "";
    const text = window.SPM_I18N ? SPM_I18N.t(key, fallback) : fallback;
    if (!confirm(text)) ev.preventDefault();
  });
})();
</script>
"""

DESIGN_CSS = """
<style>
/* ============================================================
   SPM design system - one stylesheet for every page.
   Tokens first, then primitives, then components, then layout.
   Console is intentionally dark-only. Components consume semantic
   action, emitted-value, state, surface, and text roles.
   ============================================================ */
*, *::before, *::after { box-sizing: border-box; }

:root {
  --sp-1: 4px;  --sp-2: 8px;  --sp-3: 12px; --sp-4: 16px;
  --sp-5: 24px; --sp-6: 32px; --sp-7: 48px;
  --r-sm: 8px; --r-md: 12px; --r-lg: 16px; --r-full: 999px;
  --fs-xs: 11px; --fs-sm: 12px; --fs-md: 13px; --fs-base: 14px;
  --fs-lg: 16px; --fs-xl: 20px; --fs-2xl: 26px; --fs-3xl: 34px;
  --sidebar-w: 260px;
  --topbar-h: 60px;
  --font: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Noto Sans", sans-serif;
  --mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, "Liberation Mono", monospace;
  --ease: cubic-bezier(.4, 0, .2, 1);
  --motion-instant: 80ms;
  --motion-fast: 140ms;
  --motion-base: 200ms;
  --motion-live: 320ms;
  /* A07 durations. Exits are faster than entrances on purpose: a departing
     surface has already been decided about, and equal timings make dismissal
     feel sticky. --motion-reveal fires once per element, ever; --motion-ambient
     is reserved for state that is genuinely live. */
  --motion-slow: 320ms;
  --motion-reveal: 500ms;
  --motion-ambient: 8s;
  --motion-tick: 950ms;
  --stagger: 40ms;
  --ease-entrance: cubic-bezier(.2, .7, .3, 1);
  --ease-exit: cubic-bezier(.4, 0, 1, 1);
  --rail-w: 68px;
}

/* ---- Theme: dark (default) ---- */
body, body.theme-dark {
  --bg:        #0d1017;
  --bg-grad:   radial-gradient(1200px 600px at 15% -10%, #1b2540 0%, transparent 60%), #0d1017;
  --surface:   #151a24;
  --surface-2: #1c2230;
  --surface-3: #232b3b;
  --border:    #262e3d;
