        ("generator", "/generator", "generator", "nav.generator", "Generator",       None),
        ("transfer",  "/transfer",  "transfer", "nav.transfer",  "Export / Import", None),
    ]),
    ("nav.group.settings", [
        ("settings", "/settings", "gear", "nav.settings", "Settings", None),
    ]),
]


def _nav_html(active, counts):
    out = []
    for group_key, items in NAV_SECTIONS:
        label = {"nav.group.vault": "Vault", "nav.group.tools": "Tools",
                 "nav.group.settings": "Settings"}[group_key]
        out.append(f'<div class="nav-label" data-i18n="{group_key}">{label}</div>')
        # A nav landmark, not a div: this is how a screen-reader user jumps
        # straight to the navigation instead of walking the page.
        out.append('<nav class="nav" aria-label="%s">' % label)
        for key, href, ico, i18n, fallback, counter in items:
            cls = "nav-item active" if key == active else "nav-item"
            badge = ""
            if counter is not None:
                n = counts.get(counter, 0)
                if n:
                    badge = f'<span class="nav-count">{n}</span>'
            out.append(
                f'<a class="{cls}" href="{href}" title="{html.escape(fallback)}" '
                f'data-i18n-title="{i18n}">'
                f'<span class="nav-ico" aria-hidden="true">{_icon(ico)}</span>'
                f'<span class="nav-text" data-i18n="{i18n}">{fallback}</span>{badge}</a>'
            )
        out.append("</nav>")
    return "".join(out)


RAIL_BOOTSTRAP = """
<script>
/* Runs inline, immediately after <body> opens, because reading the
   preference in DOMContentLoaded paints the sidebar expanded and then snaps
   it to the rail -- which reads as the page glitching rather than as a
   remembered setting. Any storage failure leaves the sidebar expanded,
   which is the state that needs no explanation. */
(function () {
  try {
    if (localStorage.getItem("spm.rail") === "1" &&
        window.matchMedia && window.matchMedia("(min-width: 901px)").matches) {
      document.body.classList.add("rail");
    }
  } catch (e) {}
})();
</script>
"""


THEME_BOOTSTRAP = """
<script>
/* Theme preference is device-local and contains no vault data. Resolve it
   immediately after <body> opens to avoid painting the default before the
   saved theme. A blocked storage API safely leaves Console active. */
(function () {
  var allowed = ["sundial", "console", "cyberpunk", "edgerunner"];
  try {
    var saved = localStorage.getItem("spm.theme") || "console";
    if (allowed.indexOf(saved) < 0) saved = "console";
    document.body.className = document.body.className.replace(/theme-[^\\s]+/g, "").trim();
    document.body.classList.add("theme-" + saved);
  } catch (e) {}
})();
</script>
"""


LANG_BOOTSTRAP = """
<script>
/* Resolve language from the cookie on the client. Keeping it out of the
   server response means no request-scoped state has to be threaded through
   every template - which matters because the server is threaded. */
window.SPM_LANG = (function () {
  var m = document.cookie.match(/(?:^|;\\s*)spm_lang=([^;]*)/);
  var v = m ? decodeURIComponent(m[1]) : "en";
  return __SPM_LANG_CODES__.indexOf(v) >= 0 ? v : "en";
})();
</script>
"""


def render_shell(content, active, version, vault_path, title="Sans Password Manager",
                 counts=None, flash="", searchable=False):
    """Wrap page content in the shared app shell (sidebar + topbar)."""
    counts = counts or {}
    search_html = ""
    if searchable:
        # A GET form, so typing still filters the current table instantly and
        # Enter escalates to the cross-type search. No JS is required for the
        # escalation, which keeps it working if a script is ever blocked.
        search_html = (
            '<form class="search" method="get" action="/search" role="search">'
            f'<span class="search-ico" aria-hidden="true">{_icon("search", "icon icon-sm")}</span>'
            '<label class="sr-only" for="q" data-i18n="search.label">Search this vault</label>'
            '<input id="q" name="q" type="search" autocomplete="off" spellcheck="false" '
            'data-i18n-placeholder="search.placeholder" placeholder="Search this vault...">'
            '<kbd>/</kbd></form>'
        )
    else:
        search_html = '<div class="search" aria-hidden="true"></div>'

    return f"""<!doctype html>
<html lang="__LANG__" dir="__SPM_DIR__">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<meta name="robots" content="noindex, nofollow">
<title>{html.escape(title)} · SPM</title>
{HEAD_ICONS}
{DESIGN_CSS}
</head>
<body class="theme-console">
{THEME_BOOTSTRAP}
{RAIL_BOOTSTRAP}
{ICON_SPRITE}
<a class="skip-link" href="#main-content">Skip to vault content</a>
<div class="scrim" aria-hidden="true"></div>
<div class="app">
  <aside class="sidebar" id="mobile-navigation" aria-label="Main">
    <div class="brand">
      <div class="brand-mark" aria-hidden="true">{_icon("brand")}</div>
      <div class="brand-text">
        <div class="brand-name">SPM</div>
        <div class="brand-meta">v{html.escape(version)}</div>
      </div>
    </div>
    {_nav_html(active, counts)}
    <div class="sidebar-foot">
      <div class="vault-chip" title="{html.escape(vault_path)}">
        <span class="dot" aria-hidden="true"></span>
        <span class="path">{html.escape(vault_path)}</span>
      </div>
      <a class="btn btn-ghost btn-sm btn-block" href="/logout"
         title="Logout" data-i18n-title="header.logout">
        {_icon("logout", "icon icon-sm")}
        <span class="rail-label" data-i18n="header.logout">Logout</span>
      </a>
    </div>
  </aside>

  <div class="main">
    <header class="topbar">
      <button class="icon-btn menu-btn" type="button" aria-label="Menu"
        aria-controls="mobile-navigation" aria-expanded="false">{_icon("menu", "icon icon-sm")}</button>
      {search_html}
      <div class="topbar-right">
        <div class="lockbar" id="lockbar" title="Idle auto-lock">
          <span class="lbl" aria-live="off">Locks in 30s</span>
          <span class="track"><span class="fill"></span></span>
        </div>
        <select class="select" id="lang-picker" aria-label="Language">
          __SPM_LANG_OPTIONS__
        </select>
        <span class="faint lang-notice" id="lang-notice" data-i18n="lang.unreviewed" hidden></span>
      </div>
    </header>

    <main class="content" id="main-content" tabindex="-1">
      {flash}
      {content}
    </main>
  </div>
</div>
<div id="toast" role="status" aria-live="polite"></div>
{LANG_BOOTSTRAP}
{I18N_SCRIPT}
{SHELL_SCRIPT}
{UNLOCK_BOOTSTRAP}
{LOCKBAR_SCRIPT}
</body>
</html>"""


def _esc(v):
    return html.escape(v if v is not None else "")


def _empty(icon, title_key, title, desc_key, desc, cta_html="", colspan=4):
    return (
        f'<tr class="empty-row"><td colspan="{colspan}">'
        f'<div class="empty"><div class="empty-ico" aria-hidden="true">{_icon(icon, "icon icon-lg")}</div>'
        f'<div class="empty-t" data-i18n="{title_key}">{title}</div>'
        f'<div class="empty-d" data-i18n="{desc_key}">{desc}</div>{cta_html}</div>'
        f'</td></tr>'
    )


def _actions(view_href, edit_href, delete_action, item_id, confirm_key, confirm_text):
    bits = ['<div class="icon-row">']
    if view_href:
        bits.append(f'<a class="icon-btn" href="{view_href}" title="View" aria-label="View">{_icon("view", "icon icon-sm")}</a>')
    if edit_href:
        bits.append(f'<a class="icon-btn" href="{edit_href}" title="Edit" aria-label="Edit">{_icon("edit", "icon icon-sm")}</a>')
    if delete_action:
        bits.append(
            f'<form class="inline" method="post" action="{delete_action}" '
            f'data-confirm-key="{confirm_key}" data-confirm-text="{html.escape(confirm_text, quote=True)}">'
            f'<input type="hidden" name="id" value="{item_id}">'
            f'<button type="submit" class="icon-btn danger" title="Delete" aria-label="Delete">{_icon("trash", "icon icon-sm")}</button>'
            f'</form>'
        )
    bits.append("</div>")
    return "".join(bits)


# --------------------------------------------------------------------------
# Row builders  (each row carries data-row for the instant client-side filter)
# --------------------------------------------------------------------------
def tidy_page(proposals, total):
    """Review what a bulk tidy would do, one row at a time.

    Every proposed name is an input rather than a fact. No rule gets both
    com.lsdroid.cerberuss and com.spotify.music right, so the guess is offered
    for correction rather than applied on the strength of being plausible.
    The folder is shown but not editable: it is read from the record's own
    notes, which is not a guess.
    """
    rows = []
    for item in proposals:
        changes = item["changes"]
        label = changes.get("label")
        folder = changes.get("folder")
        record_id = _esc(item["id"])
        if label:
            name_cell = (
                '<div class="faint mono">%s</div>'
                '<input class="input" name="label_%s" value="%s" maxlength="200" '
                'aria-label="New name for record %s">'
                % (_esc(label["from"]), record_id, _esc(label["to"]), record_id))
        else:
            name_cell = '<span class="faint">%s</span>' % _esc(item["label"])
        folder_cell = ('<span class="chip">%s</span>' % _esc(folder["to"])
                       if folder else '<span class="faint">&mdash;</span>')
        # Its own checkbox, not a chip. Hiding an entry is a separate decision
        # from renaming it, and a row that proposed both would otherwise make
        # accepting one mean accepting the other.
        if changes.get("hidden"):
            hidden_cell = (
                '<label class="switch"><input type="checkbox" name="hide_%s" '
                'value="1" checked><span data-i18n="tidy.hide">Hide</span></label>'
                % record_id)
        else:
            hidden_cell = '<span class="faint">&mdash;</span>'
        rows.append(
            '<tr data-row><td class="num">%s</td>'
            '<td><label class="sr-only" for="pick_%s">Include</label>'
            '<input type="checkbox" id="pick_%s" name="pick" value="%s" checked></td>'
            '<td>%s</td><td>%s</td><td>%s</td></tr>'
            % (record_id, record_id, record_id, record_id, name_cell,
               folder_cell, hidden_cell))

    return """
<div class="page-head">
  <div>
    <h2 class="page-title" data-i18n="tidy.title">Tidy imported entries</h2>
    <div class="page-sub" data-i18n="tidy.desc">Nothing has been changed yet. Review every row, correct any name, and apply.</div>
  </div>
</div>
<form method="post" action="/tidy">
<div class="card">
  <div class="card-head">
    <strong><span>%d</span> <span data-i18n="tidy.of">of</span> <span>%d</span> <span data-i18n="tidy.entries_affected">entries would change</span></strong>
  </div>
  <div class="table-wrap"><table class="t">
    <thead><tr>
      <th scope="col" class="num" data-i18n="table.id">ID</th>
      <th scope="col" data-i18n="tidy.include">Apply</th>
      <th scope="col" data-i18n="tidy.name">Name</th>
      <th scope="col" data-i18n="tidy.folder">Folder</th>
      <th scope="col" data-i18n="tidy.hidden">Hidden</th>
    </tr></thead>
    <tbody>%s</tbody>
  </table></div>
  <div class="card-foot">
    <button class="btn btn-primary" type="submit" data-i18n="tidy.apply">Apply to selected</button>
    <a class="btn btn-ghost" href="/passwords" data-i18n="tidy.cancel">Cancel</a>
    <span class="faint" data-i18n="tidy.note">The original identifier is kept in the entry's notes. Hiding keeps a name out of the password list, not out of the vault. The vault is archived before anything is written.</span>
  </div>
</div>
</form>""" % (len(proposals), total, "".join(rows))


def tidy_empty_page():
    return """
<div class="page-head">
  <div>
    <h2 class="page-title" data-i18n="tidy.title">Tidy imported entries</h2>
  </div>
</div>
<div class="card"><div class="empty">
  <div class="empty-t" data-i18n="tidy.none_t">Nothing to tidy</div>
  <div class="empty-d" data-i18n="tidy.none_d">No entry has a folder marker in its notes or a package-style name.</div>
  <a class="btn btn-primary" href="/passwords" data-i18n="form.back_list">&larr; Back to list</a>
</div></div>"""


# What a hidden entry shows instead of its name. Rendered by the server, not
# by CSS: a blur would leave the name in the page source, which is a promise
# the page does not keep.
REDACTED = "&bull;" * 8


def build_rows_html(entries, filtered=False, reveal_hidden=False):
    if not entries:
        if filtered:
            return _empty("search", "empty.filtered.t",
                          "No passwords match these filters",
                          "empty.filtered.d",
                          "Clear the filters or choose a different folder or tag.",
                          '<a class="btn btn-ghost btn-sm" href="/passwords" '
                          'data-i18n="filters.clear">Clear filters</a>', 4)
        return _empty("key", "empty.passwords.t", "No passwords yet",
                      "empty.passwords.d", "Entries you add will appear here.",
                      '<a class="btn btn-primary btn-sm" href="/add" data-i18n="btn.add_entry">+ Add Entry</a>', 4)
    rows = []
    now = time.time()
    limit = rotation_days()
    for _, parts in entries:
        eid, name, user = _esc(parts[0]), _esc(parts[1]), _esc(parts[2])
        tags = entry_tags(parts)
        folder, _, hidden = core.decode_attrs(parts[7] if len(parts) > 7 else "")
        # The username goes too. It is usually an email address, which names
        # the service as surely as the service name does.
        redacted = hidden and not reveal_hidden
        if redacted:
            name, user = REDACTED, REDACTED
        # Tags join the filter key so the existing instant filter matches them
        # without a second mechanism.
        # A redacted row is not searchable by the name it is not showing.
        # Typing a hidden entry's name into the instant filter and watching one
        # row survive would undo, on the same page, the redaction that page had
        # just performed.
        key = " ".join([f"{name} {user} {eid}".lower()] + ["#" + t for t in tags])
        # Display only -- the clickable chips live in the tag bar above the
        # table, which is the single control that drives filtering.
        folder_chip = (f'<span class="chip">{_esc(folder)}</span>' if folder else "")
        hidden_chip = ('<span class="chip chip-hidden" data-i18n="badge.hidden">'
                       'hidden</span>' if hidden else "")
        chips = folder_chip + hidden_chip + "".join(
            f'<span class="chip">#{_esc(t)}</span>' for t in tags)
        age = _entry_age_days(parts[5] if len(parts) > 5 else "", now)
        aging = ('<span class="chip chip-warn" data-i18n="badge.aging">rotate</span>'
                 if age is not None and age > limit else "")
        rows.append(
            f'<tr data-row="{key}">'
            f'<td class="num">{eid}</td>'
            f'<td class="strong">{name} {aging}{chips}</td>'
            f'<td class="muted">{user or "&mdash;"}</td>'
            f'<td class="actions">{_actions(f"/view?id={eid}", f"/edit?id={eid}", "/delete", eid, "confirm.delete_entry", "Delete this entry?")}</td>'
            f'</tr>'
        )
    return "".join(rows)


def password_filter_state(entries, query):
    """Canonical filter values and matching password rows.

    Folder and tag names are derived only from the decrypted vault already in
    this request. Unknown query values are ignored, so a crafted URL cannot
    manufacture labels in the page. Values in one facet are ORed; the folder
    and tag facets are ANDed together.
    """
    folders = {}
    tags = set()
    has_unfiled = False
    has_hidden = False
    indexed = []
    for entry in entries:
        parts = entry[1]
        folder, _, hidden = core.decode_attrs(parts[7] if len(parts) > 7 else "")
        if folder:
            folders.setdefault(folder.casefold(), folder)
        else:
            has_unfiled = True
        has_hidden = has_hidden or hidden
        row_tags = set(entry_tags(parts))
        tags.update(row_tags)
        indexed.append((entry, folder, row_tags, hidden))

    selected_folders = []
    for raw in query.get("folder", []):
        key = raw.casefold()
        if key == "__unfiled__" and has_unfiled:
            value = "__unfiled__"
        elif key == "__hidden__" and has_hidden:
            # Hidden rides the folder facet rather than getting one of its own.
            # It behaves like a folder -- one more thing to select -- and it is
            # the only way to see these names, which is what makes revealing
            # them a deliberate act rather than a side effect.
            value = "__hidden__"
        else:
            value = folders.get(key)
        if value and value not in selected_folders:
            selected_folders.append(value)
    selected_tags = []
    for raw in query.get("tag", []):
        value = raw.casefold().lstrip("#")
        if value in tags and value not in selected_tags:
            selected_tags.append(value)

    selected_folder_keys = {v.casefold() for v in selected_folders}
    matched = []
    for entry, folder, row_tags, hidden in indexed:
        folder_key = folder.casefold() if folder else "__unfiled__"
        folder_hit = (not selected_folder_keys
                      or folder_key in selected_folder_keys
                      or (hidden and "__hidden__" in selected_folder_keys))
        tag_hit = not selected_tags or bool(row_tags.intersection(selected_tags))
        if folder_hit and tag_hit:
            matched.append(entry)
    available_folders = [folders[k] for k in sorted(folders)]
    if has_unfiled:
        available_folders.append("__unfiled__")
    if has_hidden:
        available_folders.append("__hidden__")
    return available_folders, sorted(tags), selected_folders, selected_tags, matched


def build_password_filters_html(folders, tags, selected_folders, selected_tags,
                                shown, total):
    """Theme-neutral, URL-backed folder and tag filter panel."""
    def href(next_folders, next_tags):
        pairs = ([('folder', value) for value in next_folders] +
                 [('tag', value) for value in next_tags])
        suffix = urllib.parse.urlencode(pairs)
        return "/passwords" + (("?" + suffix) if suffix else "")

    def option(value, label, facet, selected, i18n=""):
        next_values = list(selected)
        if value in next_values:
            next_values.remove(value)
        else:
            next_values.append(value)
        target = href(next_values, selected_tags) if facet == "folder" else href(selected_folders, next_values)
        active = value in selected
        key = f' data-i18n="{i18n}"' if i18n else ""
        current = ' aria-current="true"' if active else ""
        cls = "chip chip-btn filter-option" + (" chip-on" if active else "")
        return (f'<a class="{cls}" href="{_esc(target)}"{current}{key}>'
                f'{_esc(label)}</a>')

    folder_options = []
    for folder in folders:
        if folder == "__unfiled__":
            folder_options.append(option(folder, "Unfiled", "folder",
                                         selected_folders, "filters.unfiled"))
        elif folder == "__hidden__":
            folder_options.append(option(folder, "Hidden", "folder",
                                         selected_folders, "filters.hidden"))
        else:
            folder_options.append(option(folder, folder, "folder", selected_folders))
    tag_options = [option(tag, "#" + tag, "tag", selected_tags) for tag in tags]
    clear = (f'<a class="btn btn-ghost btn-sm" href="/passwords" '
             f'data-i18n="filters.clear">Clear filters</a>'
             if selected_folders or selected_tags else "")
    return f"""
<section class="card filter-panel" aria-labelledby="password-filters-title">
  <div class="card-head">
    <div class="filter-panel-copy">
      <h2 id="password-filters-title" data-i18n="filters.title">Organize passwords</h2>
      <p data-i18n="filters.desc">Narrow this list by folder or tag. Active filters stay in the page address.</p>
    </div>
    {clear}
  </div>
  <div class="card-body">
    <div class="filter-groups">
      <fieldset class="filter-group">
        <legend data-i18n="filters.folders">Folders</legend>
        <div class="filter-options">{"".join(folder_options) or '<span class="faint">&mdash;</span>'}</div>
      </fieldset>
      <fieldset class="filter-group">
        <legend data-i18n="filters.tags">Tags</legend>
        <div class="filter-options">{"".join(tag_options) or '<span class="faint">&mdash;</span>'}</div>
      </fieldset>
    </div>
    <p class="filter-summary" role="status" aria-live="polite">
      <span class="num">{shown}</span> <span data-i18n="filters.of">of</span>
      <span class="num">{total}</span> <span data-i18n="filters.passwords_shown">passwords shown</span>
    </p>
  </div>
</section>"""


